<script setup lang="ts">
import { Pencil, X } from 'lucide-vue-next'
import { computed } from 'vue'
import { useI18n } from 'vue-i18n'
import { useStore } from 'vuex'
import Message, { TextMessage } from '../classes/message'

const store = useStore()
const { t } = useI18n()

const editingMessage = computed((): Message | undefined => {
  const { editingMessageId, messageMultiLists, selectedRoomId } =
    store.state.imkit
  if (!editingMessageId) return undefined
  return messageMultiLists.get(selectedRoomId)?.main?.map.get(editingMessageId)
})

const description = computed((): string => {
  if (!editingMessage.value) return ''
  if (editingMessage.value instanceof TextMessage) {
    return editingMessage.value.text.replace(/@([\w-]+)/g, (match, userId) => {
      const user = store.state.imkit.users[userId]
      return user ? `@${user.nickname}` : match
    })
  }
  return ''
})

const close = () => {
  store.commit('imkit/setState', { editingMessageId: '' })
}
</script>

<template>
  <div
    v-if="editingMessage"
    class="mb-3 flex items-center gap-2 rounded-lg bg-gray-200 p-2 dark:bg-zinc-600/80"
  >
    <Pencil :size="20" class="shrink-0 text-gray-600 dark:text-gray-200" />
    <div class="flex min-w-0 flex-col gap-1">
      <div class="text-base font-bold text-gray-600 dark:text-gray-200">
        {{ t('editMessage') }}
      </div>
      <div class="multiline-ellipsis text-xs text-gray-500 dark:text-gray-300">
        {{ description }}
      </div>
    </div>
    <div class="ml-auto flex shrink-0 gap-2">
      <X
        :size="20"
        class="h-5 w-5 cursor-pointer text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
        @click="close"
      />
    </div>
  </div>
</template>

<style scoped>
.multiline-ellipsis {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}
</style>
