import { onUnmounted, ref, watch, type ComputedRef } from 'vue'
import { MessageStatus } from '../classes/message'

interface MessageLoadingOptions {
  status: ComputedRef<MessageStatus>
  isOutgoing: ComputedRef<boolean>
  /** 延遲多久後顯示 loading (ms) */
  delay?: number
  /** 最少顯示 loading 的時間 (ms) */
  minDuration?: number
}

export function useMessageLoading(options: MessageLoadingOptions) {
  const { status, isOutgoing, delay = 1000, minDuration = 1000 } = options

  const showLoading = ref(false)
  let loadingTimeout: ReturnType<typeof setTimeout> | null = null
  let hideTimeout: ReturnType<typeof setTimeout> | null = null
  let spinnerStartTime: number | null = null

  watch(
    status,
    (newStatus) => {
      if (loadingTimeout) {
        clearTimeout(loadingTimeout)
        loadingTimeout = null
      }
      if (hideTimeout) {
        clearTimeout(hideTimeout)
        hideTimeout = null
      }

      if (newStatus !== MessageStatus.Sending) {
        if (showLoading.value && spinnerStartTime) {
          const elapsed = Date.now() - spinnerStartTime
          const remainingTime = Math.max(0, minDuration - elapsed)

          hideTimeout = setTimeout(() => {
            showLoading.value = false
            spinnerStartTime = null
            hideTimeout = null
          }, remainingTime)
        } else {
          showLoading.value = false
          spinnerStartTime = null
        }
        return
      }

      if (newStatus === MessageStatus.Sending && isOutgoing.value) {
        loadingTimeout = setTimeout(() => {
          showLoading.value = true
          spinnerStartTime = Date.now()
          loadingTimeout = null
        }, delay)
      }
    },
    { immediate: true }
  )

  onUnmounted(() => {
    if (loadingTimeout) {
      clearTimeout(loadingTimeout)
    }
    if (hideTimeout) {
      clearTimeout(hideTimeout)
    }
  })

  return {
    showLoading
  }
}
