import dayjs, { Dayjs } from 'dayjs'
import { DateTime } from 'luxon'
const toLocaleString = (
  millis: number,
  t: (str: string) => string,
  locale: string,
  now: Dayjs = dayjs()
) => {
  const dj = dayjs(millis)
  if (dj.isSame(now, 'day')) {
    return t('today')
  }
  if (dj.isSame(now.subtract(1, 'day'), 'day')) {
    return t('yesterday')
  }
  const dt = DateTime.fromMillis(millis).setLocale(locale)
  if (dj.isSame(now, 'week')) {
    return dt.toLocaleString({
      month: 'numeric',
      day: 'numeric',
      weekday: 'short'
    })
  }
  if (dj.isSame(now, 'year')) {
    return dt.toLocaleString({
      month: 'numeric',
      day: 'numeric'
    })
  }
  return dt.toLocaleString({
    month: 'numeric',
    day: 'numeric',
    year: 'numeric'
  })
}
export default toLocaleString
