import { store } from '../store/index'
export default (
  roomId: string,
  action: {
    type: string
    label: string
    uri: string
    text: string
  }
) => {
  switch (action.type) {
    case 'message': {
      const payload = {
        roomId,
        messageType: 'text',
        message: action.text
      }
      store.dispatch('imkit/sendMessage', payload)
      break
    }
    case 'uri':
      window.open(action.uri, '_blank')
      break
    default:
      console.error(`Unsupported action type: ${action.type}`)
      break
  }
}
