<script setup lang="ts">
import dayjs from 'dayjs'
import localizedFormat from 'dayjs/plugin/localizedFormat'
import { Check, Square } from 'lucide-vue-next'
import { computed } from 'vue'
import { useStore } from 'vuex'
import Room from './../../classes/room'
import AvatarView from './../AvatarView.vue'
dayjs.extend(localizedFormat)
const props = defineProps<{ source: Room }>()
const store = useStore()

const isSelected = computed(
  () => !!store.state.imkit.selectedRoomIdsForCreateFolder[props.source.id]
)
const toggleRoom = (selected: boolean) => {
  const date = new Date()
  store.commit('imkit/updateField', {
    key: 'selectedRoomIdsForCreateFolder',
    value: { [props.source.id]: selected ? date : undefined }
  })
}
</script>

<template>
  <div
    class="group relative flex min-h-11 w-full cursor-pointer items-center gap-3 rounded-md p-1 px-2 sm:hover:bg-gray-100 sm:hover:dark:bg-zinc-700"
    :class="{
      'bg-gray-100 dark:bg-zinc-700 hover:dark:bg-zinc-700': isSelected
    }"
    @click="toggleRoom(!isSelected)"
  >
    <avatar-view
      v-if="source.avatars.length === 1"
      :url="source.avatars[0].url"
      :name="source.avatars[0].name"
      class="h-[34px] w-[34px] shrink-0 rounded-xl text-base"
    />
    <div v-else class="relative h-[34px] w-[34px] shrink-0">
      <avatar-view
        :url="source.avatars[1].url"
        :name="source.avatars[1].name"
        class="rounded-10px absolute top-0 right-0 h-[26px] w-[26px] text-base"
      />
      <avatar-view
        :url="source.avatars[0].url"
        :name="source.avatars[0].name"
        :class="`rounded-10px absolute bottom-0 left-0 h-7 w-7 border-2 border-white text-xs group-hover:border-gray-100 dark:border-zinc-800 group-hover:dark:border-zinc-700 ${isSelected ? 'border-gray-100' : ''}`"
      />
    </div>
    <div class="flex w-0 min-w-0 grow flex-col text-left">
      <div
        class="overflow-hidden text-base text-ellipsis whitespace-nowrap text-gray-900 dark:text-gray-300"
      >
        {{ source.displayName }}
      </div>
    </div>
    <Check v-if="isSelected" :size="20" class="text-green-500" />
    <Square v-else :size="20" class="text-gray-400" />
  </div>
</template>

<style scoped></style>
