<script setup lang="ts">
import { ChevronDown, ChevronUp, Search, X } from 'lucide-vue-next'
import { debounce, throttle } from 'throttle-debounce'
import { computed, onMounted, ref, watch } from 'vue'
import { useStore } from 'vuex'
import { API } from '../enums/api'
import LoadingSvg from './svgs/LoadingSvg.vue'
const store = useStore()
const searchKeyword = ref('')
const index = ref(0)
const messageIds = ref<string[]>([])
const isCompositting = ref(false)
const isRequesting = ref(false)
const searchMessages = async () => {
  if (isCompositting.value) {
    return
  }
  if (searchKeyword.value) {
    isRequesting.value = true
    const {
      data: { result }
    } = await store.state.imkit.axios.post(API.Search, {
      type: ['messages', 'files'],
      room: store.state.imkit.selectedRoomId,
      keyword: searchKeyword.value
    })
    messageIds.value = (result.messages[0]?.messages ?? []) as string[]
    if (result.files[0]?.messageID) {
      messageIds.value.push(result.files[0]?.messageID)
    }

    isRequesting.value = false
    if (messageIds.value.length > 0) {
      index.value = messageIds.value.length
      await store.commit('imkit/setState', {
        messageSearchKeyword: searchKeyword.value
      })
      await store.dispatch(
        'imkit/navigateToMessage',
        messageIds.value[index.value - 1]
      )
    } else {
      index.value = 0
    }
  }
}
const changeIndex = (idx: number) => {
  if (idx > 0 && idx <= messageIds.value.length) {
    index.value = idx
    store.dispatch('imkit/navigateToMessage', messageIds.value[idx - 1])
  }
}
const throttleSearchMessages = throttle(1000, searchMessages)
const debounceSearchMessagess = debounce(500, throttleSearchMessages, {
  atBegin: false
})
const styles = computed(() => store.state.imkit.config.styles)
watch(searchKeyword, debounceSearchMessagess)
onMounted(() => {
  searchKeyword.value = store.state.imkit.messageSearchKeyword
  messageIds.value =
    store.state.imkit.searchedMessageIds.get(
      store.state.imkit.selectedRoomId
    ) ?? []
})
const close = () => {
  store.commit('imkit/setState', {
    isSearchInRoomMode: false,
    messageSearchKeyword: ''
  })
}
</script>

<template>
  <div
    class="flex h-15 items-center justify-center border-b border-solid border-gray-200 p-2 dark:border-zinc-700"
    :style="styles.chatRoomHeader"
  >
    <div
      class="relative flex grow items-center rounded-lg bg-gray-100 px-4 py-3 dark:bg-zinc-700"
    >
      <div>
        <div
          v-if="isRequesting"
          class="flex h-5 w-5 items-center justify-center"
        >
          <LoadingSvg />
        </div>
        <Search
          v-else
          :size="20"
          class="h-5 w-5 cursor-pointer text-gray-600 dark:text-gray-300"
        />
      </div>
      <input
        v-model="searchKeyword"
        class="-mr-4 ml-2 h-5 grow bg-gray-100 text-base! text-gray-900 placeholder-gray-400 outline-none dark:bg-zinc-700 dark:text-gray-100"
        :placeholder="$t('searchInConversation')"
        @compositionstart="isCompositting = true"
        @compositionend="isCompositting = false"
      />
      <div
        class="absolute top-1/2 right-2 flex -translate-y-1/2 items-center justify-center"
      >
        <template v-if="!isRequesting && searchKeyword.length > 0">
          <div
            class="mr-4 pb-0.5 text-base font-medium text-gray-500 dark:text-gray-300"
          >
            {{ index }}/{{ messageIds.length }}
          </div>
          <ChevronUp
            v-if="index > 1"
            :size="20"
            class="cursor-pointer text-gray-600 dark:text-gray-300"
            @click="changeIndex(index - 1)"
          />
          <ChevronUp v-else :size="20" class="text-gray-400" />
          <ChevronDown
            v-if="index < messageIds.length"
            :size="20"
            class="mr-4 cursor-pointer text-gray-600 dark:text-gray-300"
            @click="changeIndex(index + 1)"
          />
          <ChevronDown v-else :size="20" class="mr-4 text-gray-400" />
        </template>

        <X
          :size="20"
          class="h-5 w-5 cursor-pointer text-gray-600 dark:text-gray-300"
          @click="
            () => {
              debounceSearchMessagess.cancel({ upcomingOnly: true })
              searchKeyword = ''
              throttleSearchMessages()
              close()
            }
          "
        />
      </div>
    </div>
  </div>
</template>
