<script setup lang="ts">
import { vOnClickOutside } from '@vueuse/components'
import { onLongPress } from '@vueuse/core'
import dayjs from 'dayjs'
import isYesterday from 'dayjs/plugin/isYesterday'
import localizedFormat from 'dayjs/plugin/localizedFormat'
import {
  EyeOff,
  FolderPlus,
  FolderX,
  MoreVertical,
  Pin,
  PinOff,
  Tag,
  Trash2,
  Volume2,
  VolumeX
} from 'lucide-vue-next'
import { computed, ref } from 'vue'
import { useModal } from 'vue-final-modal'
import { useI18n } from 'vue-i18n'
import { useStore } from 'vuex'
import User from '../classes/user'
import { SearchType } from '../enums/searchType'
import Room from './../classes/room'
import Settings from './../classes/settings'
import AddToFolderModal from './AddToFolderModal.vue'
import AvatarView from './AvatarView.vue'
import DeleteRoomModal from './DeleteRoomModal.vue'
import HighlightedText from './HighlightedText.vue'
import TagsModal from './TagsModal.vue'

dayjs.extend(localizedFormat)
dayjs.extend(isYesterday)
const props = defineProps<{ source: Room }>()
const settings = computed((): Settings => store.state.imkit.config.settings)
const styles = computed(() => store.state.imkit.config.styles)
const date = computed(() => {
  let updatedAt = dayjs(props.source.updatedAt)
  if (updatedAt.isSame(dayjs(), 'day')) {
    return updatedAt.format('H:mm')
  } else if (updatedAt.isYesterday()) {
    return 'Yesterday'
  } else if (updatedAt.isSame(dayjs(), 'week')) {
    return updatedAt.format('dddd')
  } else if (updatedAt.isSame(dayjs(), 'year')) {
    return updatedAt.format('MMM D')
  }
  return updatedAt.format('ll')
})

const { t } = useI18n()
const store = useStore()
const room = computed(() => {
  return store.state.imkit.rooms[props.source.id]
})
const highlightForDisplayName = computed(() => {
  if (
    store.state.imkit.searchKeyword.length > 0 &&
    (store.state.imkit.searchType === SearchType.RoomName ||
      store.state.imkit.searchType === SearchType.RoomMember)
  ) {
    return store.state.imkit.searchKeyword
  }
  return undefined
})
const highlightForContent = computed(() => {
  if (
    store.state.imkit.searchKeyword.length > 0 &&
    (store.state.imkit.searchType === SearchType.Messages ||
      store.state.imkit.searchType === SearchType.RoomMember)
  ) {
    return store.state.imkit.searchKeyword
  }
  return undefined
})
const content = computed(() => {
  if (
    store.state.imkit.searchKeyword.length > 0 &&
    store.state.imkit.searchType === SearchType.RoomMember
  ) {
    return room.value.memberIds
      .map((id: string) => store.state.imkit.users[id])
      .filter((user: User) => user)
      .map((user: User) => user.nickname || user.id)
      .join(', ')
  }

  if (
    store.state.imkit.searchKeyword.length > 0 &&
    store.state.imkit.searchType === SearchType.Files
  ) {
    return t('foundFiles', {
      count:
        store.state.imkit.searchedMessageIds.get(props.source.id)?.length ?? 0
    })
  }

  return room.value.lastMessage?.string
})
const isSelected = computed(
  () => store.state.imkit.selectedRoomId === props.source.id
)
const isInFolder = computed(
  () => !!store.state.imkit.roomIdsInFolders[props.source.id]
)
const actionMenuRoomId = computed(() => store.state.imkit.actionMenuRoomId)
const actionMenuFolderId = computed(() => store.state.imkit.actionMenuFolderId)
const searchKeyword = computed(() => store.state.imkit.searchKeyword)
const isSticky = computed(() => room.value.pref?.sticky ?? false)
const isHidden = computed(() => room.value.pref?.hidden ?? false)
const sortedFolderIds = computed(() => store.state.imkit.sortedFolderIds)
const showTagsModal = () => {
  const { open } = useModal({
    component: TagsModal,
    attrs: {
      roomId: props.source.id
    }
  })
  open()
  store.commit('imkit/setState', { actionMenuRoomId: '' })
}
const toggleActionMenu = () => {
  if (actionMenuRoomId.value === props.source.id) {
    store.commit('imkit/setState', { actionMenuRoomId: '' })
  } else {
    store.commit('imkit/setState', { actionMenuRoomId: props.source.id })
  }
}
const selectRoom = async () => {
  if (actionMenuRoomId.value || actionMenuFolderId.value) {
    return
  }
  await store.commit('imkit/setState', {
    selectedRoomId: props.source.id,
    actionMenuRoomId: ''
  })
  const isSearchInRoomMode = !!store.state.imkit.searchKeyword
  await store.commit('imkit/setState', {
    messageSearchKeyword: isSearchInRoomMode
      ? store.state.imkit.searchKeyword
      : '',
    isSearchInRoomMode
  })
}
const toggleSticky = async () => {
  await store.dispatch('imkit/updateRoomPrefs', {
    roomId: props.source.id,
    prefs: {
      sticky: !isSticky.value
    }
  })
}
const toggleHidden = async () => {
  store.commit('imkit/setState', { actionMenuRoomId: '' })
  store.dispatch('imkit/updateRoomPrefs', {
    roomId: props.source.id,
    prefs: {
      hidden: !isHidden.value
    }
  })
}
const toggleDelete = async () => {
  const { open } = useModal({
    component: DeleteRoomModal,
    attrs: {
      roomId: props.source.id
    }
  })
  open()
}
const removeRoomFromFolder = async () => {
  await store.dispatch('imkit/removeRoomFromFolder', props.source.id)
}
const addToFolder = async () => {
  const { open } = useModal({
    component: AddToFolderModal,
    attrs: {
      roomId: props.source.id
    }
  })
  open()
}
const roomCellRef = ref<HTMLElement | null>(null)

const onLongPressCallbackHook = () => {
  toggleActionMenu()
}

onLongPress(roomCellRef, onLongPressCallbackHook, {
  modifiers: { prevent: true }
})
const roomsInSelectedFolder = computed(() => {
  return store.getters['imkit/roomsInSelectedFolder']
})
const handleClickOutside = () => {
  setTimeout(() => {
    store.commit('imkit/setState', { actionMenuRoomId: '' })
  }, 0)
}
</script>

<template>
  <div class="relative flex items-center justify-center gap-1.5 px-2 pt-2">
    <div
      v-if="isInFolder && !searchKeyword"
      class="absolute left-2 h-[120%] w-1 shrink-0 rounded-full bg-slate-500"
      :class="{
        'mt-4 h-full!': roomsInSelectedFolder[0].id === props.source.id,
        'mb-4 h-full!':
          roomsInSelectedFolder[roomsInSelectedFolder.length - 1].id ===
          props.source.id
      }"
    />
    <div
      ref="roomCellRef"
      class="group relative flex min-h-[66px] grow cursor-pointer items-center gap-3 rounded-lg p-2 select-none sm:hover:bg-gray-100 sm:hover:dark:bg-zinc-700"
      :class="{
        'bg-gray-100 dark:bg-zinc-700': isSelected,
        'ml-4': isInFolder && !searchKeyword
      }"
      @click="selectRoom"
    >
      <div class="relative h-[50px]! w-[50px]! shrink-0">
        <avatar-view
          v-if="room.avatars.length === 1"
          :url="room.avatars[0].url"
          :name="room.avatars[0].name"
          class="relative"
        />
        <template v-else>
          <avatar-view
            :url="room.avatars[1].url"
            :name="room.avatars[1].name"
            class="absolute top-0 right-0 h-9 w-9 text-base"
          />
          <avatar-view
            :url="room.avatars[0].url"
            :name="room.avatars[0].name"
            :class="`absolute bottom-0 left-0 h-[38px] w-[38px] border-2 border-white text-base group-hover:border-gray-100 dark:border-zinc-800 group-hover:dark:border-zinc-700 ${isSelected ? 'border-gray-100 dark:border-zinc-700' : ''}`"
          />
        </template>
        <div
          v-if="isSticky"
          class="absolute -right-1 -bottom-1 flex h-5 w-5 items-center justify-center rounded-lg bg-slate-200 p-[3px]"
        >
          <Pin class="h-3 w-3 text-gray-700" />
        </div>
      </div>
      <div class="flex w-0 min-w-0 grow flex-col text-left">
        <div class="flex justify-between gap-2">
          <div
            class="flex flex-1 items-center justify-center gap-1 overflow-hidden"
          >
            <div
              class="w-full overflow-hidden text-base text-ellipsis whitespace-nowrap text-gray-900 dark:text-gray-100"
            >
              <highlighted-text
                :text="room.displayName ?? ''"
                :highlight="highlightForDisplayName"
              />
            </div>
            <VolumeX
              v-if="room.muted"
              class="mt-0.5 h-3.5 w-3.5 text-gray-600 dark:text-gray-400"
            />
          </div>
          <div
            class="flex-none text-xs whitespace-nowrap text-gray-500 dark:text-gray-300"
          >
            {{ date }}
          </div>
        </div>
        <div
          v-if="settings.enableReadReceipt"
          class="flex items-center justify-between gap-2"
          :class="{ 'text-gray-800': room.numberOfUnread > 0 }"
        >
          <div
            class="overflow-hidden text-base text-ellipsis whitespace-nowrap text-gray-500 dark:text-gray-400"
          >
            <highlighted-text
              :text="content ?? ''"
              :highlight="highlightForContent"
            />
          </div>
          <div
            v-if="room.numberOfUnread > 0 && !isSelected"
            class="flex h-5 min-w-5 items-center justify-center rounded-full bg-blue-400 px-1.5 text-center text-xs leading-none font-semibold text-white"
            :style="styles.roomListUnreadBadge"
          >
            {{ room.numberOfUnread > 99 ? '99+' : room.numberOfUnread }}
          </div>
        </div>
        <div
          v-if="room.isMentioned && room.numberOfUnread > 0 && !isSelected"
          class="text-xs text-blue-500 dark:text-blue-400"
        >
          {{ $t('youWereMentioned') }}
        </div>
        <div v-if="room.pref?.tags" class="mt-1 flex flex-wrap gap-1">
          <div
            v-for="tag in room.pref?.tags ?? []"
            :key="tag"
            class="overflow-hidden rounded-md bg-blue-400 px-1 py-0.5 text-xs text-ellipsis whitespace-nowrap text-white"
            :style="{ backgroundColor: (room.pref?.tagColors || {})[tag] }"
          >
            {{ tag }}
          </div>
        </div>
        <div
          v-if="
            searchKeyword &&
            store.state.imkit.searchType === SearchType.Messages
          "
          class="text-gray-500 dark:text-gray-400"
        >
          {{
            $t('foundMessages', [
              store.state.imkit.searchedMessageIds.get(source.id)?.length ?? 0
            ])
          }}
        </div>
      </div>
      <div
        class="absolute right-4 hidden h-8 w-8 items-center justify-center rounded-full bg-white shadow-md hover:scale-110 hover:transform hover:transition sm:group-hover:flex dark:bg-zinc-800"
        :class="{ 'flex!': actionMenuRoomId == source.id }"
        @click.stop="toggleActionMenu"
      >
        <MoreVertical class="h-5 w-5 text-gray-700 dark:text-gray-300" />
      </div>
      <div
        v-if="actionMenuRoomId == source.id"
        v-on-click-outside="handleClickOutside"
        class="absolute top-[calc(50%+28px)] right-3 z-10 flex flex-col items-stretch gap-1 rounded-lg bg-white p-1.5 text-base text-gray-800 shadow-md dark:bg-zinc-800 dark:text-gray-200"
      >
        <div
          class="flex cursor-pointer items-center gap-2 rounded p-2 hover:bg-gray-100 hover:dark:bg-zinc-700"
          @click.stop="showTagsModal"
        >
          <Tag class="h-5 w-5" />
          {{ $t('tag') }}
        </div>
        <div
          class="flex cursor-pointer items-center gap-2 rounded p-2 hover:bg-gray-100 hover:dark:bg-zinc-700"
          @click.stop="toggleSticky"
        >
          <PinOff v-if="isSticky" class="h-5 w-5" />
          <Pin v-else class="h-5 w-5" />
          {{ isSticky ? $t('unpin') : $t('pin') }}
        </div>
        <div
          class="flex cursor-pointer items-center gap-2 rounded p-2 hover:bg-gray-100 hover:dark:bg-zinc-700"
          @click.stop="toggleHidden"
        >
          <EyeOff class="h-5 w-5" />
          {{ isHidden ? $t('unhide') : $t('hide') }}
        </div>
        <div
          class="flex cursor-pointer items-center gap-2 rounded p-2 hover:bg-gray-100 hover:dark:bg-zinc-700"
          @click.stop="toggleDelete"
        >
          <Trash2 class="h-5 w-5" />
          {{ $t('delete') }}
        </div>
        <div
          v-if="isInFolder"
          class="flex cursor-pointer items-center gap-2 rounded p-2 hover:bg-gray-100 hover:dark:bg-zinc-700"
          @click.stop="removeRoomFromFolder"
        >
          <FolderX class="h-5 w-5" />
          {{ $t('removeFromFolder') }}
        </div>
        <div
          v-else-if="sortedFolderIds.length > 0"
          class="flex cursor-pointer items-center gap-2 rounded p-2 hover:bg-gray-100 hover:dark:bg-zinc-700"
          @click.stop="addToFolder"
        >
          <FolderPlus class="h-5 w-5" />
          {{ $t('addToFolder') }}
        </div>
        <div
          class="flex cursor-pointer items-center gap-2 rounded p-2 hover:bg-gray-100 hover:dark:bg-zinc-700"
          @click.stop="
            () => {
              store.commit('imkit/setState', { actionMenuRoomId: '' })
              store.dispatch('imkit/toggleNotification', props.source.id)
            }
          "
        >
          <Volume2 v-if="room.muted" class="h-5 w-5" />
          <VolumeX v-else class="h-5 w-5" />
          {{ room.muted ? $t('unmute') : $t('mute') }}
        </div>
      </div>
    </div>
  </div>
</template>

<style scoped></style>
