<script setup lang="ts">
import { computed } from 'vue'
import { TemplateMessage } from './../../classes/message'
import actionHandler from './../../utils/line-action-handler'
const props = defineProps<{ message: TemplateMessage }>()
const isIncoming = computed(() => props.message.isIncoming)
const isOutgoing = computed(() => !isIncoming.value)
</script>

<template>
  <div class="w-[250px] overflow-hidden text-base">
    <div class="p-3">
      {{ message.template.text.substring(0, 240) }}
    </div>
    <div class="flex divide-x border-t">
      <div
        v-for="action in message.template.actions.slice(0, 2)"
        :key="action.label"
        class="flex grow cursor-pointer items-center justify-center p-2"
        :class="{
          'text-slate-500': isIncoming,
          'text-slate-100': isOutgoing
        }"
        @click="actionHandler(message.roomId, action)"
      >
        {{ action.label }}
      </div>
    </div>
  </div>
</template>

<style scoped></style>
