<script setup lang="ts">
import { File, X } from 'lucide-vue-next'
import { computed } from 'vue'
import { useI18n } from 'vue-i18n'
import { useStore } from 'vuex'
import IMImage from '../classes/image'
import Message, {
  FileMessage,
  ImageMessage,
  MessageType,
  MixedMessage,
  StickerMessage,
  TextMessage,
  VideoMessage
} from '../classes/message'
import User from '../classes/user'
import AvatarView from './AvatarView.vue'
import StickerMessageContent from './StickerMessageContent.vue'
const store = useStore()
const replyMessage = computed((): Message => {
  const { replyId, messageMultiLists, selectedRoomId } = store.state.imkit
  return messageMultiLists.get(selectedRoomId)?.main?.map.get(replyId)
})
const replyMessageSender = computed((): User | undefined => {
  const reply = replyMessage.value
  if (reply) {
    return store.state.imkit.users[reply.senderId]
  }
  return undefined
})
const description = computed((): string => {
  if (replyMessage.value.type === MessageType.Text) {
    return (replyMessage.value as TextMessage).string
  } else if (replyMessage.value.type === MessageType.Mixed) {
    return (replyMessage.value as MixedMessage).string
  } else if (replyMessage.value.type === MessageType.File) {
    const file = replyMessage.value as FileMessage
    return `${file.fileName}.${file.fileExtension}`
  } else if (
    replyMessage.value.type === MessageType.Image ||
    replyMessage.value.type === MessageType.Sticker ||
    replyMessage.value.type === MessageType.Video
  ) {
    const { t } = useI18n()
    const messageTypeName = {
      // [MessageType.Text]: t('text'),
      [MessageType.Image]: t('image'),
      [MessageType.Video]: t('video'),
      [MessageType.Sticker]: t('sticker')
    }
    return messageTypeName[replyMessage.value.type]
  }
  return ''
})
const image = computed((): IMImage | undefined => {
  if (replyMessage.value.type === MessageType.Image) {
    return (replyMessage.value as ImageMessage).images[0]
  }
  if (replyMessage.value.type === MessageType.Mixed) {
    return (replyMessage.value as MixedMessage).images[0]
  }
  return undefined
})

const stickerContent = computed((): StickerMessage => {
  return replyMessage.value as StickerMessage
})
const videoContent = computed((): VideoMessage => {
  return replyMessage.value as VideoMessage
})
const close = () => {
  store.commit('imkit/setState', { replyId: '' })
}
</script>

<template>
  <div
    v-if="replyMessage"
    class="mb-3 flex items-center gap-2 rounded-lg bg-gray-200 p-2 dark:bg-zinc-600"
  >
    <avatar-view
      class="row-span-2 h-7 w-7 shrink-0 rounded-lg bg-gray-300 text-base"
      :url="replyMessageSender?.avatarUrl ?? ''"
      :name="replyMessageSender?.nickname ?? ''"
    />
    <div class="flex min-w-0 flex-col gap-1">
      <div class="text-base font-bold text-gray-600 dark:text-gray-300">
        {{ replyMessageSender?.nickname }}
      </div>
      <div class="multiline-ellipsis text-xs text-gray-500 dark:text-gray-300">
        {{ description }}
      </div>
    </div>
    <div class="ml-auto flex shrink-0 gap-2">
      <div v-if="replyMessage.type === MessageType.Sticker">
        <sticker-message-content
          :class="{
            'h-[2.8rem] w-[2.8rem]': true
          }"
          :message="stickerContent"
        />
      </div>
      <div v-if="replyMessage.type === MessageType.Video">
        <img
          v-src="videoContent.video.thumbnailUrl"
          src="data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw=="
          class="h-[2.8rem] w-[2.8rem] border-0 object-contain"
        />
      </div>
      <div
        v-if="replyMessage.type === MessageType.File"
        class="flex items-center"
      >
        <File :size="28" class="text-gray-500 dark:text-gray-300" />
      </div>
      <img
        v-if="image"
        v-src="image.thumbnailUrl"
        class="h-10 w-10 rounded object-cover"
      />
      <X
        :size="20"
        class="h-5 w-5 cursor-pointer text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
        @click="close"
      />
    </div>
  </div>
</template>

<style scoped>
.multiline-ellipsis {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}
</style>
