<script setup lang="ts">
import { Play } from 'lucide-vue-next'
import { computed, ref } from 'vue'
import RadialProgress from 'vue3-radial-progress'
import { useStore } from 'vuex'
import { MessageStatus, VideoMessage } from './../classes/message'
import ContentLightboxDialog from './ui/ContentLightboxDialog.vue'

const props = defineProps<{ message: VideoMessage }>()

// Calculate explicit dimensions for stable layout
const containerSize = computed(() => {
  const { width, height } = props.message.video
  const maxSize = 400

  // Fallback to default size if dimensions are missing or invalid
  if (!width || !height || width <= 0 || height <= 0) {
    return { width: '200px', height: '112px' } // 16:9 fallback
  }

  // Scale down to fit within maxSize while maintaining aspect ratio
  if (width >= height) {
    const scaledWidth = Math.min(width, maxSize)
    const scaledHeight = (scaledWidth * height) / width
    return { width: `${scaledWidth}px`, height: `${scaledHeight}px` }
  } else {
    const scaledHeight = Math.min(height, maxSize)
    const scaledWidth = (scaledHeight * width) / height
    return { width: `${scaledWidth}px`, height: `${scaledHeight}px` }
  }
})

const store = useStore()
const uploadProgresses = computed(() => store.state.imkit.uploadProgresses)

// Lightbox state
const lightboxOpen = ref(false)

const handlePlayButtonClick = () => {
  lightboxOpen.value = true
}

const closeLightbox = () => {
  lightboxOpen.value = false
}
</script>

<template>
  <div
    class="-mx-3 -my-2 flex cursor-pointer items-center justify-center"
    :style="containerSize"
    @click="handlePlayButtonClick"
  >
    <img
      v-src="message.video.thumbnailUrl"
      src="data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw=="
      class="h-full w-full border-0 object-cover transition"
    />
    <template v-if="message.video.thumbnailUrl?.startsWith('data')">
      <div class="absolute inset-0 bg-gray-800/50 fill-blue-300" />
      <RadialProgress
        class="absolute!"
        :diameter="40"
        :completed-steps="uploadProgresses[message.video.id] * 100"
        :total-steps="100"
        :start-color="'#60a5fa'"
        :stop-color="'#60a5fa'"
        :stroke-width="4"
        :inner-stroke-width="4"
      />
      <template
        v-if="
          message.video.thumbnailUrl.startsWith('data') &&
          message.status !== MessageStatus.Failed
        "
      >
        <div class="absolute inset-0 bg-gray-800/50 fill-blue-300" />
        <RadialProgress
          class="absolute!"
          :diameter="48"
          :completed-steps="(uploadProgresses[message.video.id] ?? 0) * 100"
          :total-steps="100"
          :start-color="'#60a5fa'"
          :stop-color="'#60a5fa'"
          :stroke-width="4"
          :inner-stroke-width="4"
        >
          <span class="text-xs font-medium text-white">
            {{ Math.round((uploadProgresses[message.video.id] ?? 0) * 100) }}%
          </span>
        </RadialProgress>
      </template>
      <template v-else>
        <Play class="pointer-events-none absolute text-white" :size="24" />
        <div
          class="absolute right-2 bottom-2 rounded-full bg-black/30 px-2 py-1 text-xs font-bold text-white"
        >
          {{ Math.floor(message.video.duration / 60) }}:{{
            `${Math.floor(message.video.duration % 60)}`.padStart(2, '0')
          }}
        </div>
      </template>
    </template>
  </div>

  <ContentLightboxDialog
    :open="lightboxOpen"
    :video="message.video"
    :room-id="message.roomId"
    :sender-name="message.senderNickname"
    :created-at="message.createdAt"
    @update:open="lightboxOpen = $event"
    @close="closeLightbox"
  />
</template>

<style scoped></style>
