type CommitFn = AugmentedActionContext['commit']
type DispatchFn = AugmentedActionContext['dispatch']

async function shouldSkipByRoomTag(
  state: IMState,
  commit: CommitFn,
  dispatch: DispatchFn,
  message: Message
): Promise<boolean> {
  if (!state.roomTag) return false

  const existingRoom = state.rooms[message.roomId]
  if (existingRoom) {
    return !existingRoom.roomTags.includes(state.roomTag)
  }

  // Room not in state — check cache, then API
  const cachedTags = state.roomTagCache.get(message.roomId)
  if (cachedTags !== undefined) {
    return !cachedTags.includes(state.roomTag)
  }

  // Cache miss — fetch room to get roomTags
  await dispatch(IMActionTypes.fetchRoom, message.roomId)
  const fetchedRoom = state.rooms[message.roomId]
  if (!fetchedRoom) return true

  const tags = fetchedRoom.roomTags
  if (!tags.includes(state.roomTag)) {
    commit(IMMutationTypes.setMap, {
      mapName: 'roomTagCache',
      key: message.roomId,
      value: tags
    })
    // Use deleteField (not deleteRoom) — fetchRoom only adds to state.rooms,
    // not sortedRooms/folders/messageMultiLists, so a lightweight removal suffices.
    commit(IMMutationTypes.deleteField, {
      key: 'rooms',
      value: message.roomId
    })
    return true
  }
  return false
}

function clearTypingIfNeeded(
  state: IMState,
  commit: CommitFn,
  senderId: string
) {
  const typingTimeoutId = state.isTyping[senderId]
  if (typingTimeoutId !== undefined) {
    clearTimeout(typingTimeoutId)
    commit(IMMutationTypes.deleteField, {
      key: 'isTyping',
      value: senderId
    })
  }
}

// Per-room debounced+throttled fetchRoom for recall messages
// throttle: fires immediately on first call (leading edge), rate-limits to 1/sec
// debounce: ensures a trailing call after the burst settles
const recallFetchRoomMap = new Map<
  string,
  { throttled: () => void; debounced: () => void }
>()

function fetchRoomOnRecall(dispatch: DispatchFn, roomId: string) {
  let entry = recallFetchRoomMap.get(roomId)
  if (!entry) {
    const doFetch = async () => {
      await dispatch(IMActionTypes.fetchRoom, roomId)
      dispatch(IMActionTypes.aggregateRoomsAndFolders)
    }
    const throttled = throttle(1000, doFetch)
    const debounced = debounce(500, throttled, { atBegin: false })
    entry = { throttled, debounced }
    recallFetchRoomMap.set(roomId, entry)
  }
  entry.throttled()
  entry.debounced()
}

function pushOrReplaceMessage(
  state: IMState,
  commit: CommitFn,
  message: Message
) {
  const existing = state.messageMultiLists
    .get(message.roomId)
    ?.main?.finds(message.id)

  if (!existing) {
    commit(IMMutationTypes.pushMessage, message)
    return
  }

  // Skip AI streaming messages — they are handled by handleAIStreamingFromSocket
  if (message.type === MessageType.AIStreaming) return

  commit(IMMutationTypes.replaceMessage, {
    targetMessageId: message.id,
    message
  })
}

export const actions: ActionTree<IMState, RootState> & Actions = {
  [IMActionTypes.increment]({ commit }) {
    commit(IMMutationTypes.increment)
  },
  async [IMActionTypes.fetchRooms](
    { state, commit, dispatch },
    { pageSize } = { pageSize: undefined }
  ) {
    if (state.isRequesting[API.FetchRooms]) return
    const { numberOfFetchedRooms, uid } = state
    if (
      numberOfFetchedRooms === state.numberOfTotalRooms &&
      numberOfFetchedRooms > 0
    )
      return
    const limit =
      pageSize !== undefined
        ? pageSize
        : Math.min(Math.max(30, numberOfFetchedRooms), 120)
    const {
      data: { result }
    } = await state.axios.get(API.FetchRooms, {
      params: {
        skip: numberOfFetchedRooms,
        limit,
        q: state.roomTag
          ? `{ "members": "${uid}", "roomTags": "${state.roomTag}" }`
          : `{ "members": "${uid}" }`,
        sort: state.sortBy,
        sortUnreadFirst: state.sortUnreadFirst
      }
    })
    const { data, totalCount: numberOfTotalRooms } = result
    const rooms: { [id: string]: Room } = {}
    const users: { [uid: string]: User } = {}
    const roomsArray: Room[] = []
    for (const room of data) {
      const roomInstance = new Room(room, state.uid)
      rooms[room._id] = roomInstance
      roomsArray.push(roomInstance)
      room.members // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .flatMap((m: any) =>
          Array.isArray(m.members) ? [...m.members, m] : [m]
        )
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .forEach((m: any) => {
          if (!users[m.id]) {
            users[m.id] = new User(m)
          }
        })
    }
    commit(IMMutationTypes.updateField, { key: 'rooms', value: rooms })
    commit(IMMutationTypes.mergeUsers, users)
    commit(IMMutationTypes.setState, {
      numberOfTotalRooms,
      numberOfFetchedRooms: numberOfFetchedRooms + limit,
      sortedRooms: [...state.sortedRooms, ...roomsArray]
    })
    dispatch(IMActionTypes.aggregateRoomsAndFolders)
  },
  async [IMActionTypes.handleMessageFromSocket](
    { state, commit, dispatch },
    { message, mentions }
  ) {
    if (await shouldSkipByRoomTag(state, commit, dispatch, message)) return

    const room = state.rooms[message.roomId]
    if (!room) {
      await dispatch(IMActionTypes.fetchRoom, message.roomId)
      return
    }

    clearTypingIfNeeded(state, commit, message.senderId)

    const { id, numberOfUnread } = room
    const isSelectedRoom = message.roomId === state.selectedRoomId
    const isNewLastMessage =
      !room.lastMessage || message.createdAt >= room.lastMessage.createdAt

    if (isSelectedRoom) {
      if (state.config.settings.linkPreviewEnabled) {
        dispatch(IMActionTypes.handleLinkPreviews, [message])
      }
      await state.rwlock.withWrite(() => {
        pushOrReplaceMessage(state, commit, message)
      })
    }

    const shouldMarkAsRead =
      isSelectedRoom && (typeof document === 'undefined' || !document.hidden)

    if (shouldMarkAsRead) {
      commit(IMMutationTypes.updateRoom, {
        id,
        ...(isNewLastMessage && {
          updatedAt: message.createdAt,
          lastMessage: message
        }),
        numberOfUnread: 0,
        isMentioned: false
      } as Room)
      if (message.senderId !== state.uid) {
        dispatch(IMActionTypes.updateLastRead, id)
      }
    } else {
      commit(IMMutationTypes.updateRoom, {
        id,
        ...(isNewLastMessage && {
          updatedAt: message.createdAt,
          lastMessage: message
        }),
        numberOfUnread:
          message.senderId !== state.uid && isNewLastMessage
            ? numberOfUnread + 1
            : numberOfUnread,
        isMentioned: room.isMentioned || (mentions ?? []).includes(state.uid)
      } as Room)
    }

    if (isNewLastMessage) {
      commit(IMMutationTypes.setMap, {
        mapName: 'numberOfTotalMessages',
        key: id,
        value: (state.numberOfTotalMessages.get(id) ?? 0) + 1
      })
    }

    if (room.pref?.hidden) {
      dispatch(IMActionTypes.updateRoomPrefs, {
        roomId: id,
        prefs: { hidden: false }
      })
    }
    dispatch(IMActionTypes.aggregateRoomsAndFolders)

    // Re-fetch room on recall to sync lastMessage & numberOfUnread with server
    if (
      message.type === MessageType.Recall &&
      (isNewLastMessage || numberOfUnread > 0)
    ) {
      fetchRoomOnRecall(dispatch, id)
    }
  },
  async [IMActionTypes.loadMessages](
    { state, commit, dispatch },
    { roomId, beforeMessageId, afterMessageId, targetMessageId }
  ) {
    const path = `/rooms/${roomId}/messages/v3`
    if (state.isRequesting[path]) return
    const currentList = state.messageMultiLists.get(roomId)
    const totalMessages = state.numberOfTotalMessages.get(roomId) ?? -1
    if (
      totalMessages !== -1 &&
      (currentList?.numberOfMessages() ?? 0) >= totalMessages
    )
      return
    const DEFAULT_LIMIT = 30
    const params: Record<string, unknown> = { limit: DEFAULT_LIMIT }
    if (beforeMessageId) {
      params.beforeMessage = beforeMessageId
      params.sortOrder = 'desc'
    }
    if (afterMessageId || targetMessageId) {
      params.afterMessage = afterMessageId || targetMessageId
      params.sortOrder = 'asc'
    }
    const {
      data: { result }
    } = await state.axios.get(path, {
      params
    })
    const { data, totalCount: numberOfTotalMessages } = result
    if (afterMessageId) {
      data.shift()
    }
    if (beforeMessageId) {
      data.shift()
    }
    const users: { [uid: string]: User } = {}
    for (const message of data) {
      const sender = (message as { sender?: { _id?: string } }).sender
      const uid = sender?._id
      if (uid && !users[uid] && sender) {
        users[uid] = new User(sender)
      }
    }
    commit(IMMutationTypes.mergeUsers, users)
    const messageLinkedList = new MessageLinkedList(data)
    const messages = messageLinkedList.array()
    if (state.config.settings.linkPreviewEnabled) {
      dispatch(IMActionTypes.handleLinkPreviews, messages)
    }
    // if (state.config.translationApiKey) {
    //   const textMessages = messages.filter(
    //     (m) => m.type === MessageType.Text && m.senderId !== state.uid
    //   ) as TextMessage[]
    //   const translatedTexts = await Promise.allSettled(
    //     textMessages.map((m) => dispatch(IMActionTypes.translate, m.text))
    //   )
    //   for (let i = 0; i < textMessages.length; i++) {
    //     const translatedText = translatedTexts[i]
    //     if (
    //       translatedText.status === 'fulfilled' &&
    //       translatedText.value !== textMessages[i].text
    //     ) {
    //       textMessages[i].translatedText = TextMessage.linkfy(
    //         translatedText.value
    //       )
    //     }
    //   }
    // }
    if (beforeMessageId) {
      commit(IMMutationTypes.unshiftMessageLinkedList, messageLinkedList)
    } else if (afterMessageId) {
      commit(IMMutationTypes.concateMessageLinkedList, messageLinkedList)
    } else {
      commit(IMMutationTypes.insertMessageLinkedList, messageLinkedList)
    }
    const prevTotal = state.numberOfTotalMessages.get(roomId) ?? -1
    if (numberOfTotalMessages > prevTotal) {
      commit(IMMutationTypes.setMap, {
        mapName: 'numberOfTotalMessages',
        key: roomId,
        value: numberOfTotalMessages
      })
    }
    return data
  },
  async [IMActionTypes.fetchRoom]({ state, commit }, roomId) {
    await coalesceAsync(`fetchRoom:${roomId}`, async () => {
      const {
        data: { result }
      } = await state.axios.get(`/rooms/${roomId}`)
      const room = new Room(result, state.uid)
      const rooms: { [id: string]: Room } = {}
      rooms[room.id] = room
      commit(IMMutationTypes.updateField, { key: 'rooms', value: rooms })
      const users: { [uid: string]: User } = {}
      result.members // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .flatMap((m: any) => {
          if (Array.isArray(m.members)) {
            return [...m.members, m]
          }
          return [m]
        })
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .forEach((m: any) => {
          if (!users[m.id]) {
            users[m.id] = new User(m)
          }
        })
      commit(IMMutationTypes.mergeUsers, users)
    })
  },
  async [IMActionTypes.updateLastRead]({ state, commit }, roomId) {
    const path = `/rooms/${roomId}/lastRead`
    if (state.isRequesting[path]) return
    const room = state.rooms[roomId]
    const {
      data: { result }
    } = await state.axios.put(path, {
      message: room.lastMessage?.id
    })
    if (result) {
      commit(IMMutationTypes.updateRoom, {
        id: roomId,
        numberOfUnread: 0,
        isMentioned: false
      } as Room)
    }
  },
  async [IMActionTypes.handleRoomFromSocket](
    { state, commit, dispatch },
    result
  ) {
    // roomTag filter: ignore rooms that don't match current roomTag
    if (state.roomTag) {
      const roomTags: string[] =
        (result as { roomTags?: string[] }).roomTags ?? []
      if (!roomTags.includes(state.roomTag)) {
        // Cache tags so handleMessageFromSocket can skip API call
        commit(IMMutationTypes.setMap, {
          mapName: 'roomTagCache',
          key: (result as { _id: string })._id,
          value: roomTags
        })
        return
      }
    }
    const room = new Room(result, state.uid)
    const existingRoom = state.rooms[room.id]
    if (existingRoom) {
      if (result.unread === undefined) {
        room.numberOfUnread = existingRoom.numberOfUnread
      }
      if (result.pref === undefined) {
        room.pref = existingRoom.pref
      }
      if (
        result.isSuperuser === undefined &&
        existingRoom.isSuperuser !== undefined
      ) {
        room.isSuperuser = existingRoom.isSuperuser
      }
      if (result.muted === undefined && existingRoom.muted !== undefined) {
        room.muted = existingRoom.muted
      }
      if (
        result.isMentioned === undefined &&
        existingRoom.isMentioned !== undefined
      ) {
        room.isMentioned = existingRoom.isMentioned
      }
    }
    const rooms: { [id: string]: Room } = {}
    rooms[room.id] = room
    commit(IMMutationTypes.updateField, { key: 'rooms', value: rooms })
    const users: { [uid: string]: User } = {}
    ;(result as { members: unknown[] }).members // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .flatMap((m: any) => {
        if (Array.isArray(m.members)) {
          return [...m.members, m]
        }
        return [m]
      })
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .forEach((m: any) => {
        if (!users[m.id]) {
          users[m.id] = new User(m)
        }
      })
    commit(IMMutationTypes.mergeUsers, users)
    dispatch(IMActionTypes.aggregateRoomsAndFolders)
  },
  async [IMActionTypes.handleLastReadFromSocket]({ commit }, event) {
    commit(IMMutationTypes.updateLastRead, event)
  },
  async [IMActionTypes.sendMessage]({ state, commit, dispatch }, payload) {
    const { roomId } = payload
    if (!roomId) return
    const deliveringMessage = Message.fromPayload(payload, state.uid)
    if (!deliveringMessage) return
    deliveringMessage.status = MessageStatus.Sending
    commit(IMMutationTypes.setMap, {
      mapName: 'deliveringMessages',
      key: deliveringMessage.id,
      value: deliveringMessage
    })
    commit(IMMutationTypes.pushMessage, deliveringMessage)

    try {
      if (payload.messageType === MessageType.Image) {
        const { files } = payload
        const urls = await Promise.all(
          (payload.images as IMImage[]).map((image, index) =>
            dispatch(IMActionTypes.uploadImage, {
              image: image,
              file: (files as File[])[index],
              roomId: roomId
            })
          )
        )
        const images: {
          originalUrl: string
          thumbnailUrl: string
          width: number
          height: number
        }[] = []
        ;(payload.images as IMImage[]).forEach((image, index) => {
          state.imageCache.set(urls[index].thumbnailUrl, image.thumbnailUrl)
          const { id, width, height } = image
          images.push({
            originalUrl: urls[index].originalUrl,
            thumbnailUrl: urls[index].thumbnailUrl,
            width,
            height
          })
          commit(IMMutationTypes.updateField, {
            key: 'uploadProgresses',
            value: { [`${id}-original`]: 1 }
          })
          commit(IMMutationTypes.updateField, {
            key: 'uploadProgresses',
            value: { [`${id}-thumbnail`]: 1 }
          })
        })
        payload.images = images
        delete payload.files
      } else if (payload.messageType === MessageType.Video) {
        const { file, video } = payload
        const imVideo = video as IMVideo
        payload.width = imVideo.width
        payload.height = imVideo.height
        payload.duration = imVideo.duration

        // Check if already uploaded via autoUpload API
        if (imVideo.originalUrl && imVideo.thumbnailUrl) {
          // Already uploaded by backend, use URLs directly
          payload.thumbnailUrl = imVideo.thumbnailUrl
          payload.originalUrl = imVideo.originalUrl
        } else {
          // Need to upload manually (fallback for client-side processing)
          const thumbnailFile = imVideo.thumbnailFile
          if (!thumbnailFile) return
          const urls = await Promise.all([
            dispatch(IMActionTypes.uploadMedia, {
              id: thumbnailFile.id,
              file: thumbnailFile.file,
              roomId: roomId,
              isPreview: true
            }),
            dispatch(IMActionTypes.uploadMedia, {
              id: imVideo.id,
              file: file,
              roomId: roomId
            })
          ])
          payload.thumbnailUrl = urls[0]
          payload.originalUrl = urls[1]
          state.imageCache.set(urls[0], imVideo.thumbnailUrl)
          commit(IMMutationTypes.updateField, {
            key: 'uploadProgresses',
            value: { [imVideo.id]: 1 }
          })
        }
        delete payload.file
      } else if (payload.messageType === MessageType.File) {
        const { file } = payload
        const url = await dispatch(IMActionTypes.uploadMedia, {
          id: deliveringMessage.id,
          file: file,
          roomId: roomId
        })
        payload.originalUrl = url
        delete payload.file
        commit(IMMutationTypes.updateField, {
          key: 'uploadProgresses',
          value: { [deliveringMessage.id]: 1 }
        })
      } else if (payload.messageType === MessageType.Audio) {
        const { file } = payload
        const url = await dispatch(IMActionTypes.uploadMedia, {
          id: deliveringMessage.id,
          file: file,
          roomId: roomId
        })
        payload.originalUrl = url
        delete payload.file
        commit(IMMutationTypes.updateField, {
          key: 'uploadProgresses',
          value: { [deliveringMessage.id]: 1 }
        })
      } else if (payload.messageType === MessageType.Mixed) {
        // Mixed message: upload images like Image type, but keep text
        const { files } = payload
        const urls = await Promise.all(
          (payload.images as IMImage[]).map((image, index) =>
            dispatch(IMActionTypes.uploadImage, {
              image: image,
              file: (files as File[])[index],
              roomId: roomId
            })
          )
        )
        const images: {
          originalUrl: string
          thumbnailUrl: string
          width: number
          height: number
        }[] = []
        ;(payload.images as IMImage[]).forEach((image, index) => {
          state.imageCache.set(urls[index].thumbnailUrl, image.thumbnailUrl)
          const { id, width, height } = image
          images.push({
            originalUrl: urls[index].originalUrl,
            thumbnailUrl: urls[index].thumbnailUrl,
            width,
            height
          })
          commit(IMMutationTypes.updateField, {
            key: 'uploadProgresses',
            value: { [`${id}-original`]: 1 }
          })
          commit(IMMutationTypes.updateField, {
            key: 'uploadProgresses',
            value: { [`${id}-thumbnail`]: 1 }
          })
        })
        payload.images = images
        delete payload.files
      }
      const release = await state.rwlock.read()
      try {
        const {
          data: { result }
        } = await state.axios.post(`/rooms/${roomId}/message`, payload)
        const message = Message.createReactive(result)
        if (!message) return
        commit(IMMutationTypes.setMap, {
          mapName: 'processingMessages',
          key: message.id,
          value: message
        })
        commit(IMMutationTypes.deleteMap, {
          mapName: 'deliveringMessages',
          key: deliveringMessage.id
        })
        if (state.config.settings.linkPreviewEnabled) {
          dispatch(IMActionTypes.handleLinkPreviews, [message])
        }
        if (message.roomId === state.selectedRoomId) {
          commit(IMMutationTypes.replaceMessage, {
            message,
            targetMessageId: deliveringMessage.id
          })
        }
        commit(IMMutationTypes.updateRoom, {
          id: message.roomId,
          updatedAt: message.createdAt,
          lastMessage: message
        } as Room)
        dispatch(IMActionTypes.aggregateRoomsAndFolders)
        if (message.roomId === state.selectedRoomId) {
          dispatch(IMActionTypes.updateLastRead, message.roomId)
        }
        commit(IMMutationTypes.deleteMap, {
          mapName: 'processingMessages',
          key: message.id
        })
        const callbacks = state.config.callbacks
        callbacks?.onMessageSent?.(message)
        return message
      } finally {
        release()
      }
    } catch (error) {
      deliveringMessage.status = MessageStatus.Failed
      commit(IMMutationTypes.updateMessage, deliveringMessage)
      commit(IMMutationTypes.deleteMap, {
        mapName: 'deliveringMessages',
        key: deliveringMessage.id
      })
      throw error
    }
  },
  async [IMActionTypes.retryMessage](
    { state, commit, dispatch },
    localMessage
  ) {
    localMessage.status = MessageStatus.Sending
    commit(IMMutationTypes.updateMessage, localMessage)
    commit(IMMutationTypes.setMap, {
      mapName: 'deliveringMessages',
      key: localMessage.id,
      value: localMessage
    })
    try {
      const payload = localMessage.payload
      const roomId = localMessage.roomId

      // Handle video messages that need upload
      if (
        payload?.messageType === MessageType.Video &&
        !payload.originalUrl &&
        payload.video
      ) {
        const imVideo = payload.video as IMVideo
        // Check if already uploaded via autoUpload API
        if (imVideo.originalUrl && imVideo.thumbnailUrl) {
          payload.thumbnailUrl = imVideo.thumbnailUrl
          payload.originalUrl = imVideo.originalUrl
        } else {
          // Need to upload manually
          const thumbnailFile = imVideo.thumbnailFile
          if (thumbnailFile && payload.file) {
            const urls = await Promise.all([
              dispatch(IMActionTypes.uploadMedia, {
                id: thumbnailFile.id,
                file: thumbnailFile.file,
                roomId: roomId
              }),
              dispatch(IMActionTypes.uploadMedia, {
                id: imVideo.id,
                file: payload.file,
                roomId: roomId
              })
            ])
            payload.thumbnailUrl = urls[0]
            payload.originalUrl = urls[1]
            state.imageCache.set(urls[0], imVideo.thumbnailUrl)
            commit(IMMutationTypes.updateField, {
              key: 'uploadProgresses',
              value: { [imVideo.id]: 1 }
            })
          }
        }
        delete payload.file
      }

      const release = await state.rwlock.read()
      try {
        const {
          data: { result }
        } = await state.axios.post(
          `/rooms/${localMessage.roomId}/message`,
          payload
        )
        const remoteMessage = Message.createReactive(result)
        if (!remoteMessage) return
        commit(IMMutationTypes.setMap, {
          mapName: 'processingMessages',
          key: remoteMessage.id,
          value: remoteMessage
        })
        commit(IMMutationTypes.deleteMap, {
          mapName: 'deliveringMessages',
          key: localMessage.id
        })
        if (state.config.settings.linkPreviewEnabled) {
          dispatch(IMActionTypes.handleLinkPreviews, [remoteMessage])
        }
        if (remoteMessage.roomId === state.selectedRoomId) {
          commit(IMMutationTypes.replaceMessage, {
            message: remoteMessage,
            targetMessageId: localMessage.id
          })
        }
        commit(IMMutationTypes.updateRoom, {
          id: remoteMessage.roomId,
          updatedAt: remoteMessage.createdAt,
          lastMessage: remoteMessage
        } as Room)
        dispatch(IMActionTypes.aggregateRoomsAndFolders)
        commit(IMMutationTypes.deleteMap, {
          mapName: 'processingMessages',
          key: remoteMessage.id
        })
        return remoteMessage
      } finally {
        release()
      }
    } catch (error) {
      localMessage.status = MessageStatus.Failed
      commit(IMMutationTypes.updateMessage, localMessage)
      commit(IMMutationTypes.deleteMap, {
        mapName: 'deliveringMessages',
        key: localMessage.id
      })
      throw error
    }
  },
  async [IMActionTypes.batchSendMessage]({ state }, payload) {
    await state.axios.post(`/messages/batch`, payload)
  },
  async [IMActionTypes.recallMessage]({ state, commit }, payload) {
    const { roomId } = payload
    if (!roomId) return
    const {
      data: { result }
    } = await state.axios.post(`/rooms/${roomId}/message`, payload)
    const message = Message.createReactive(result)
    if (!message) return
    const room = state.rooms[`${roomId}`]
    if (room && room.lastMessage?.id === message.id) {
      commit(IMMutationTypes.updateRoom, {
        id: roomId,
        lastMessage: message
      } as Room)
    }
    commit(IMMutationTypes.replaceMessage, {
      targetMessageId: message.id,
      message
    })
  },
  async [IMActionTypes.editMessage]({ state, commit }, payload) {
    const { roomId, _id, message: newMessage } = payload
    if (!roomId || !_id || !newMessage) return
    const {
      data: { result }
    } = await state.axios.post(`/rooms/${roomId}/message`, {
      _id,
      message: newMessage
    })
    const updatedMessage = Message.createReactive(result)
    if (!updatedMessage) return
    const room = state.rooms[`${roomId}`]
    if (room && room.lastMessage?.id === _id) {
      commit(IMMutationTypes.updateRoom, {
        id: roomId,
        lastMessage: updatedMessage
      } as Room)
    }
    commit(IMMutationTypes.replaceMessage, {
      targetMessageId: _id,
      message: updatedMessage
    })
    commit(IMMutationTypes.setState, { editingMessageId: '' })
  },
  async [IMActionTypes.hideMessage]({ state, commit }, payload) {
    const { roomId, messageIds } = payload
    if (!roomId || !messageIds || messageIds.length === 0) return
    await state.axios.post(`/messages/user-delete`, {
      room: roomId,
      messages: messageIds
    })
    commit(IMMutationTypes.deleteMessages, messageIds)
  },
  async [IMActionTypes.deleteMessage]({ state, commit }, payload) {
    const { roomId, messageId } = payload
    if (!roomId || !messageId) return
    await state.axios.delete(`/rooms/${roomId}/messages/${messageId}`)
    commit(IMMutationTypes.deleteMessages, [messageId])
  },
  async [IMActionTypes.uploadMedia](
    { state, commit },
    { id, file, roomId }
  ): Promise<string> {
    const formData = new FormData()
    formData.append('file', file, encodeURIComponent(file.name))
    formData.append('extra', JSON.stringify({ roomId }))
    const {
      data: {
        result: { _id }
      }
    } = await state.axios.post('/files/chatserver-upload', formData, {
      headers: {
        'Content-Type': 'multipart/form-data'
      },
      timeout: 300000, // 5 分鐘，避免大檔案上傳 timeout
      onUploadProgress: (e) => {
        const { total } = e
        if (!total) return
        commit(IMMutationTypes.updateField, {
          key: 'uploadProgresses',
          value: { [id]: e.loaded / total }
        })
      }
    })
    return `${state.config.domain}/files/chatserver-upload/${_id}`
  },
  async [IMActionTypes.uploadImage]({ dispatch }, { image, file, roomId }) {
    if (file.size > 1024 * 1024) {
      // image size > 1MB
      try {
        const compressedFile = await imageCompression(file, {
          maxSizeMB: 1,
          maxWidthOrHeight: 1920,
          useWebWorker: true
        })
        const urls = await Promise.all([
          dispatch(IMActionTypes.uploadMedia, {
            id: `${image.id}-original`,
            file: file,
            roomId: roomId
          }),
          dispatch(IMActionTypes.uploadMedia, {
            id: `${image.id}-thumbnail`,
            file: compressedFile,
            roomId: roomId
          })
        ])
        return { originalUrl: urls[0], thumbnailUrl: urls[1] }
      } catch (error) {
        console.error(error)
      }
    }
    const url = await dispatch(IMActionTypes.uploadMedia, {
      id: `${image.id}-original`,
      file,
      roomId: roomId
    })
    return { originalUrl: url, thumbnailUrl: url }
  },
  async [IMActionTypes.fetchLinkPreview](_, url): Promise<LinkPreview> {
    try {
      const { data } = await axios.get(
        `https://url.imkit.io/?url=${encodeURIComponent(url)}`
      )
      return data as LinkPreview
    } catch {
      // Fallback to YouTube oEmbed API for YouTube URLs
      const ytMatch = url.match(
        /^https?:\/\/(?:www\.|m\.|music\.)?(?:youtube\.com|youtu\.be)\//
      )
      if (!ytMatch) throw new Error('Link preview failed')
      const { data } = await axios.get(
        `https://www.youtube.com/oembed?url=${encodeURIComponent(url)}&format=json`
      )
      return {
        title: data.title,
        description: data.author_name,
        icon: 'https://www.youtube.com/favicon.ico',
        images: [data.thumbnail_url],
        name: 'YouTube',
        url
      } as LinkPreview
    }
  },
  async [IMActionTypes.handleLinkPreviews](
    { state, commit, dispatch },
    messages
  ) {
    const urls: string[] = Array.from(
      new Set(
        messages
          .flatMap((m) => (m as TextMessage)?.urls || [])
          .filter(
            (url) =>
              !state.linkPreviews[url] && !state.loadingLinkPreviews.has(url)
          )
      )
    )
    if (urls.length === 0) return
    commit(IMMutationTypes.addLoadingLinkPreviews, urls)
    const TIMEOUT_MS = 3000
    urls.forEach(async (url) => {
      try {
        const timeoutPromise = new Promise((_, reject) =>
          setTimeout(() => reject(new Error('timeout')), TIMEOUT_MS)
        )
        const linkPreview = await Promise.race([
          dispatch(IMActionTypes.fetchLinkPreview, url),
          timeoutPromise
        ])
        commit(IMMutationTypes.updateField, {
          key: 'linkPreviews',
          value: { [url]: linkPreview }
        })
      } catch {
        // ignore
      } finally {
        commit(IMMutationTypes.removeLoadingLinkPreview, url)
      }
    })
  },
  async [IMActionTypes.fetchVideoBlob]({ state }, url): Promise<Blob> {
    const { data } = await state.axios.get(url, {
      responseType: 'blob',
      timeout: 60000
    })
    return data
  },
  async [IMActionTypes.navigateToMessage](
    { state, commit, dispatch },
    messageId
  ) {
    const currentList = state.messageMultiLists.get(state.selectedRoomId)
    if (currentList?.main?.contains(messageId)) {
      commit(IMMutationTypes.setState, {
        navigationTargetId: messageId
      })
    } else {
      const roomId = state.selectedRoomId
      if (!roomId) return
      commit(IMMutationTypes.setState, { isNavigatingToMessage: true })
      try {
        await dispatch(IMActionTypes.loadMessages, {
          roomId,
          targetMessageId: messageId
        })
        if (state.selectedRoomId !== roomId) return
        commit(IMMutationTypes.setState, {
          navigationTargetId: messageId,
          isNavigatingToMessage: false
        })
      } catch {
        commit(IMMutationTypes.setState, { isNavigatingToMessage: false })
      }
    }
  },
  async [IMActionTypes.updateRoomPrefs](
    { state, commit, dispatch },
    { roomId, prefs }
  ) {
    await state.axios.post(`/roomPrefs/${roomId}`, prefs)
    const room = state.rooms[roomId]
    if (!room) return
    commit(IMMutationTypes.updateRoom, {
      id: roomId,
      pref: { ...room.pref, ...prefs }
    } as Room)
    dispatch(IMActionTypes.aggregateRoomsAndFolders)
  },
  async [IMActionTypes.fetchPrefs]({ state, commit }) {
    const {
      data: { result }
    } = await state.axios.get('/me/pref')
    const folders: { [id: string]: Folder } = {}
    const folderIds: string[] = []
    const folderNames: { [id: string]: string } = {}
    const folderRoomIds: { [id: string]: string[] } = {}
    const roomIdsInFolders: { [roomId: string]: boolean } = {}
    for (const element of result) {
      if (element.key === 'folders-meta') {
        for (const folder of element.data) {
          folderNames[folder.key] = folder.name
          folderIds.push(folder.key)
        }
      } else if (element.key === 'blackList') {
        continue
      } else {
        folderRoomIds[element.key] = element.data.children.map(
          (child: { [id: string]: string }) => child.id
        )
      }
    }
    for (const id of folderIds) {
      folders[id] = new Folder(id, folderNames[id], folderRoomIds[id] || [])
      for (const roomId of folderRoomIds[id] || []) {
        roomIdsInFolders[roomId] = true
      }
    }
    commit(IMMutationTypes.setState, {
      folders,
      sortedFolderIds: folderIds,
      roomIdsInFolders
    })
  },
  async [IMActionTypes.fetchRoomsInFolders]({ state, dispatch }) {
    const numberOfRoomIds = Object.keys(state.roomIdsInFolders).length
    while (state.numberOfFetchedRooms < numberOfRoomIds) {
      await dispatch(IMActionTypes.fetchRooms, {
        pageSize: 200
      })
    }
    const limit = pLimit(6)
    const tasks = Object.keys(state.roomIdsInFolders)
      .filter((id) => {
        return !state.rooms[id]
      })
      .map((id) => limit(() => dispatch(IMActionTypes.fetchRoom, id)))
    await Promise.allSettled(tasks)
  },
  async [IMActionTypes.updatePref]({ state }, { key, value }) {
    return await state.axios.post(`/me/pref/${key}`, value)
  },
  async [IMActionTypes.deletePref]({ state }, key) {
    return await state.axios.delete(`/me/pref/${key}`)
  },
  async [IMActionTypes.updateFolder](
    { state, dispatch, commit },
    { folderKey, name }
  ) {
    const roomIds = Object.keys(state.selectedRoomIdsForCreateFolder).filter(
      (id) => state.selectedRoomIdsForCreateFolder[id]
    )
    await dispatch(IMActionTypes.updatePref, {
      key: 'folders-meta',
      value: state.sortedFolderIds
        .map((id) => state.folders[id] as Folder)
        .filter((folder) => !!folder && folder.id !== folderKey)
        .map((folder) => ({
          key: folder.id,
          name: folder.name
        }))
        .concat([{ key: folderKey, name }])
        .sort((a, b) => a.key.localeCompare(b.key))
    })
    await dispatch(IMActionTypes.updatePref, {
      key: folderKey,
      value: {
        children: roomIds.map((id) => ({
          id,
          type: 'room'
        }))
      }
    })
    if (state.folders[folderKey]) {
      commit(IMMutationTypes.updateField, {
        key: 'roomIdsInFolders',
        value: state.folders[folderKey].roomIds.reduce(
          (acc, id) => {
            acc[id] = false
            return acc
          },
          {} as { [roomId: string]: boolean }
        )
      })
    }
    const folder = new Folder(folderKey, name, roomIds)
    commit(IMMutationTypes.updateField, {
      key: 'folders',
      value: {
        [folderKey]: folder
      }
    })
    commit(IMMutationTypes.updateField, {
      key: 'roomIdsInFolders',
      value: roomIds.reduce(
        (acc, id) => {
          acc[id] = true
          return acc
        },
        {} as { [roomId: string]: boolean }
      )
    })
    commit(IMMutationTypes.setState, {
      sortedFolderIds: [...new Set([...state.sortedFolderIds, folderKey])],
      selectedRoomIdsForCreateFolder: {}
    })
    dispatch(IMActionTypes.aggregateRoomsAndFolders)
  },
  async [IMActionTypes.removeFolder]({ state, dispatch }, folderId) {
    await dispatch(IMActionTypes.deletePref, folderId)
    await dispatch(IMActionTypes.updatePref, {
      key: 'folders-meta',
      value: state.sortedFolderIds
        .map((id) => state.folders[id] as Folder)
        .filter((folder) => !!folder && folder.id !== folderId)
        .map((folder) => ({
          key: folder.id,
          name: folder.name
        }))
    })
    dispatch(IMActionTypes.handlePrefDeleteFromSocket)
  },
  async [IMActionTypes.handlePrefChangeFromSocket](
    { state, commit, dispatch },
    payload
  ) {
    const { key, data } = payload
    if (key === 'folders-meta') {
      const folders: { [id: string]: Folder } = {}
      const sortedFolderIds: string[] = []
      for (const { key, name } of data as []) {
        const folder = state.folders[key] || new Folder(key, name, [])
        folders[key] = folder
        sortedFolderIds.push(key)
      }
      commit(IMMutationTypes.setState, {
        folders,
        sortedFolderIds
      })
    } else {
      const { id, name } = state.folders[key as string]
      if (id) {
        const roomIds = (data as { children: { id: string }[] }).children.map(
          (child) => child.id
        )
        const folder = new Folder(id, name, roomIds)
        commit(IMMutationTypes.updateField, {
          key: 'folders',
          value: {
            [key as string]: folder
          }
        })
        commit(IMMutationTypes.updateField, {
          key: 'roomIdsInFolders',
          value: roomIds.reduce(
            (acc, id) => {
              acc[id] = true
              return acc
            },
            {} as { [roomId: string]: boolean }
          )
        })
      }
    }
    dispatch(IMActionTypes.aggregateRoomsAndFolders)
  },
  async [IMActionTypes.handlePrefDeleteFromSocket](
    { state, commit, dispatch },
    payload
  ) {
    const folder = state.folders[payload]
    if (!folder) {
      return
    }
    const roomIdsInFolders: { [roomId: string]: boolean } = {}
    for (const id of folder.roomIds) {
      roomIdsInFolders[id] = false
    }
    commit(IMMutationTypes.deleteField, {
      key: 'folders',
      value: payload
    })
    commit(IMMutationTypes.updateField, {
      key: 'roomIdsInFolders',
      value: roomIdsInFolders
    })
    commit(IMMutationTypes.setState, {
      sortedFolderIds: state.sortedFolderIds.filter((id) => id !== payload)
    })
    dispatch(IMActionTypes.aggregateRoomsAndFolders)
  },
  async [IMActionTypes.aggregateRoomsAndFolders]({ state, commit }) {
    const roomIds = new Set(Object.keys(state.rooms))

    let sortedRooms = Array.from(roomIds)
      .map((id) => state.rooms[id])
      .filter((room) => {
        return room && !state.roomIdsInFolders[room.id] && !room.pref?.hidden
      })

    const sortUnreadFirst = state.sortUnreadFirst

    sortedRooms = sortedRooms.sort((a, b) => {
      if (sortUnreadFirst !== 0) {
        const aHasUnread = a.numberOfUnread > 0
        const bHasUnread = b.numberOfUnread > 0
        if (aHasUnread !== bHasUnread) {
          return sortUnreadFirst === 1
            ? bHasUnread
              ? 1
              : -1
            : aHasUnread
              ? 1
              : -1
        }
      }

      if (!!a.pref?.sticky !== !!b.pref?.sticky) {
        return a.pref?.sticky ? -1 : 1
      }

      return b.updatedAt - a.updatedAt
    })

    commit(IMMutationTypes.setState, {
      sortedRooms
    })
  },
  async [IMActionTypes.removeMembers]({ state, commit }, { roomId, uids }) {
    const room = state.rooms[roomId]
    if (!room) {
      return
    }
    await state.axios.post(`/rooms/${roomId}/delete/members`, {
      systemMessage: true,
      members: uids
    })
    if (uids.includes(state.uid)) {
      commit(IMMutationTypes.deleteRoom, roomId)
      const selectedRoomId = state.sortedRooms.find(
        (room) => room.numberOfUnread === 0
      )?.id
      if (selectedRoomId) {
        commit(IMMutationTypes.setState, {
          selectedRoomId
        })
      }
    }
  },
  async [IMActionTypes.handleTypingFromSocket]({ state, commit }, payload) {
    const { room: roomId, sender, senderInfo } = payload
    if (roomId !== state.selectedRoomId) return
    if (sender === state.uid) return
    if (state.blockedUsers[sender]) return
    commit(IMMutationTypes.mergeUsers, {
      [senderInfo._id]: new User(senderInfo)
    })
    const previousTimeoutId = state.isTyping[sender]
    if (previousTimeoutId !== undefined) {
      clearTimeout(previousTimeoutId)
    }
    const currentTimeoutId = setTimeout(() => {
      commit(IMMutationTypes.deleteField, {
        key: 'isTyping',
        value: sender
      })
    }, 6000)
    commit(IMMutationTypes.updateField, {
      key: 'isTyping',
      value: { [sender]: currentTimeoutId }
    })
  },
  async [IMActionTypes.insertUnreadMessage]({ state, commit }, numberOfUnread) {
    if (numberOfUnread <= 0) return

    const messageList = state.messageMultiLists.get(state.selectedRoomId)?.main
    if (!messageList) return

    const unreadDividerId = `unread-divider-${state.selectedRoomId}`
    messageList.remove(unreadDividerId)

    const messages = messageList.array()
    if (messages.length === 0) return

    // Try to find the last-read message by ID for accurate positioning
    const room = state.rooms[state.selectedRoomId]
    const lastReadId = room?.lastReadMessageId[state.uid]
    const lastReadByIdMsg = lastReadId
      ? messageList.finds(lastReadId)
      : undefined

    let dividerCreatedAt: number
    if (lastReadByIdMsg) {
      // ID-based: place divider right after the last-read message
      if (messageList.tail?.id === lastReadByIdMsg.id) return
      dividerCreatedAt = lastReadByIdMsg.createdAt + 1
    } else {
      // Fallback: count-based positioning
      const firstUnreadIndex = messages.length - numberOfUnread
      if (firstUnreadIndex <= 0) {
        const firstMessage = messages[0]
        if (!firstMessage) return
        dividerCreatedAt = firstMessage.createdAt - 1
      } else {
        const lastReadMessage = messages[firstUnreadIndex - 1]
        if (!lastReadMessage) return
        if (messageList.tail?.id === lastReadMessage.id) return
        dividerCreatedAt = lastReadMessage.createdAt + 1
      }
    }

    const announcementMessage = Message.fromPayload(
      {
        roomId: state.selectedRoomId,
        messageType: MessageType.Announcement,
        message: i18n.global.t('unreadMessages'),
        createdAtMS: dividerCreatedAt
      },
      state.uid
    )
    if (!announcementMessage) return
    announcementMessage.id = unreadDividerId
    commit(IMMutationTypes.pushMessage, announcementMessage)
  },
  async [IMActionTypes.removeUnreadMessage]({ state }) {
    const unreadDividerId = `unread-divider-${state.selectedRoomId}`
    state.messageMultiLists
      .get(state.selectedRoomId)
      ?.main?.remove(unreadDividerId)
  },
  async [IMActionTypes.translate]({ state }, text) {
    if (state.translationCache.has(text)) {
      return state.translationCache.get(text) || text
    }
    let target: string = navigator.language.split('-')[0]
    const langsGoogleSupported: { [key: string]: string } = {
      am: 'am',
      ar: 'ar',
      eu: 'eu',
      bn: 'bn',
      'en-gb': 'en-GB',
      'pt-br': 'pt-BR',
      bg: 'bg',
      ca: 'ca',
      chr: 'chr',
      hr: 'hr',
      cs: 'cs',
      da: 'da',
      nl: 'nl',
      en: 'en',
      et: 'et',
      fil: 'fil',
      fi: 'fi',
      fr: 'fr',
      de: 'de',
      el: 'el',
      gu: 'gu',
      iw: 'iw',
      hi: 'hi',
      hu: 'hu',
      is: 'is',
      id: 'id',
      it: 'it',
      ja: 'ja',
      kn: 'kn',
      ko: 'ko',
      lv: 'lv',
      lt: 'lt',
      ms: 'ms',
      ml: 'ml',
      mr: 'mr',
      no: 'no',
      pl: 'pl',
      'pt-pt': 'pt-PT',
      ro: 'ro',
      ru: 'ru',
      sr: 'sr',
      'zh-cn': 'zh-CN',
      sk: 'sk',
      sl: 'sl',
      es: 'es',
      sw: 'sw',
      sv: 'sv',
      ta: 'ta',
      te: 'te',
      th: 'th',
      'zh-tw': 'zh-TW',
      tr: 'tr',
      ur: 'ur',
      uk: 'uk',
      vi: 'vi',
      cy: 'cy'
    }
    if (langsGoogleSupported[navigator.language.toLowerCase()]) {
      target = langsGoogleSupported[navigator.language.toLowerCase()]
    }
    const translatedText = await fetch(
      'https://translation.googleapis.com/language/translate/v2',
      {
        method: 'POST',
        headers: new Headers({
          'Content-Type': 'application/x-www-form-urlencoded'
        }),
        body: new URLSearchParams({
          q: text,
          key: state.config.translationApiKey,
          target
        }),
        redirect: 'follow'
      }
    )
      .then((response) => response.json())
      .then((jsonData): string => jsonData.data?.translations[0].translatedText)
    state.translationCache.set(text, translatedText)
    return translatedText
  },
  // IMActionTypes.searchRooms
  async [IMActionTypes.searchRooms]({ state, commit }, keyword) {
    if (state.isRequesting[API.Search]) return
    // Show skeleton immediately by setting keyword and clearing old results
    commit(IMMutationTypes.setState, {
      searchKeyword: keyword,
      searchRooms: {},
      searchType: SearchType.RoomName
    })
    const types = Object.values(SearchType)
    const {
      data: { result }
    } = await state.axios.post(API.Search, {
      type: types,
      keyword
    })
    const rooms: { [id: string]: Room } = {}
    const users: { [uid: string]: User } = {}
    const searchRooms: { [type: string]: Room[] | Folder[] } = {}
    const searchedMessageIds = new Map<string, string[]>()
    for (const type of types) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      result[type].forEach((r: any) => {
        if (type === SearchType.Messages) {
          searchedMessageIds.set(r.room._id, r.messages)
          r = r.room
        }
        if (type === SearchType.Files) {
          searchedMessageIds.set(r.room._id, r.messages)
          r = r.room
        }
        rooms[r._id] = new Room(r, state.uid)
        if (!searchRooms[type]) {
          searchRooms[type] = []
        }
        ;(searchRooms[type] as Room[]).push(rooms[r._id])
        r.members // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .flatMap((m: any) =>
            Array.isArray(m.members) ? [...m.members, m] : [m]
          )
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          .forEach((m: any) => {
            if (!users[m.id]) {
              users[m.id] = new User(m)
            }
          })
      })
    }
    for (const folder of Object.values(state.folders)) {
      if (folder.name.includes(keyword)) {
        if (!searchRooms[SearchType.RoomPrefFolder]) {
          searchRooms[SearchType.RoomPrefFolder] = []
        }
        ;(searchRooms[SearchType.RoomPrefFolder] as Folder[]).push(folder)
      }
    }
    const searchTypes = Object.keys(searchRooms)
    const searchType =
      searchTypes.length > 0 ? searchTypes[0] : SearchType.RoomName
    commit(IMMutationTypes.updateField, { key: 'rooms', value: rooms })
    commit(IMMutationTypes.mergeUsers, users)
    commit(IMMutationTypes.setState, {
      searchRooms,
      searchType,
      searchKeyword: keyword,
      searchedMessageIds
    })
  },
  async [IMActionTypes.subscribe]({ state }) {
    if (
      typeof window === 'undefined' ||
      typeof Notification === 'undefined' ||
      !state.config.firebaseConfig ||
      !state.config.firebaseVapidKey
    ) {
      return
    }
    if (Notification.permission === 'default') {
      const permission = await Notification.requestPermission()
      if (permission !== 'granted') return
    } else if (Notification.permission !== 'granted') {
      return
    }
    const firebaseApp = initializeApp(state.config.firebaseConfig)
    const messaging = getMessaging(firebaseApp)
    const fcmToken = await getToken(messaging, {
      vapidKey: state.config.firebaseVapidKey
    })
    if (!fcmToken) return
    let deviceId = localStorage.getItem('imkit-deviceId')
    if (!deviceId) {
      deviceId = uuidv4()
      localStorage.setItem('imkit-deviceId', deviceId)
    }
    await state.axios.post(API.Subscribe, {
      type: 'fcm',
      token: fcmToken,
      deviceId
    })
  },
  async [IMActionTypes.unsubscribe]({ state }) {
    let deviceId = localStorage.getItem('imkit-deviceId')
    if (!deviceId) {
      deviceId = uuidv4()
      localStorage.setItem('imkit-deviceId', deviceId)
    }
    await state.axios.post(API.Unsubscribe, {
      type: 'fcm',
      deviceId
    })
  },
  async [IMActionTypes.removeRoomFromFolder](
    { state, commit, dispatch },
    roomId
  ) {
    if (!state.roomIdsInFolders[roomId]) return
    const selectedFolder = state.folders[state.selectedFolderId]
    if (!selectedFolder) return
    const folderKey = selectedFolder.id
    const roomIds = selectedFolder.roomIds.filter((id) => id !== roomId)
    await dispatch(IMActionTypes.updatePref, {
      key: folderKey,
      value: {
        children: roomIds.map((id) => ({
          id,
          type: 'room'
        }))
      }
    })
    const folder = new Folder(folderKey, selectedFolder.name, roomIds)
    commit(IMMutationTypes.updateField, {
      key: 'folders',
      value: {
        [folderKey]: folder
      }
    })
    commit(IMMutationTypes.updateField, {
      key: 'roomIdsInFolders',
      value: { [roomId]: false }
    })
    dispatch(IMActionTypes.aggregateRoomsAndFolders)
  },
  async [IMActionTypes.addRoomToFolder](
    { state, commit, dispatch },
    { roomId, folderId }
  ) {
    const folder = state.folders[folderId]
    if (!folder) return
    const roomIds = Array.from(new Set([...folder.roomIds, roomId]))
    await dispatch(IMActionTypes.updatePref, {
      key: folderId,
      value: {
        children: roomIds.map((id) => ({
          id,
          type: 'room'
        }))
      }
    })
    const newFolder = new Folder(folderId, folder.name, roomIds)
    commit(IMMutationTypes.updateField, {
      key: 'folders',
      value: {
        [folderId]: newFolder
      }
    })
    commit(IMMutationTypes.updateField, {
      key: 'roomIdsInFolders',
      value: { [roomId]: true }
    })
    dispatch(IMActionTypes.aggregateRoomsAndFolders)
  },
  async [IMActionTypes.toggleNotification]({ state, commit }, roomId) {
    const room = state.rooms[roomId]
    if (!room) return
    if (room.muted) {
      await state.axios.delete(`/me/mute/${roomId}`)
    } else {
      await state.axios.post(`/me/mute/${roomId}`)
    }
    commit(IMMutationTypes.updateRoom, {
      id: roomId,
      muted: !room.muted
    } as Room)
  },
  async [IMActionTypes.translateMessage]({ state, commit, dispatch }, message) {
    if (
      state.config.translationApiKey &&
      (message.type === MessageType.Text ||
        message.type === MessageType.Mixed) &&
      message.senderId !== state.uid
    ) {
      const text =
        message.type === MessageType.Text
          ? (message as TextMessage).text
          : (message as MixedMessage).text
      try {
        const translatedText = await dispatch(IMActionTypes.translate, text)
        if (message.type === MessageType.Text) {
          ;(message as TextMessage).translatedText =
            translatedText !== text ? translatedText : null
        } else {
          ;(message as MixedMessage).translatedText =
            translatedText !== text ? translatedText : null
        }
        commit(IMMutationTypes.replaceMessage, {
          message,
          targetMessageId: message.id
        })
      } catch (e) {
        console.error(e)
      }
    }
  },
  async [IMActionTypes.blockUser]({ state, commit }, { roomId, uid }) {
    await state.axios.post(`/blockStatus/room/${roomId}/${uid}`)
    commit(IMMutationTypes.updateField, {
      key: 'blockedUsers',
      value: { [uid]: true }
    })
  },
  async [IMActionTypes.unblockUser]({ state, commit }, { roomId, uid }) {
    await state.axios.delete(`/blockStatus/room/${roomId}/${uid}`)
    commit(IMMutationTypes.deleteField, {
      key: 'blockedUsers',
      value: uid
    })
  },
  async [IMActionTypes.getBlockList]({ state, commit }, roomId) {
    const resp = await state.axios.get(`/blockStatus/room/${roomId}`)
    const blockedUsers: { [uid: string]: boolean } = {}
    for (const block of resp.data.result.data) {
      if (!block.blockee || block.unblockAt) continue
      blockedUsers[block.blockee.id] = true
    }
    commit(IMMutationTypes.updateField, {
      key: 'blockedUsers',
      value: blockedUsers
    })
  },
  async [IMActionTypes.hideMessagesFromUserInRoom]({ state }, roomId) {
    await state.axios.post('/messages/user-delete/all-in-room', {
      room: roomId
    })
  },
  async [IMActionTypes.sendReaction]({ state }, { messageId, reaction }) {
    await state.axios.post(`/messages/${messageId}/reaction`, {
      reaction
    })
  },
  async [IMActionTypes.deleteReaction]({ state }, { messageId, reaction }) {
    const query = {
      reaction
    }
    await state.axios.delete(`/messages/${messageId}/reaction`, {
      params: query
    })
  },
  async [IMActionTypes.handleAIStreamingFromSocket](
    { state, commit },
    payload: {
      messageId: string
      room: string
      sender: string
      text: string
      senderInfo?: { _id: string; [key: string]: unknown }
    }
  ) {
    const { messageId, room: roomId, sender, text, senderInfo } = payload

    if (!messageId || !roomId || !text) {
      console.warn('Invalid AI streaming payload:', payload)
      return
    }

    // 只處理當前選中房間的消息
    if (roomId !== state.selectedRoomId) return

    const typingEntries = Object.entries(state.isTyping)
    if (typingEntries.length > 0) {
      typingEntries.forEach(([, timeoutId]) => clearTimeout(timeoutId))
      commit(IMMutationTypes.setState, { isTyping: {} })
    }

    await state.rwlock.withWrite(() => {
      const currentList = state.messageMultiLists.get(roomId)
      const existingMessage = currentList?.main?.finds(messageId)

      if (existingMessage && existingMessage.type === MessageType.AIStreaming) {
        // 累積文本到現有的 AI streaming message
        const aiMessage = existingMessage as AIStreamingMessage
        const updatedMessage = new AIStreamingMessage({
          _id: messageId,
          messageType: MessageType.AIStreaming,
          sender: senderInfo || { _id: sender },
          room: roomId,
          text: aiMessage.text + text, // 累積文本
          createdAtMS: aiMessage.createdAt,
          updatedAtMS: Date.now()
        })

        commit(IMMutationTypes.replaceMessage, {
          targetMessageId: messageId,
          message: updatedMessage
        })
      } else {
        // 創建新的 AI streaming message
        const newMessage = new AIStreamingMessage({
          _id: messageId,
          messageType: MessageType.AIStreaming,
          sender: senderInfo || { _id: sender },
          room: roomId,
          text: text,
          createdAtMS: Date.now(),
          updatedAtMS: Date.now()
        })

        commit(IMMutationTypes.pushMessage, newMessage)
      }
    })
  },

  async [IMActionTypes.fetchPresignedUrl]({ state }, { bucketName, fileId }) {
    const { data } = await state.axios.get(
      `/files/${bucketName}/${fileId}?signedUrlOnly=true`
    )
    return data.result.url
  },

  async [IMActionTypes.fetchPresignedUrlByPath]({ state }, path: string) {
    // Parse path like "/files/chat/b1e1af64-cf1d-450f-b7f8-1c7dbc3092e4.jpg"
    const match = path.match(/^\/files\/([^/]+)\/(.+)$/)
    if (!match) {
      console.error('Invalid file path format:', path)
      return null
    }
    const [, bucketName, fileId] = match
    const { data } = await state.axios.get(
      `/files/${bucketName}/${fileId}?signedUrlOnly=true`
    )
    return data.result.url
  }
}
