<script setup lang="ts">
import { computed, onMounted, onUnmounted, watch } from 'vue'
import { useStore } from 'vuex'
import FloatButton from './FloatButton.vue'
import RoomListWrapperCell from './RoomListWrapperCell.vue'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { vOnClickOutside } from '@vueuse/components'
import dayjs from 'dayjs'
import { ArrowUpDown, Search, X } from 'lucide-vue-next'
import { useModal, useVfm } from 'vue-final-modal'
import VirtualList from 'vue3-virtual-scroll-list'
import Folder from '../classes/folder'
import Room from '../classes/room'
import { useRoomSearch } from '../composables/useRoomSearch'
import { useRoomSort } from '../composables/useRoomSort'
import { SearchType } from '../enums/searchType'
import Settings from './../classes/settings'
import UpdateFolderModal from './folders/UpdateFolderModal.vue'
import MassTextingModal from './MassTextingModal.vue'
import LoadingSvg from './svgs/LoadingSvg.vue'

const store = useStore()
const vfm = useVfm()

// Sort
const { sortType, showSortMenu, isFirstLoading, setSortType } = useRoomSort()

const sortedRooms = computed((): Room[] => store.state.imkit.sortedRooms)
const sortedFolders = computed(() =>
  store.state.imkit.sortedFolderIds
    .map((id: string) => store.state.imkit.folders[id])
    .filter((folder: Folder) => folder)
)
const selectedFolder = computed(() => {
  return store.state.imkit.folders[store.state.imkit.selectedFolderId]
})
const searchType = computed((): SearchType => {
  return store.state.imkit.searchType
})
const searchTypes = computed(() => {
  if (store.state.imkit.searchKeyword) {
    return Object.values(SearchType).filter(
      (t) => t in store.state.imkit.searchRooms
    ) // preserve SearchType enum order
  }
  return []
})
const roomTag = computed(() => {
  return store.state.imkit.roomTag
})
const settings = computed((): Settings => store.state.imkit.config.settings)
const uid = computed(() => store.state.imkit.uid)

let visibilityHiddenAt = 0
let stopUidWatch: (() => void) | null = null
let lastUid = ''

const fetchTask = async () => {
  isFirstLoading.value = true
  try {
    await store.dispatch('imkit/fetchPrefs')
    await store.dispatch('imkit/fetchRooms')
  } finally {
    isFirstLoading.value = false
  }
  await store.dispatch('imkit/fetchRoomsInFolders')
}

// Search
const {
  searchKeyword,
  searchInput,
  isCompositting,
  isAPIRequesting,
  clearSearch
} = useRoomSearch({ fetchTask })

const list = computed(() => {
  if (store.state.imkit.searchKeyword && vfm.modals.length === 0) {
    if (
      searchType.value === SearchType.RoomPrefFolder &&
      selectedFolder.value
    ) {
      const list = [...store.state.imkit.searchRooms[searchType.value]]
      const roomsInSelectedFolder = selectedFolder.value.roomIds
        .map((id: string) => store.state.imkit.rooms[id])
        .filter((room: Room) => {
          if (roomTag.value) {
            return room && room.roomTags.includes(roomTag.value)
          }
          return room
        })
      const index = list.findIndex(
        (room: Room) => room.id === selectedFolder.value.id
      )
      if (index > -1) {
        list.splice(index + 1, 0, ...roomsInSelectedFolder)
      }
      return list.filter((item): item is Room => item instanceof Room)
    }
    const searchResults = store.state.imkit.searchRooms[searchType.value] || []
    return searchResults
  }
  const rooms = [...sortedRooms.value]
  const list = [...sortedFolders.value, ...rooms]
  if (selectedFolder.value) {
    const roomsInSelectedFolder = store.getters['imkit/roomsInSelectedFolder']
    const index = sortedFolders.value.findIndex(
      (folder: Folder) => folder.id === selectedFolder.value.id
    )
    if (index > -1) {
      list.splice(index + 1, 0, ...roomsInSelectedFolder)
    }
  }
  return list
})

const isRequesting = computed(
  () =>
    vfm.modals.length === 0 &&
    (isCompositting.value ||
      isFirstLoading.value ||
      (isAPIRequesting.value && searchKeyword.value.length > 0))
)

// Template v-if visibility variables
const showClearSearchButton = computed(() => !!searchKeyword.value)
const showLoadingSkeleton = computed(
  () => isRequesting.value && list.value.length === 0
)
const showSearchTypeTabs = computed(
  () => searchTypes.value.length > 0 && vfm.modals.length === 0
)
const showEmptyState = computed(
  () =>
    !isRequesting.value && list.value.length === 0 && vfm.modals.length === 0
)
const showCustomNoRoomsImage = computed(() => !!settings.value.noRoomsImageURL)
const showDefaultNoRoomsImage = computed(
  () => settings.value.noRoomsImageURL === undefined
)
const showNoRoomsText = computed(
  () => !!settings.value.noRoomsText || settings.value.noRoomsText === undefined
)

const tobottom = () => {
  store.dispatch('imkit/fetchRooms')
}
const createFolder = () => {
  const { open } = useModal({
    component: UpdateFolderModal
  })
  open()
}
const massTexting = () => {
  const { open } = useModal({
    component: MassTextingModal
  })
  open()
}

watch(sortedRooms, (rooms) => {
  if (rooms.length === 0) return
  if (!settings.value.autoSelectRoomWhenLoaded) return
  if (!store.state.imkit.selectedRoomId && document.body.clientWidth > 640) {
    if (settings.value.enableReadReceipt) {
      const room = Object.values(rooms).find(
        (room) => room.numberOfUnread === 0
      )
      if (room) {
        store.commit('imkit/setState', { selectedRoomId: room.id })
      }
    } else {
      const room = rooms[0]
      if (room) {
        store.commit('imkit/setState', { selectedRoomId: room.id })
      }
    }
  }
})

const onVisibilityChange = () => {
  if (document.hidden) {
    visibilityHiddenAt = dayjs().unix()
  } else {
    const hiddenInterval = dayjs().unix() - visibilityHiddenAt
    if (hiddenInterval > 60) {
      fetchTask()
      store.state.imkit.socket.connect()
    }
  }
}

onMounted(() => {
  stopUidWatch = watch(
    uid,
    () => {
      if (uid.value === lastUid) return
      lastUid = uid.value
      fetchTask()
    },
    { immediate: true }
  )
  document.addEventListener('visibilitychange', onVisibilityChange)
})

onUnmounted(() => {
  if (stopUidWatch) {
    stopUidWatch()
    stopUidWatch = null
  }
  document.removeEventListener('visibilitychange', onVisibilityChange)
})
</script>

<template>
  <!-- <div class="flex flex-col w-1/3 h-full overflow-auto p-2 gap-1">
    <room-list-wrapper-cell
      v-for="item in list"
      :key="item.id"
      :source="item"
    />
  </div> -->
  <div class="relative overflow-auto">
    <virtual-list
      class="h-full overflow-auto transition ease-in-out"
      :data-key="'id'"
      :data-sources="list"
      :data-component="RoomListWrapperCell"
      :wrap-class="'flex flex-col'"
      :estimated-size="66"
      :keeps="60"
      @tobottom="tobottom"
    >
      <template #header>
        <div class="border-b border-gray-200 p-4 dark:border-zinc-700">
          <div class="mb-4 flex items-center justify-between">
            <div class="flex items-center space-x-3">
              <span
                class="relative flex h-8 w-8 shrink-0 overflow-hidden rounded-full"
              >
                <img
                  class="aspect-square h-full w-full object-contain"
                  src="../assets/imkit_logo_no_text.png"
                />
              </span>
              <h1 class="font-semibold text-gray-900 dark:text-gray-100">
                IMKit
              </h1>
            </div>
          </div>
          <div class="flex items-center space-x-2">
            <div class="relative flex-1">
              <div
                class="absolute top-1/2 left-3 flex h-4 w-4 -translate-y-1/2 transform items-center justify-center"
              >
                <LoadingSvg v-if="isRequesting" />
                <Search v-else class="h-4 w-4 text-gray-500" />
              </div>
              <input
                ref="searchInput"
                v-model="searchKeyword"
                class="ring-offset-background flex h-10 w-full rounded-md border-0 bg-gray-100 px-3 py-2 pt-2 pr-10 pl-10 text-base! text-gray-900 file:border-0 file:bg-transparent file:text-base file:font-medium placeholder:text-gray-500 focus-visible:ring-1 focus-visible:ring-blue-400 focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-50 md:text-base dark:bg-zinc-700 dark:text-gray-100 dark:placeholder:text-gray-400"
                :placeholder="settings.searchRoomPlaceholder || $t('search')"
                @compositionstart="isCompositting = true"
                @compositionend="isCompositting = false"
                @blur="isCompositting = false"
              />
              <button
                v-if="showClearSearchButton"
                class="absolute inset-y-0 right-3 flex items-center text-gray-400 transition-colors hover:text-gray-600 focus-visible:ring-1 focus-visible:ring-blue-400 focus-visible:outline-none dark:text-gray-100"
                type="button"
                aria-label="Clear search"
                @click="clearSearch"
              >
                <X class="h-4 w-4" />
              </button>
            </div>
            <div
              v-on-click-outside="
                () => {
                  showSortMenu = false
                }
              "
              class="relative"
            >
              <button
                class="ring-offset-background inline-flex h-10 w-10 shrink-0 cursor-pointer items-center justify-center gap-2 rounded-md text-base font-medium whitespace-nowrap text-gray-900 transition-colors hover:bg-gray-100 focus-visible:ring-2 focus-visible:ring-gray-400 focus-visible:ring-offset-2 focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50 dark:text-gray-100 dark:hover:bg-zinc-700"
                type="button"
                @click="showSortMenu = !showSortMenu"
              >
                <ArrowUpDown class="h-4 w-4" />
              </button>
              <transition name="slide-fade">
                <div
                  v-if="showSortMenu"
                  class="absolute top-12 right-0 z-50 min-w-32 overflow-hidden rounded-md border border-gray-200 bg-white p-1 shadow-lg dark:border-zinc-700 dark:bg-zinc-800"
                >
                  <div
                    class="relative flex cursor-pointer items-center rounded-sm px-2 py-1.5 text-base transition-colors outline-none select-none hover:bg-gray-100 dark:hover:bg-zinc-700"
                    :class="{
                      'bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400':
                        sortType === 'time'
                    }"
                    @click="setSortType('time')"
                  >
                    {{ $t('sortByTime') }}
                  </div>
                  <div
                    class="relative flex cursor-pointer items-center rounded-sm px-2 py-1.5 text-base transition-colors outline-none select-none hover:bg-gray-100 dark:hover:bg-zinc-700"
                    :class="{
                      'bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400':
                        sortType === 'unread'
                    }"
                    @click="setSortType('unread')"
                  >
                    {{ $t('sortByUnread') }}
                  </div>
                </div>
              </transition>
            </div>
          </div>
        </div>
        <div
          v-if="showSearchTypeTabs"
          class="mx-2 mt-2 flex items-center gap-2 overflow-auto text-base text-gray-900 dark:text-gray-200"
        >
          <div
            v-for="t in searchTypes"
            :key="t"
            class="cursor-pointer rounded-lg p-2 whitespace-nowrap hover:bg-gray-100 hover:dark:bg-white hover:dark:text-gray-900"
            :class="{
              'bg-gray-100 font-medium text-gray-800': t === searchType
            }"
            @click="
              store.commit('imkit/setState', {
                searchType: t
              })
            "
          >
            {{ $t(t) }}
          </div>
        </div>
        <div v-if="showLoadingSkeleton" class="flex flex-col gap-1">
          <div v-for="i in 20" :key="i" class="flex gap-3 p-2">
            <div
              class="loading h-[50px] w-[50px] rounded-2xl bg-white dark:bg-zinc-800"
            />
            <div class="flex grow flex-col justify-center gap-2">
              <div
                class="loading h-5 w-full rounded-md bg-white dark:bg-zinc-800"
              />
              <div
                class="loading h-4 w-4/5 rounded-md bg-white dark:bg-zinc-800"
              />
            </div>
          </div>
        </div>
        <div
          v-else-if="showEmptyState"
          class="flex h-[80dvh] flex-col items-center justify-center gap-6 px-6 py-12"
        >
          <img
            v-if="showCustomNoRoomsImage"
            :src="settings.noRoomsImageURL"
            class="h-24 w-24 object-contain"
          />
          <img
            v-else-if="showDefaultNoRoomsImage"
            src="../assets/imkit_logo_no_text.png"
            class="h-24 w-24 object-contain"
          />
          <p
            v-if="showNoRoomsText"
            class="text-center text-base text-gray-500 dark:text-gray-400"
          >
            {{
              settings.noRoomsText === undefined
                ? $t('noRoomsAvailable')
                : settings.noRoomsText
            }}
          </p>
        </div>
      </template>
    </virtual-list>
    <FloatButton
      :mass-texting-enabled="settings.massTextingEnabled"
      @create-folder="createFolder"
      @mass-texting="massTexting"
    />
  </div>
</template>

<style scoped>
@keyframes bg {
  0% {
    background-color: oklch(0.872 0.01 258.338); /* --color-gray-300 light */
  }
  50% {
    background-color: oklch(0.928 0.006 264.531); /* --color-gray-200 light */
  }
  100% {
    background-color: oklch(0.872 0.01 258.338); /* --color-gray-300 light */
  }
}

@keyframes bg-dark {
  0% {
    background-color: oklch(0.37 0.013 285.805); /* --color-zinc-700 dark */
  }
  50% {
    background-color: oklch(0.442 0.017 285.786); /* --color-zinc-600 dark */
  }
  100% {
    background-color: oklch(0.37 0.013 285.805); /* --color-zinc-700 dark */
  }
}

.dark .loading {
  animation: bg-dark 2s infinite;
}
.loading {
  animation: bg 2s infinite;
}
</style>
