// --- Keep bottom-most visible message anchored when container height changes ---
let prevContainerHeight = 0
let wasAtBottom = false
const resizeObserver = new ResizeObserver((entries) => {
  const newHeight = entries[0].contentRect.height
  if (prevContainerHeight && vl.value) {
    if (wasAtBottom) {
      vl.value.scrollToBottom()
    } else {
      const delta = prevContainerHeight - newHeight
      if (Math.abs(delta) > 1) {
        vl.value.scrollToOffset(vl.value.getOffset() + delta)
      }
    }
  }
  prevContainerHeight = newHeight
})

function onVlScroll() {
  if (vl.value && settings.value.scrollAnchoringEnabled) {
    wasAtBottom =
      vl.value.getScrollSize() -
        vl.value.getOffset() -
        vl.value.getClientSize() <
      24
  }
}

