const send = async () => {
  const el = input.value
  if (!el) return

  let msg = ''
  const mentions: string[] = []

  // Walk DOM to extract text and embedded mentions
  const walk = (node: Node) => {
    if (node.nodeType === Node.TEXT_NODE) {
      msg += node.textContent
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      const element = node as HTMLElement
      if (element.tagName === 'BR') {
        // Convert <br> elements to newlines
        msg += '\n'
      } else if (element.hasAttribute('data-at-embedded')) {
        // Embedded mention from dropdown - extract nickname and find user
        const nickname =
          element.textContent?.trim().replace(/^@/, '').trim() || ''
        const user = Object.values(store.state.imkit.users).find(
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          (u: any) => u.nickname === nickname
        )
        if (user) {
          // Preserve spaces around mention (At.vue wraps content with spaces)
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const userId = (user as any).id
          mentions.push(userId)
          msg += ` @${userId} `
        } else {
          msg += element.textContent
        }
      } else if (element.tagName === 'DIV') {
        // Chrome/Safari create <div> elements for each line in contenteditable
        // Add newline before div content (except for the first line)
        if (msg.length > 0 && !msg.endsWith('\n')) {
          msg += '\n'
        }
        Array.from(node.childNodes).forEach(walk)
      } else {
        Array.from(node.childNodes).forEach(walk)
      }
    }
  }
  walk(el)

  msg = msg.trim()

  // Also handle typed @mentions (not from dropdown)
  for (const uid of room.value.memberIds) {
    const user = store.state.imkit.users[uid]
    if (
      user &&
      msg.includes(`@${user.nickname}`) &&
      !mentions.includes(user.id)
    ) {
      mentions.push(user.id)
      msg = msg.replaceAll(`@${user.nickname}`, `@${user.id}`)
    }
  }

  const hasText = msg.length > 0
  const hasImages = images.value.length > 0
  const hasVideos = videos.value.length > 0

  // Nothing to send
  if (!hasText && !hasImages && !hasVideos) return

  const { replyId, editingMessageId } = store.state.imkit

  // Save videos to local variables before clearing (needed for Case 4)
  const videosToSend = hasVideos ? [...videos.value] : []
  const videoFilesToSend = hasVideos ? [...videoFiles.value] : []

  // Clear all input UI immediately: text, reply preview, and video previews
  el.textContent = ''
  message.value = ''
  if (replyId) {
    store.commit('imkit/setState', { replyId: null })
  }
  if (hasVideos) {
    videos.value = []
    videoFiles.value = []
  }

  // Ensure DOM updates before proceeding with async operations
  // Without this, the input may not visually clear until all awaits complete
  await nextTick()

  const sendPromises: Promise<unknown>[] = []

  // If in edit mode, dispatch editMessage first (must complete before sending attachments)
  if (editingMessageId && hasText) {
    await store.dispatch('imkit/editMessage', {
      roomId: room.value.id,
      _id: editingMessageId,
      message: msg
    })
    // After edit, send images separately (concurrently with videos below)
    if (hasImages) {
      sendPromises.push(
        store.dispatch('imkit/sendMessage', {
          roomId: room.value.id,
          messageType: 'image',
          images: images.value,
          files: imageFiles.value
        })
      )
      images.value = []
      imageFiles.value = []
    }
  } else if (hasText && hasImages) {
    // Text + images → mixed message
    sendPromises.push(
      store.dispatch('imkit/sendMessage', {
        roomId: room.value.id,
        messageType: 'mixed',
        message: msg,
        images: images.value,
        files: imageFiles.value,
        reply: replyId ? replyId : null,
        mentions
      })
    )
    images.value = []
    imageFiles.value = []
  } else if (hasText) {
    // Text only
    sendPromises.push(
      store.dispatch('imkit/sendMessage', {
        roomId: room.value.id,
        messageType: 'text',
        message: msg,
        reply: replyId ? replyId : null,
        mentions
      })
    )
  } else if (hasImages) {
    // Images only
    sendPromises.push(
      store.dispatch('imkit/sendMessage', {
        roomId: room.value.id,
        messageType: 'image',
        images: images.value,
        files: imageFiles.value
      })
    )
    images.value = []
    imageFiles.value = []
  }

  // Videos (sent concurrently with the above)
  for (let i = 0; i < videosToSend.length; i++) {
    const video = videosToSend[i]
    const videoFile = videoFilesToSend[i]
    const { width, height, duration } = video
    sendPromises.push(
      store.dispatch('imkit/sendMessage', {
        roomId: room.value.id,
        messageType: 'video',
        video,
        file: videoFile,
        width,
        height,
        duration
      })
    )
  }

  if (sendPromises.length > 0) {
    await Promise.all(sendPromises)
  }

  // Keep keyboard open on mobile by re-focusing input
  input.value?.focus()
}
const totop = async () => {
  if (isNavigating.value || isNavigatingToMessage.value) return
  if (isBackgroundRefreshing.value) return
  const totalMessages =
    store.state.imkit.numberOfTotalMessages.get(
      store.state.imkit.selectedRoomId
    ) ?? Infinity
  if (sortedMessages.value.length >= totalMessages) return
  // Find the first real message (skip unread divider which has invalid ID for API)
  const firstRealMessage = sortedMessages.value.find(
    (m) => !m.id.startsWith('unread-divider-')
  )
  const messages = await store.dispatch('imkit/loadMessages', {
    roomId: room.value.id,
    beforeMessageId: firstRealMessage?.id
  })
  if (messages && messages.length > 0) {
    // 如果有未讀分隔線，重新定位它
    const hasLastRead = !!room.value?.lastReadMessageId[store.state.imkit.uid]
    if (
      initialUnreadCount.value > 0 &&
      settings.value.enableReadReceipt &&
      hasLastRead
    ) {
      await store.dispatch(
        'imkit/insertUnreadMessage',
        initialUnreadCount.value
      )
    }
    vl.value?.scrollToIndex(messages.length)
  }
}
const tobottom = async () => {
