const fetchVideoInfo = async (
  videoFile: File,
  roomId: string
): Promise<IMVideo> => {
  try {
    // Call API to get video info with autoUpload
    const formData = new FormData()
    formData.append('file', videoFile)
    formData.append(
      'autoUpload',
      JSON.stringify({
        bucket: 'chat',
        extra: {
          roomID: roomId
        }
      })
    )

    const response = await store.state.imkit.axios.post(
      API.FetchVideoInfo,
      formData,
      { timeout: 60000 }
    )

    const videoInfo = response.data?.result as {
      width: number
      height: number
      duration: number
      thumbnailUrl: string
      thumbnailId: string
      originalUrl: string
      originalId: string
    }

    // Fetch presigned URL for thumbnail to display in preview
    const presignedThumbnailUrl = await store.dispatch(
      'imkit/fetchPresignedUrlByPath',
      videoInfo.thumbnailUrl
    )

    // Convert API response to IMVideo format
    // When using autoUpload, the API returns URLs directly (no need to upload separately)
    const video: IMVideo = {
      id: videoInfo.originalId,
      width: videoInfo.width,
      height: videoInfo.height,
      duration: videoInfo.duration,
      thumbnailUrl: presignedThumbnailUrl || videoInfo.thumbnailUrl,
      originalUrl: videoInfo.originalUrl,
      thumbnailFile: null // No need to upload, already done by backend
    }
    return video
  } catch (error) {
    console.error('Error fetching video info from API:', error)
    // Fallback to client-side processing if API fails
    return await file2video(videoFile)
  }
}
const onFileChange = async (event: Event) => {
  const filesArray = Array.from(
    (event?.target as HTMLInputElement)?.files || []
  )
  if (filesArray.some((file) => file.size >= fileSizeLimit.value)) {
    openFileSizeLimitModal()
    if (fileInput.value) {
      fileInput.value.value = ''
    }
    return
  }
  const files = filesArray.filter((file) => file.size < fileSizeLimit.value)

  if (files.length === 0 || files.length > 10) return
  const selectedImageFiles = files.filter((file) =>
    file.type.startsWith('image')
  )
  const selectedVideoFiles = files.filter((file) =>
    file.type.startsWith('video')
  )
  const otherFiles = files.filter(
    (file) => !file.type.startsWith('image') && !file.type.startsWith('video')
  )
  if (selectedImageFiles.length > 0) {
    isLoadingFiles.value = true
    try {
      const newImages = await Promise.all(selectedImageFiles.map(file2image))
      images.value = images.value.concat(newImages)
      imageFiles.value = imageFiles.value.concat(selectedImageFiles)
    } finally {
      isLoadingFiles.value = false
    }
  }
  if (selectedVideoFiles.length > 0) {
    isLoadingVideo.value = true
    try {
      for (const videoFile of selectedVideoFiles) {
        let video
        try {
          video = await file2video(videoFile)
        } catch {
          video = await fetchVideoInfo(videoFile, room.value.id)
        }
        videos.value = videos.value.concat(video)
        videoFiles.value = videoFiles.value.concat(videoFile)
      }
    } finally {
      isLoadingVideo.value = false
    }
  }
  if (otherFiles.length > 0) {
    for (const file of otherFiles) {
      const payload = {
        roomId: room.value.id,
        messageType: 'file',
        file,
        originalUrl: '',
        extra: {
          mimeType: file.type,
          fileName: file.name.split('.').slice(0, -1).join('.'),
          bytes: file.size,
          fileExtension: file.name.split('.').pop()
        }
      }
      await store.dispatch('imkit/sendMessage', payload)
    }
  }
  if (fileInput.value) {
    fileInput.value.value = ''
  }
}
const onDrop = async (event: DragEvent) => {
  const filesArray = Array.from((event?.dataTransfer || {}).files || [])
  if (filesArray.length === 0 || filesArray.length > 10) return
  if (filesArray.some((file) => file.size >= fileSizeLimit.value)) {
    openFileSizeLimitModal()
    return
  }

  const droppedImageFiles = filesArray.filter((file) =>
    file.type.startsWith('image')
  )
  const droppedVideoFiles = filesArray.filter((file) =>
    file.type.startsWith('video')
  )
  const otherFiles = filesArray.filter(
    (file) => !file.type.startsWith('image') && !file.type.startsWith('video')
  )

  if (droppedImageFiles.length > 0) {
    isLoadingFiles.value = true
    try {
      const newImages = await Promise.all(droppedImageFiles.map(file2image))
      images.value = images.value.concat(newImages)
      imageFiles.value = imageFiles.value.concat(droppedImageFiles)
    } finally {
      isLoadingFiles.value = false
    }
  }
  if (droppedVideoFiles.length > 0) {
    isLoadingVideo.value = true
    try {
      for (const videoFile of droppedVideoFiles) {
        let video
        try {
          video = await file2video(videoFile)
        } catch {
          video = await fetchVideoInfo(videoFile, room.value.id)
        }
        videos.value = videos.value.concat(video)
        videoFiles.value = videoFiles.value.concat(videoFile)
      }
    } finally {
      isLoadingVideo.value = false
    }
  }
  if (otherFiles.length > 0) {
    for (const file of otherFiles) {
      const payload = {
        roomId: room.value.id,
        messageType: 'file',
        file,
        originalUrl: '',
        extra: {
          mimeType: file.type,
          fileName: file.name.split('.').slice(0, -1).join('.'),
          bytes: file.size,
          fileExtension: file.name.split('.').pop()
        }
      }
      await store.dispatch('imkit/sendMessage', payload)
    }
  }
}
const checkIfDroppable = (event: Event) => {
  event.preventDefault()
}
const onPaste = async (event: ClipboardEvent) => {
  const clipboardData = event.clipboardData
  if (!clipboardData) return

  // Handle file paste (images and videos)
  const files = clipboardData.files
  if (files.length > 0 && files.length <= 10) {
    if (Array.from(files).some((file) => file.size >= fileSizeLimit.value)) {
      openFileSizeLimitModal()
      return
    }
    event.preventDefault()

    const pastedImageFiles = Array.from(files).filter((file) =>
      file.type.startsWith('image')
    )
    const pastedVideoFiles = Array.from(files).filter((file) =>
      file.type.startsWith('video')
    )

    if (pastedImageFiles.length > 0) {
      isLoadingFiles.value = true
      try {
        images.value = images.value.concat(
          await Promise.all(pastedImageFiles.map(file2image))
        )
        imageFiles.value = imageFiles.value.concat(pastedImageFiles)
      } finally {
        isLoadingFiles.value = false
      }
    }

    if (pastedVideoFiles.length > 0) {
      isLoadingVideo.value = true
      try {
        for (const videoFile of pastedVideoFiles) {
          let video
          try {
            video = await file2video(videoFile)
          } catch {
            video = await fetchVideoInfo(videoFile, room.value.id)
          }
          videos.value = videos.value.concat(video)
          videoFiles.value = videoFiles.value.concat(videoFile)
        }
      } finally {
        isLoadingVideo.value = false
      }
    }
    return
  }

  // Strip HTML and paste as plain text, converting newlines to <br> for contenteditable
  const text = clipboardData.getData('text/plain')
  if (text) {
    event.preventDefault()

    // Escape HTML special characters first
    let html = escapeHtml(text)

    // Convert @userId mentions to embedded spans with blue styling
    // Match @userId patterns (userId can be alphanumeric with underscores/hyphens)
    // Also consume optional preceding whitespace to avoid double spaces
    html = html.replace(/(\s)?@([\w-]+)/g, (match, _ws, userId) => {
      const user = store.state.imkit.users[userId]
      if (user) {
        // Create embedded mention span matching At.vue format
        // Escape nickname to prevent XSS
        const safeNickname = escapeHtml(user.nickname)
        return `<span data-at-embedded="" contenteditable="false"> @${safeNickname} </span>`
      }
      return match // Keep original if user not found
    })

    // Convert newlines to <br>
    html = html.replace(/\n/g, '<br>')
    document.execCommand('insertHTML', false, html)
  }
}
const back = () => {
  store.commit('imkit/setState', { selectedRoomId: '' })
}
const removeImageAtIndex = (index: number) => {
  images.value.splice(index, 1)
  imageFiles.value.splice(index, 1)
