const openImageLightbox = (index: number) => {
  selectedImageIndex.value = index
  showImageLightbox.value = true
}
const openVideoLightbox = (index: number) => {
  const file = videoFiles.value[index]
  if (!file) return
  if (selectedVideoUrl.value) {
    URL.revokeObjectURL(selectedVideoUrl.value)
  }
  selectedVideoUrl.value = URL.createObjectURL(file)
  showVideoLightbox.value = true
}
const handleVideoLightboxOpenChange = (val?: boolean) => {
  showVideoLightbox.value = val ?? false
  if (!showVideoLightbox.value && selectedVideoUrl.value) {
    URL.revokeObjectURL(selectedVideoUrl.value)
    selectedVideoUrl.value = null
  }
}
const previousImage = () => {
  if (selectedImageIndex.value > 0) {
    selectedImageIndex.value--
  }
}
const nextImage = () => {
  if (selectedImageIndex.value < images.value.length - 1) {
    selectedImageIndex.value++
  }
}

const onCompositionstart = () => {
  isComposing.value = true
}
const onCompositionend = () => {
  // Safari fires compositionend before keydown, so delay resetting the flag
  // to ensure the Enter key that ends composition doesn't trigger send
  // See: https://bugs.webkit.org/show_bug.cgi?id=165004
  setTimeout(() => {
    isComposing.value = false
  }, 0)
}
const onKeydownEnter = (e: KeyboardEvent) => {
  if (
    !isComposing.value &&
    !e.isComposing &&
    e.key === 'Enter' &&
    !e.shiftKey &&
    !isMobile.value &&
    !settings.value.sendButtonEnabled
  ) {
    e.preventDefault()
    send()
  }
}
const onInput = () => {
  if (!input.value) return
  // Extract plain text for message ref (for typing indicator)
  const text = input.value.innerText || ''
  message.value = text
  // When content is empty, clear all child nodes to ensure CSS :empty selector works
  // This fixes the placeholder not showing after deleting all text
  if (!text.trim()) {
    input.value.textContent = ''
  }
}

const onFormatApplied = () => {
  if (input.value) {
    message.value = input.value.innerText || ''
  }
}
const search = () => {
  store.commit('imkit/setState', {
    isSearchInRoomMode: true
  })
}
let visibilityHiddenAt = 0
const onVisibilityChange = () => {
  if (document.hidden) {
    visibilityHiddenAt = dayjs().unix()
  } else {
    const hiddenInterval = dayjs().unix() - visibilityHiddenAt
    if (hiddenInterval > 60) {
      store.state.imkit.socket.connect()
      reloadData(selectedRoomId.value, false)
    } else if (
      selectedRoomId.value &&
      room.value &&
      room.value.numberOfUnread > 0
    ) {
      store.dispatch('imkit/updateLastRead', selectedRoomId.value)
      store.commit('imkit/updateRoom', {
        id: selectedRoomId.value,
        numberOfUnread: 0,
        isMentioned: false
      })
    }
  }
}
const waitForPaint = () =>
  new Promise<void>((resolve) =>
    requestAnimationFrame(() => requestAnimationFrame(() => resolve()))
  )
const finishLoad = async (
  roomId: string,
  numberOfUnread: number,
  resetInitialLoaded: boolean
) => {
  initialUnreadCount.value = numberOfUnread
  const uid = store.state.imkit.uid
  const hasLastRead = !!room.value?.lastReadMessageId[uid]
  const hasUnread = settings.value.enableReadReceipt && numberOfUnread > 0
  const shouldShowDivider = hasUnread && hasLastRead

  if (hasUnread) {
    store.dispatch('imkit/updateLastRead', roomId)
  }
  if (shouldShowDivider) {
    await store.dispatch('imkit/insertUnreadMessage', numberOfUnread)
  } else {
    store.dispatch('imkit/removeUnreadMessage')
  }
  if (room.value?.isSuperuser) {
    store.dispatch('imkit/getBlockList', room.value.id)
  }
  for (const message of store.state.imkit.deliveringMessages.values()) {
    if (message.roomId === roomId) {
      store.commit('imkit/pushMessage', message)
    }
  }
  await waitForPaint()
  if (shouldShowDivider && resetInitialLoaded) {
    const unreadDividerId = `unread-divider-${selectedRoomId.value}`
    const index = sortedMessages.value.findIndex(
      (m) => m.id === unreadDividerId
    )
    if (index !== -1) {
      vl.value?.scrollToIndex(index)
      isInitialLoaded.value = true
      return
    }
  }
  vl.value?.scrollToBottom()
  isInitialLoaded.value = true
}

const fetchAndLoadMessages = async (roomId: string) => {
  await store.dispatch('imkit/fetchRoom', roomId)
  if (store.state.imkit.selectedRoomId !== roomId) return 0
  const numberOfUnread = room.value?.numberOfUnread ?? 0

  await store.dispatch('imkit/loadMessages', { roomId })
  if (store.state.imkit.selectedRoomId !== roomId) return numberOfUnread

  const maxPages = 10
  let pages = 0
  while (realMessages.value.length < numberOfUnread && pages < maxPages) {
    const firstRealMessage = realMessages.value.find(
      (m: Message) => !m.id.startsWith('unread-divider-')
    )
    if (!firstRealMessage) break

    const prevCount = realMessages.value.length
    await store.dispatch('imkit/loadMessages', {
      roomId,
      beforeMessageId: firstRealMessage.id
    })
    if (realMessages.value.length === prevCount) break
    if (store.state.imkit.selectedRoomId !== roomId) return numberOfUnread
    pages++
  }
  return numberOfUnread
}

const backgroundRefresh = async (roomId: string) => {
  isBackgroundRefreshing.value = true
  try {
    const numberOfUnread = await fetchAndLoadMessages(roomId)
    if (store.state.imkit.selectedRoomId !== roomId) return
    await finishLoad(roomId, numberOfUnread, true)
  } catch (error) {
    console.error('Background refresh failed:', error)
  } finally {
    isBackgroundRefreshing.value = false
  }
}

const reloadData = async (roomId: string, resetInitialLoaded = true) => {
  const cachedList = store.state.imkit.messageMultiLists.get(roomId)
  const hasCachedMessages = cachedList?.main && cachedList.main.length > 0

  if (hasCachedMessages && resetInitialLoaded) {
    // Cache hit: show cached messages immediately, refresh in background
    store.commit('imkit/clearChatRoom')
    store.dispatch('imkit/removeUnreadMessage')
    backgroundRefresh(roomId)
    return
  }

  // No cache: show loading state, then fetch
  if (resetInitialLoaded) {
    isInitialLoaded.value = false
  }
  store.commit('imkit/clearChatRoom')
  let numberOfUnread = 0
  try {
    numberOfUnread = await fetchAndLoadMessages(roomId)
  } finally {
    await finishLoad(roomId, numberOfUnread, resetInitialLoaded)
  }
}
onMounted(() => {
  watch(
    selectedRoomId,
    async (newSelectedRoomId, oldSelectedRoomId) => {
      if (newSelectedRoomId === oldSelectedRoomId) return
      if (newSelectedRoomId) {
        if (input.value) {
          input.value.textContent = ''
        }
        message.value = ''
        images.value = []
        imageFiles.value = []
        videos.value = []
        videoFiles.value = []
        await reloadData(newSelectedRoomId)
        if (!isMobile.value) input.value?.focus()
      }
    },
    { immediate: true }
  )
  watch(
    [
      // 1) Keep pinned to bottom when virtual list input length changes.
      () => sortedMessages.value.length,
      // 2) Link preview loading finished may resize cells; keep bottom if already at bottom.
      () => store.state.imkit.loadingLinkPreviews.size,
      // Used to detect "exactly one real message appended".
      () => realMessages.value.length,
      // 3) AI streaming can replace/update the last message without changing array length.
      lastRealMessage
    ],
    ([, , newRealLen], [, , oldRealLen]) => {
      if (!isInitialLoaded.value) return

      const isNewSingleMessage =
        oldRealLen !== undefined && newRealLen - oldRealLen === 1

      if (isNewSingleMessage) {
        // 4) My own new message should force scroll-to-bottom even if currently not at bottom.
        if (lastRealMessage.value?.senderId === store.state.imkit.uid) {
          isLatestMessageVisible.value = false
          nextTick(() => vl.value?.scrollToBottom())
          return
        }
      }

      if (vl.value?.getOffset() === undefined) return
      const isAtBottom =
        vl.value?.getScrollSize() -
          vl.value?.getOffset() -
          vl.value?.getClientSize() <
        24

      if (isNewSingleMessage) {
        // 5) Someone else's new message: show banner only when user is not at bottom.
        isLatestMessageVisible.value = !isAtBottom
      }

      // For any data/height change (1~3), preserve bottom lock when user was already at bottom.
      if (isAtBottom && !isNavigating.value && !isNavigatingToMessage.value)
        nextTick(() => vl.value?.scrollToBottom())
    }
  )
  watch(navigationTargetId, (newId) => {
    if (!newId) return
    isNavigating.value = true
    const el = document.querySelector(
      `[data-message-id="${newId}"]`
    ) as HTMLElement | null
    const vlEl = vl.value?.$el as HTMLElement | undefined
    if (el && vlEl) {
      const elRect = el.getBoundingClientRect()
      const vlRect = vlEl.getBoundingClientRect()
      if (elRect.top < vlRect.top || elRect.bottom > vlRect.bottom) {
        const index = sortedMessages.value.findIndex((m) => m.id === newId)
        if (index !== -1) vl.value?.scrollToIndex(index)
      }
    } else {
      const index = sortedMessages.value.findIndex((m) => m.id === newId)
      if (index !== -1) vl.value?.scrollToIndex(index)
    }
    store.commit('imkit/setState', { navigationTargetId: '' })

    setTimeout(() => {
      const el = document.querySelector(
        `[data-message-id="${newId}"]`
      ) as HTMLElement | null
      if (el) {
        el.classList.remove('animate-message-highlight')
        void el.offsetWidth
        el.classList.add('animate-message-highlight')
        el.addEventListener(
          'animationend',
          () => {
            el.classList.remove('animate-message-highlight')
            isNavigating.value = false
          },
          { once: true }
        )
      } else {
        isNavigating.value = false
      }
    }, 100)
  })
  watch(
    replyId,
    () => {
      if (replyId.value) {
        showAudioInput.value = false
        const wasAtBottom =
          vl.value &&
          vl.value.getScrollSize() -
            vl.value.getOffset() -
            vl.value.getClientSize() <
            24
        // Focus synchronously to keep mobile keyboard activation within the user gesture call stack
        if (input.value) {
          input.value.focus()
        } else {
          nextTick(() => input.value?.focus())
        }
        if (wasAtBottom) {
          nextTick(() => vl.value?.scrollToBottom())
        }
      }
    },
    { flush: 'sync' }
  )
  watch(editingMessageId, (newId) => {
    if (newId) {
      store.commit('imkit/setState', { replyId: '' })
      showAudioInput.value = false
      const editingMessage = store.state.imkit.messageMultiLists
        .get(store.state.imkit.selectedRoomId)
        ?.main?.map.get(newId)
      if (
        editingMessage &&
        (editingMessage instanceof TextMessage ||
          editingMessage instanceof MixedMessage)
      ) {
        setTimeout(() => {
          if (input.value) {
            let html = escapeHtml(editingMessage.text)
            html = html.replace(/(\s)?@([\w-]+)/g, (match, _ws, userId) => {
              const user = store.state.imkit.users[userId]
              if (user) {
                const safeNickname = escapeHtml(user.nickname)
                return `<span data-at-embedded="" contenteditable="false"> @${safeNickname} </span>`
              }
              return match
            })
            html = html.replace(/\n/g, '<br>')
            input.value.innerHTML = html
            message.value = editingMessage.text
            input.value.focus()
            const range = document.createRange()
            const sel = window.getSelection()
            range.selectNodeContents(input.value)
            range.collapse(false)
            sel?.removeAllRanges()
            sel?.addRange(range)
          }
        }, 0)
      }
    } else {
      if (input.value) {
        input.value.textContent = ''
        message.value = ''
      }
    }
  })
  watch(message, () => {
    if (lastTypingDate.value.add(5, 'second') > dayjs()) return
    lastTypingDate.value = dayjs()
    const { socket, selectedRoomId } = store.state.imkit
    socket.emit('typing', selectedRoomId)
  })

  document.addEventListener('visibilitychange', onVisibilityChange)

  // Observe virtual list container resize to preserve scroll anchor
  const vlEl = vl.value?.$el as HTMLElement | undefined
  if (vlEl && settings.value.scrollAnchoringEnabled) {
    resizeObserver.observe(vlEl)
  }
})

onUnmounted(() => {
  document.removeEventListener('visibilitychange', onVisibilityChange)
  resizeObserver.disconnect()
})

const longtapHandler = () => {
  const { open } = useModal({
    component: VersionModal
  })
  open()
}
const members = computed(() => {
  return room.value.memberIds.map(
    (member: string) => store.state.imkit.users[member]?.nickname
  )
})
const textareaDisabled = computed(() => {
  const currRoom = room.value
  if (!currRoom) return false
  if (!currRoom.isSuperuser) return false

  const eligible = currRoom.memberIds.filter(
    (uid: string) => uid !== store.state.imkit.uid && !uid.endsWith('_sub')
  )

  if (eligible.length === 0) return false
  return eligible.every(
    (uid: string) => !!store.state.imkit.blockedUsers?.[uid]
  )
})
</script>

