import { Socket, io } from 'socket.io-client'

import { Store } from 'vuex'
import Config from './classes/config'
import Message from './classes/message'
import User from './classes/user'

export interface ServerToClientEvents {
  'chat message': (res: Record<string, unknown>) => void
}

export interface ClientToServerEvents {
  auth2: (
    token: string,
    header: { CLIENT_KEY: string; Authorization: string },
    callback: (res: Record<string, unknown>) => void
  ) => void
}

export function createSocket(
  config: Config,
  store: Store<any> // eslint-disable-line @typescript-eslint/no-explicit-any
): Socket<ServerToClientEvents, ClientToServerEvents> {
  const { domain, clientKey } = config
  const socket = io(domain, {
    forceBase64: true,
    transports: ['websocket', 'webtransport'],
    reconnection: true,
    reconnectionAttempts: Infinity,
    reconnectionDelay: 1000,
    reconnectionDelayMax: 5000
  })
  socket.on('connect', () => {
    socket.emit('auth2', store.state.imkit.config.token, {
      CLIENT_KEY: clientKey,
      Authorization: store.state.imkit.config.token
    })
  })
  socket.on('disconnect', (reason: string) => {
    if (socket.active) {
      // temporary failure, the socket will automatically try to reconnect
    } else {
      socket.connect()
      console.log(reason)
    }
  })
  socket.on('connect_error', (error: Error) => {
    if (socket.active) {
      // temporary failure, the socket will automatically try to reconnect
    } else {
      socket.connect()
      console.log(error.message)
    }
  })
  socket.on('chat message', (res: Record<string, unknown>) => {
    const message = Message.createReactive(res)
    const users: { [uid: string]: User } = {}
    const user = new User(res['sender'])
    const callbacks = store.state.imkit.config.callbacks
    callbacks?.onMessageReceived?.(message, user)
    users[user.id] = user
    store.commit('imkit/mergeUsers', users)
    store.dispatch('imkit/handleMessageFromSocket', {
      message,
      mentions: (res['mentions'] as string[]) ?? []
    })
  })
  socket.on('room', (res: Record<string, unknown>) => {
    store.dispatch('imkit/handleRoomFromSocket', res)
  })
  socket.on('lastRead', (res: Record<string, unknown>) => {
    const { roomID: roomId, memberID: uid, messageID: messageId } = res
    type lastRead = {
      roomId: string
      uid: string
      messageId: string
    }
    store.dispatch('imkit/handleLastReadFromSocket', {
      roomId,
      uid,
      messageId
    } as lastRead)
  })
  socket.on('roomPref', (res: Record<string, unknown>) => {
    const { room: roomId, ...pref } = res
    if (!roomId) return
    store.commit('imkit/updateRoom', { id: roomId, pref })
    if (pref['sticky'] !== undefined)
      store.dispatch('imkit/aggregateRoomsAndFolders')
  })
  socket.on('myPrefChange', (res: Record<string, unknown>) => {
    store.dispatch('imkit/handlePrefChangeFromSocket', res)
  })
  socket.on('myPrefDelete', (res: Record<string, unknown>) => {
    store.dispatch('imkit/handlePrefDeleteFromSocket', res)
  })
  socket.on('typing', (res: Record<string, unknown>) => {
    store.dispatch('imkit/handleTypingFromSocket', res)
  })
  socket.on('ai_streaming', (res: Record<string, unknown>) => {
    store.dispatch('imkit/handleAIStreamingFromSocket', res)
  })
  return socket
}
