<script setup lang="ts">
import { computed } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import { useStore } from 'vuex'
import Callbacks from '../classes/callbacks'

const vfm = useVfm()
const store = useStore()
const callbacks = computed((): Callbacks => store.state.imkit.config.callbacks)

const handleConfirm = () => {
  localStorage.clear()
  callbacks.value.onEndChat?.()
  vfm.closeAll()
}

const handleCancel = () => {
  vfm.closeAll()
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-zinc-800 min-w-[200px] max-w-full rounded-xl p-5 flex flex-col gap-3 w-[300px]"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div class="mb-1 text-xl font-medium text-gray-700 dark:text-gray-300">
      {{ $t('endChatConfirmTitle') }}
    </div>
    <div class="text-gray-500 dark:text-gray-400">
      {{ $t('endChatConfirmMessage') }}
    </div>
    <div class="mt-2 flex items-center justify-center gap-2">
      <button
        class="h-10 w-[100px] grow cursor-pointer rounded-lg border border-gray-200 text-base text-gray-700 dark:border-stone-400 dark:text-stone-400"
        @click="handleCancel"
      >
        {{ $t('cancel') }}
      </button>
      <button
        class="h-10 w-[100px] grow cursor-pointer rounded-lg bg-red-500 text-base text-white"
        @click="handleConfirm"
      >
        {{ $t('confirm') }}
      </button>
    </div>
  </vue-final-modal>
</template>
