type Options = {
  store: Store<any> // eslint-disable-line @typescript-eslint/no-explicit-any
  config: Config
}
export { ChatRoom, ChatRoomInfo, Message, ModalsContainer, RoomList, User }

const fetchImageAsBase64 = async (
  axios: AxiosInstance,
  url: string,
  onProgress?: (ratio: number) => void
) => {
  const resp = await axios.get(url, {
    responseType: 'arraybuffer',
    onDownloadProgress: (e) => {
      if (e.total) onProgress?.(e.loaded / e.total)
    }
  })
  const binary = new Uint8Array(resp.data).reduce(
    (data, byte) => data + String.fromCharCode(byte),
    ''
  )
  return `data:${resp.headers['content-type']};base64,${btoa(binary)}`
}

const refreshS3PresignedUrl = async (
  axios: AxiosInstance,
  s3Url: string
): Promise<string | null> => {
  const { hostname, pathname } = new URL(s3Url)
  if (!hostname.includes('s3') || !hostname.includes('amazonaws.com'))
    return null
  const segments = pathname.split('/').filter(Boolean)
  if (segments.length < 3) return null
  // S3 path: /{appPrefix}/{bucketName}/{fileId}
  const { data } = await axios.get(
    `/files/${segments[1]}/${segments.slice(2).join('/')}?signedUrlOnly=true`
  )
  return data.result?.url ?? null
}

/**
 * Per-app SDK registrations: vue-final-modal, vue-i18n, vue3-touch-events,
 * and the v-src directive. Exported so consumers that share one store across
 * multiple Vue apps (e.g. the Web Component layer) can register these on a
 * second app without re-running the store-scoped heavy init.
 */
export const installAppLevel = (
  app: App,
  store: Store<any> // eslint-disable-line @typescript-eslint/no-explicit-any
) => {
  app.use(createVfm())
  app.use(i18n)
  app.use<Vue3TouchEventsOptions>(Vue3TouchEvents, {
    disableClick: false
  })
  app.directive('src', async (el, binding) => {
    const { value, oldValue } = binding
    if (value.startsWith('data:')) {
      el.src = value
      return
    }
    const { imageCache: cache, axios } = store.state.imkit
    if (oldValue === undefined || value !== oldValue) {
      if (cache.has(value)) {
        el.src = cache.get(value)
        return
      }
      const onProgress = (ratio: number) => {
        store.commit('imkit/updateField', {
          key: 'downloadProgresses',
          value: { [value]: ratio }
        })
      }
      el.classList.add('opacity-0')
      try {
        const src = await fetchImageAsBase64(axios, value, onProgress)
        cache.set(value, src)
        el.src = src
      } catch {
        // Fetch failed (e.g., 403 from expired S3 presigned URL).
        // Try to get a fresh presigned URL from the API and retry.
        try {
          const freshUrl = await refreshS3PresignedUrl(axios, value)
          if (freshUrl) {
            const src = await fetchImageAsBase64(axios, freshUrl, onProgress)
            cache.set(value, src)
            el.src = src
            return
          }
        } catch {
          // Refresh failed
        }
        el.src = value
      } finally {
        el.classList.remove('opacity-0')
      }
    }
  })
}

export default {
  install: async (app: App, options: Options) => {
    console.log('IMKIT version:', version)
    const { store, config } = options
    if (!store.hasModule('imkit')) store.registerModule('imkit', imkit)
    let uid = ''
    try {
      const { id, _id }: { id: string; _id: string } = jose.decodeJwt(
        config.token
      )
      uid = id || _id
    } catch (e) {
      console.log(e)
    }
    const axios = createAxios(config, store)
    const socket = createSocket(config, store)
    store.commit('imkit/setState', { config, uid, axios, socket })
    installAppLevel(app, store)
  }
}
