<script setup lang="ts">
import { computed, inject } from 'vue'
import { useStore } from 'vuex'
import Message from '../../../classes/message'
import actionHandler from './../../../utils/line-action-handler'
const props = defineProps<{ content: any }>() // eslint-disable-line @typescript-eslint/no-explicit-any
const store = useStore()
const messageId = inject('messageId') as string
const message = computed(
  (): Message =>
    store.state.imkit.messageMultiLists
      .get(store.state.imkit.selectedRoomId)
      ?.main?.map.get(messageId)
)
const color = computed(() => {
  if (props.content.style === 'primary') {
    return '#ffffff'
  }
  if (props.content.style === 'secondary') {
    return '#000000'
  }
  return props.content.color || '#42659a'
})
const backgroundColor = computed(() => {
  if (props.content.style === 'primary') {
    return props.content.color || '#17c950'
  }
  if (props.content.style === 'secondary') {
    return props.content.color || '#dcdfe5'
  }
  return ''
})
</script>

<template>
  <button
    :class="[content.size === 'md' ? 'h-52px' : 'h-10']"
    class="rounded-lg"
    :style="{
      color: color,
      backgroundColor: backgroundColor
    }"
    @click="actionHandler(message.roomId, content.action)"
  >
    {{ content.action.label }}
  </button>
</template>

<style scoped></style>
