<script setup lang="ts">
import { vOnClickOutside } from '@vueuse/components'
import { onLongPress } from '@vueuse/core'
import { Edit, MoreVertical, Trash2 } from 'lucide-vue-next'
import { computed, ref } from 'vue'
import { useModal } from 'vue-final-modal'
import { useStore } from 'vuex'
import { SearchType } from '../enums/searchType'
import Folder from './../classes/folder'
import Room from './../classes/room'
import DeleteFolderConfirmModal from './DeleteFolderConfirmModal.vue'
import UpdateFolderModal from './folders/UpdateFolderModal.vue'
import HighlightedText from './HighlightedText.vue'

const props = defineProps<{ source: Folder }>()
const store = useStore()

const searchKeyword = computed(() => {
  if (
    store.state.imkit.searchKeyword.length > 0 &&
    store.state.imkit.searchType === SearchType.RoomPrefFolder
  ) {
    return store.state.imkit.searchKeyword
  }
  return undefined
})
const selectedFolderId = computed(() => {
  return store.state.imkit.selectedFolderId
})
const numberOfUread = computed(() => {
  return props.source.roomIds
    .filter((id) => store.state.imkit.selectedRoomId !== id)
    .reduce((acc, roomId) => {
      const room: Room = store.state.imkit.rooms[roomId]
      if (room) {
        return acc + room.numberOfUnread
      }
      return acc
    }, 0)
})
const roomTag = computed(() => {
  return store.state.imkit.roomTag
})
const numberOfChatroom = computed(() => {
  return props.source.roomIds
    .map((id: string) => store.state.imkit.rooms[id])
    .filter((room: Room) => {
      if (roomTag.value) {
        return room && room.roomTags.includes(roomTag.value)
      }
      return room
    }).length
})
const actionMenuRoomId = computed(() => store.state.imkit.actionMenuRoomId)
const actionMenuFolderId = computed(() => store.state.imkit.actionMenuFolderId)
const toggle = () => {
  if (actionMenuRoomId.value || actionMenuFolderId.value) {
    return
  }
  if (store.state.imkit.selectedFolderId === props.source.id) {
    store.commit('imkit/setState', { selectedFolderId: '' })
  } else {
    store.commit('imkit/setState', { selectedFolderId: props.source.id })
  }
}
const remove = () => {
  const { open } = useModal({
    component: DeleteFolderConfirmModal,
    attrs: {
      folder: props.source
    }
  })
  open()
  store.commit('imkit/setState', { actionMenuFolderId: '' })
}
const edit = () => {
  const { open } = useModal({
    component: UpdateFolderModal,
    attrs: {
      folderId: props.source.id
    }
  })
  open()
  store.commit('imkit/setState', { actionMenuFolderId: '' })
}
const toggleActionMenu = () => {
  if (actionMenuFolderId.value === props.source.id) {
    store.commit('imkit/setState', { actionMenuFolderId: '' })
  } else {
    store.commit('imkit/setState', { actionMenuFolderId: props.source.id })
  }
}
const handleClickOutside = () => {
  setTimeout(() => {
    store.commit('imkit/setState', { actionMenuFolderId: '' })
  }, 0)
}
const folderCellRef = ref<HTMLElement | null>(null)

const onLongPressCallbackHook = () => {
  toggleActionMenu()
}

onLongPress(folderCellRef, onLongPressCallbackHook, {
  modifiers: { prevent: true },
  delay: 500
})
</script>

<template>
  <div
    ref="folderCellRef"
    class="group relative mx-2 mt-2 flex min-h-[66px] cursor-pointer items-center gap-3 rounded-lg bg-slate-200 p-2 select-none active:bg-slate-300 dark:bg-slate-700 active:dark:bg-slate-600"
    @click="toggle"
  >
    <img
      v-if="selectedFolderId === source.id"
      width="30"
      height="30"
      src="../assets/opened-folder.png"
    />
    <img v-else width="30" height="30" src="../assets/folder.png" />
    <div class="flex flex-col overflow-hidden">
      <div
        class="overflow-hidden text-base text-ellipsis whitespace-nowrap text-gray-900 dark:text-gray-100"
      >
        <highlighted-text :text="source.name" :highlight="searchKeyword" />
      </div>
      <div
        class="overflow-hidden text-base text-ellipsis whitespace-nowrap text-gray-500 dark:text-gray-400"
      >
        {{
          numberOfChatroom
            ? $t('numberOfChatroom', numberOfChatroom)
            : $t('no-chatroom')
        }}
      </div>
    </div>

    <div
      v-if="numberOfUread > 0"
      class="ml-auto flex h-5 min-w-5 items-center justify-center rounded-full bg-blue-400 text-center text-xs leading-none font-semibold text-white"
    >
      {{ numberOfUread }}
    </div>
    <div
      class="absolute right-4 h-8 w-8 items-center justify-center rounded-full bg-white shadow-md hover:scale-110 hover:transform hover:transition dark:bg-zinc-800"
      :class="{
        flex: actionMenuFolderId == source.id,
        'hidden sm:group-hover:flex': actionMenuFolderId != source.id
      }"
      @click.stop="toggleActionMenu"
    >
      <MoreVertical class="h-5 w-5 text-gray-700 dark:text-gray-300" />
    </div>
    <div
      v-if="actionMenuFolderId == source.id"
      v-on-click-outside="handleClickOutside"
      class="absolute top-[calc(50%+28px)] right-3 z-10 flex flex-col items-stretch gap-1 rounded-lg bg-white p-1.5 text-base text-gray-800 shadow-md dark:bg-zinc-800 dark:text-gray-200"
    >
      <div
        class="flex cursor-pointer items-center gap-2 rounded p-2 hover:bg-gray-100 hover:dark:bg-zinc-700"
        @click.stop="edit"
      >
        <Edit class="h-5 w-5" />
        {{ $t('edit') }}
      </div>
      <div
        class="flex cursor-pointer items-center gap-2 rounded p-2 hover:bg-gray-100 hover:dark:bg-zinc-700"
        @click.stop="remove"
      >
        <Trash2 class="w- h-5" />
        {{ $t('delete') }}
      </div>
    </div>
  </div>
</template>

<style scoped></style>
