<script setup lang="ts">
import { twMerge } from 'tailwind-merge'
import { computed, ref, watch } from 'vue'
import { useModal } from 'vue-final-modal'
import AvatarModal from './AvatarModal.vue'

const props = withDefaults(
  defineProps<{ url: string; name: string; class?: string }>(),
  { class: '' }
)

const imgClass = computed(() =>
  twMerge(
    'h-[50px] w-[50px] cursor-pointer rounded-2xl object-cover',
    props.class
  )
)

const fallbackClass = computed(() =>
  twMerge(
    'flex h-[50px] w-[50px] cursor-pointer items-center justify-center rounded-2xl bg-gray-200 text-xl font-semibold text-gray-500 dark:bg-zinc-600 dark:text-gray-300',
    props.class
  )
)
const isFallback = ref(false)
isFallback.value = props.url.length === 0
const handleError = () => {
  isFallback.value = true
}
watch(
  () => [props.url, props.name],
  () => {
    isFallback.value = false
  }
)
const showAvatarModal = () => {
  const { open } = useModal({
    component: AvatarModal,
    attrs: {
      url: props.url,
      name: props.name
    }
  })
  open()
}
</script>

<template>
  <img
    v-if="!isFallback"
    :src="url"
    :class="imgClass"
    @error="handleError"
    @click.stop="showAvatarModal"
  />
  <div v-else :class="fallbackClass" @click.stop="showAvatarModal">
    {{ name && name.length > 0 ? name.charAt(0).toUpperCase() : '' }}
  </div>
</template>

<style scoped></style>
