import axios, { AxiosHeaders, AxiosInstance, AxiosRequestConfig } from 'axios'

import { useModal, useVfm } from 'vue-final-modal'
import { Store } from 'vuex'
import Config from './classes/config'
import UnauthorizedModal from './components/UnauthorizedModal.vue'
enum RequestType {
  Start,
  End
}

function handleRequest(
  type: RequestType,
  config: AxiosRequestConfig,
  store: Store<any> // eslint-disable-line @typescript-eslint/no-explicit-any
) {
  const { url } = config
  const path = url?.split('?')[0]
  if (!path) return
  const isRequesting: { [api: string]: Date | null } = {}
  isRequesting[path] = type == RequestType.Start ? new Date() : null
  store.commit('imkit/updateField', {
    key: 'isRequesting',
    value: isRequesting
  })
}

const refetchToken = async (
  store: Store<any> // eslint-disable-line @typescript-eslint/no-explicit-any
) => {
  // needs to fetch new valid token
  const token = ''
  if (token) {
    localStorage.setItem('imkit-token', token)
    store.commit('imkit/updateField', {
      key: 'config',
      value: { token }
    })
    return true
  } else if (localStorage.getItem('imkit-token')) {
    localStorage.removeItem('imkit-token')
  }
  const vfm = useVfm()
  vfm.closeAll()
  const { open } = useModal({
    component: UnauthorizedModal
  })
  open()
  return false
}

export function createAxios(
  config: Config,
  store: Store<any> // eslint-disable-line @typescript-eslint/no-explicit-any
): AxiosInstance {
  const { domain } = config
  const instance: AxiosInstance = axios.create({
    baseURL: domain,
    timeout: 10000
  })
  instance.interceptors.request.use(
    (config) => {
      handleRequest(RequestType.Start, config, store)
      const headers: AxiosHeaders = new AxiosHeaders({
        'IM-Authorization': store.state.imkit.config.token,
        'IM-Client-Key': store.state.imkit.config.clientKey,
        'x-timezone': Intl.DateTimeFormat().resolvedOptions().timeZone,
        'accept-language': navigator.language
      })
      config.headers = headers
      return config
    },
    (error) => {
      const { config } = error
      handleRequest(RequestType.End, config, store)
      return Promise.reject(error)
    }
  )
  instance.interceptors.response.use(
    (response) => {
      const { config } = response
      handleRequest(RequestType.End, config, store)
      return response
    },
    async (error) => {
      const { config } = error
      handleRequest(RequestType.End, config, store)
      if (error.response?.status === 401) {
        await refetchToken(store)
        const headers: AxiosHeaders = new AxiosHeaders({
          'IM-Authorization': store.state.imkit.config.token,
          'IM-Client-Key': store.state.imkit.config.clientKey,
          'x-timezone': Intl.DateTimeFormat().resolvedOptions().timeZone,
          'accept-language': navigator.language
        })
        config.headers = headers
        return axios.request(config)
      }
      return Promise.reject(error)
    }
  )
  return instance
}
