<script setup lang="ts">
import { computed, ref } from 'vue'
import RadialProgress from 'vue3-radial-progress'
import { useStore } from 'vuex'
import IMImage from '../classes/image'
import { ImageMessage, MessageStatus } from './../classes/message'
import { calculateImageSize } from './../utils/image-size'
import ContentLightboxDialog from './ui/ContentLightboxDialog.vue'
const props = defineProps<{ message: ImageMessage }>()
const store = useStore()
const uploadProgresses = computed(() => store.state.imkit.uploadProgresses)

// Lightbox state
const lightboxOpen = ref(false)
const selectedImage = ref<IMImage | null>(null)

const calculateSize = (index: number, image: IMImage) =>
  calculateImageSize(index, image, props.message.images.length)

const showImage = (image: IMImage) => {
  selectedImage.value = image
  lightboxOpen.value = true
}

const closeLightbox = () => {
  lightboxOpen.value = false
  selectedImage.value = null
}
</script>

<template>
  <div
    class="grid gap-px"
    :class="[message.images.length > 1 ? 'grid-cols-2' : 'grid-cols-1']"
  >
    <div
      v-for="(image, index) in message.images"
      :key="image.thumbnailUrl"
      class="relative flex items-center justify-center overflow-hidden rounded-lg"
      :class="{
        'col-span-2':
          message.images.length > 1 &&
          index === message.images.length - 1 &&
          index % 2 === 0
      }"
      @click="showImage(image)"
    >
      <img
        v-src="image.thumbnailUrl"
        src="data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw=="
        class="border-0 object-cover transition"
        :style="calculateSize(index, image)"
      />
      <template
        v-if="
          image.thumbnailUrl?.startsWith('data') &&
          message.status !== MessageStatus.Failed
        "
      >
        <div class="absolute inset-0 bg-gray-800/50 fill-blue-300" />
        <RadialProgress
          class="absolute!"
          :diameter="48"
          :completed-steps="
            uploadProgresses[`${image.id}-thumbnail`] !== undefined
              ? (((uploadProgresses[`${image.id}-original`] ?? 0) +
                  (uploadProgresses[`${image.id}-thumbnail`] ?? 0)) /
                  2) *
                100
              : (uploadProgresses[`${image.id}-original`] ?? 0) * 100
          "
          :total-steps="100"
          :start-color="'#60a5fa'"
          :stop-color="'#60a5fa'"
          :stroke-width="4"
          :inner-stroke-width="4"
        >
          <span class="text-xs font-medium text-white">
            {{
              Math.round(
                uploadProgresses[`${image.id}-thumbnail`] !== undefined
                  ? (((uploadProgresses[`${image.id}-original`] ?? 0) +
                      (uploadProgresses[`${image.id}-thumbnail`] ?? 0)) /
                      2) *
                      100
                  : (uploadProgresses[`${image.id}-original`] ?? 0) * 100
              )
            }}%
          </span>
        </RadialProgress>
      </template>
    </div>
  </div>

  <ContentLightboxDialog
    :open="lightboxOpen"
    :image="selectedImage"
    :room-id="message.roomId"
    :sender-name="message.senderNickname"
    :created-at="message.createdAt"
    @update:open="lightboxOpen = $event"
    @close="closeLightbox"
  />
</template>

<style scoped></style>
