import Message from '../../../classes/message'
import MessageLinkedList from '../../../classes/messageLinkedList'
import { IMState } from './state'
// import MessageMultiList from '../../../classes/messageMultiList'
import { MutationTree } from 'vuex'
import MessageMultiList from '../../../classes/messageMultiList'
import Room from '../../../classes/room'
import User from '../../../classes/user'
import { IMMutationTypes as MutationTypes } from './mutation-types'

const MAX_CACHED_ROOMS = 20

function evictOldRoomCaches(state: IMState) {
  if (state.messageMultiLists.size <= MAX_CACHED_ROOMS) return
  for (const roomId of state.messageMultiLists.keys()) {
    if (roomId === state.selectedRoomId) continue
    state.messageMultiLists.delete(roomId)
    state.numberOfTotalMessages.delete(roomId)
    state.searchedMessageIds.delete(roomId)
    if (state.messageMultiLists.size <= MAX_CACHED_ROOMS) break
  }
}

export type Mutations<S = IMState> = {
  [MutationTypes.increment](state: S): void
  [MutationTypes.setState](state: S, payload: Record<string, unknown>): void
  [MutationTypes.updateField](
    state: S,
    payload: {
      key: keyof S
      value: Record<string, unknown>
    }
  ): void
  [MutationTypes.mergeUsers](state: S, users: Record<string, User>): void
  [MutationTypes.deleteField](
    state: S,
    payload: {
      key: keyof S
      value: string
    }
  ): void
  [MutationTypes.updateRoom](state: S, payload: Room): void
  [MutationTypes.updateMessage](state: S, payload: Message): void
  [MutationTypes.updateLastRead](
    state: S,
    event: {
      roomId: string
      uid: string
      messageId: string
    }
  ): void
  [MutationTypes.pushMessage](state: S, message: Message): void
  [MutationTypes.replaceMessage](
    state: S,
    payload: {
      targetMessageId: string
      message: Message
    }
  ): void
  [MutationTypes.deleteMessages](state: S, messageIds: string[]): void
  [MutationTypes.clearChatRoom](state: S): void
  [MutationTypes.deleteRoom](state: S, roomId: string): void
  [MutationTypes.setMap](
    state: S,
    payload: {
      mapName: keyof S
      key: string
      value: unknown
    }
  ): void
  [MutationTypes.deleteMap](
    state: S,
    payload: {
      mapName: keyof S
      key: string
    }
  ): void
  [MutationTypes.insertMessageLinkedList](
    state: S,
    linkedList: MessageLinkedList
  ): void
  [MutationTypes.concateMessageLinkedList](
    state: S,
    linkedList: MessageLinkedList
  ): void
  [MutationTypes.unshiftMessageLinkedList](
    state: S,
    linkedList: MessageLinkedList
  ): void
  [MutationTypes.setRoomTag](state: S, roomTag: string): void
  [MutationTypes.addLoadingLinkPreviews](state: S, urls: string[]): void
  [MutationTypes.removeLoadingLinkPreview](state: S, url: string): void
}

export const mutations: MutationTree<IMState> & Mutations = {
  [MutationTypes.increment](state) {
    state.count++
  },
  [MutationTypes.setState](state, payload) {
    Object.assign(state, payload)
  },
  [MutationTypes.updateField](state, payload) {
    const { key, value } = payload
    Object.assign(state[key], value)
  },
  [MutationTypes.mergeUsers](state, users) {
    for (const id in users) {
      const existing = state.users[id]
      if (existing) {
        /* eslint-disable @typescript-eslint/no-explicit-any */
        const incoming = users[id] as any
        for (const prop in incoming) {
          if (incoming[prop] !== null || (existing as any)[prop] == null) {
            ;(existing as any)[prop] = incoming[prop]
          }
        }
        /* eslint-enable @typescript-eslint/no-explicit-any */
      } else {
        state.users[id] = users[id]
      }
    }
  },
  [MutationTypes.deleteField](state, payload) {
    const { key, value } = payload
    delete (state[key] as Record<string, unknown>)[value]
  },
  [MutationTypes.updateRoom](state, payload) {
    const { id } = payload
    const room = state.rooms[id]
    if (room) {
      Object.assign(room, payload)
    }
  },
  [MutationTypes.updateMessage](state, payload) {
    const { id } = payload
    const message = state.messageMultiLists.get(payload.roomId)?.main?.finds(id)
    if (message) {
      Object.assign(message, payload)
    }
  },
  [MutationTypes.updateLastRead](state, event) {
    const { roomId, uid, messageId } = event
    const room = state.rooms[roomId]
    if (room) {
      room.lastReadMessageId[uid] = messageId
    }
  },
  [MutationTypes.pushMessage](state, message) {
    if (message.roomId !== state.selectedRoomId) return
    state.messageMultiLists.get(message.roomId)?.main?.append(message)
  },
  [MutationTypes.replaceMessage](state, payload) {
    const { targetMessageId, message } = payload
    if (message.roomId !== state.selectedRoomId) return
    state.messageMultiLists
      .get(message.roomId)
      ?.main?.replace(targetMessageId, message)
  },
  [MutationTypes.deleteMessages](state, messageIds) {
    messageIds.forEach((messageId: string) => {
      state.messageMultiLists.get(state.selectedRoomId)?.main?.remove(messageId)
    })
  },
  [MutationTypes.clearChatRoom](state) {
    state.replyId = ''
    state.navigationTargetId = ''
    state.isNavigatingToMessage = false
    state.isTyping = {}
    state.isSearchInRoomMode = false
    state.messageSearchKeyword = ''
    state.blockedUsers = {}
    state.numberOfTotalMessages.delete(state.selectedRoomId)
    state.editingMessageId = ''
  },
  [MutationTypes.deleteRoom](state, roomId) {
    delete state.rooms[roomId]
    delete state.roomIdsInFolders[roomId]
    delete state.selectedRoomIdsForCreateFolder[roomId]
    state.sortedRooms = state.sortedRooms.filter((room) => room.id !== roomId)
    state.messageMultiLists.delete(roomId)
    state.numberOfTotalMessages.delete(roomId)
    state.searchedMessageIds.delete(roomId)
  },
  [MutationTypes.setMap](state, payload) {
    const { mapName, key, value } = payload
    ;(state[mapName] as Map<string, unknown>).set(key, value)
  },
  [MutationTypes.deleteMap](state, payload) {
    const { mapName, key } = payload
    ;(state[mapName] as Map<string, unknown>).delete(key)
  },
  [MutationTypes.insertMessageLinkedList](state, linkedList) {
    const roomId = state.selectedRoomId
    let multi = state.messageMultiLists.get(roomId)
    if (!multi) {
      multi = new MessageMultiList(linkedList)
    } else {
      multi.insert(linkedList)
      multi.merge()
    }
    state.messageMultiLists.delete(roomId)
    state.messageMultiLists.set(roomId, multi)
    evictOldRoomCaches(state)
  },
  [MutationTypes.concateMessageLinkedList](state, linkedList) {
    const roomId = state.selectedRoomId
    let multi = state.messageMultiLists.get(roomId)
    if (!multi) {
      multi = new MessageMultiList(linkedList)
    } else {
      multi.concate(linkedList)
      multi.merge()
    }
    state.messageMultiLists.delete(roomId)
    state.messageMultiLists.set(roomId, multi)
    evictOldRoomCaches(state)
  },
  [MutationTypes.unshiftMessageLinkedList](state, linkedList) {
    const roomId = state.selectedRoomId
    let multi = state.messageMultiLists.get(roomId)
    if (!multi) {
      multi = new MessageMultiList(linkedList)
    } else {
      multi.unshift(linkedList)
      multi.merge()
    }
    state.messageMultiLists.delete(roomId)
    state.messageMultiLists.set(roomId, multi)
    evictOldRoomCaches(state)
  },
  [MutationTypes.setRoomTag](state, roomTag) {
    if (roomTag !== state.roomTag) {
      state.roomTagCache.clear()
    }
    state.roomTag = roomTag
  },
  [MutationTypes.addLoadingLinkPreviews](state, urls) {
    state.loadingLinkPreviews = new Set([...state.loadingLinkPreviews, ...urls])
  },
  [MutationTypes.removeLoadingLinkPreview](state, url) {
    const newSet = new Set(state.loadingLinkPreviews)
    newSet.delete(url)
    state.loadingLinkPreviews = newSet
  }
}
