<script setup lang="ts">
import { computed } from 'vue'
import { TemplateMessage } from './../../classes/message'
import actionHandler from './../../utils/line-action-handler'
const props = defineProps<{ message: TemplateMessage }>()
const isIncoming = computed(() => props.message.isIncoming)
const isOutgoing = computed(() => !isIncoming.value)
</script>

<template>
  <div class="w-[250px] cursor-pointer overflow-hidden text-base">
    <img
      v-if="message.template.thumbnailImageUrl"
      class="object-cover text-gray-900 dark:text-gray-200"
      :class="{
        'object-contain': message.template.imageSize === 'contain'
      }"
      :style="{
        'background-color': message.template.imageBackgroundColor ?? '#ffffff',
        height: `${
          message.template.imageAspectRatio === 'square' ? 250 : 250 / 1.51
        }px`
      }"
      :src="message.template.thumbnailImageUrl"
      @click="actionHandler(message.roomId, message.template.defaultAction)"
    />
    <div
      class="flex flex-col gap-1 p-3"
      @click="actionHandler(message.roomId, message.template.defaultAction)"
    >
      <div>{{ message.template.title?.substring(0, 40) }}</div>
      <div
        v-if="message.template.text"
        class="text-base"
        :class="{
          'text-gray-500 dark:text-gray-300': isIncoming,
          'text-gray-100': isOutgoing
        }"
      >
        {{
          !message.template.thumbnailImageUrl && !message.template.title
            ? message.template.text.substring(0, 160)
            : message.template.text.substring(0, 60)
        }}
      </div>
    </div>
    <div
      v-if="message.template.actions.length > 0"
      class="flex flex-col gap-2 border-t border-gray-200 py-3 dark:border-gray-500"
    >
      <div
        v-for="action in message.template.actions"
        :key="action.label"
        class="flex items-center justify-center p-0.5 text-base"
        :class="{
          'text-slate-500 dark:text-slate-300': isIncoming,
          'text-slate-100': isOutgoing
        }"
        @click="actionHandler(message.roomId, action)"
      >
        {{ action.label }}
      </div>
    </div>
  </div>
</template>

<style scoped></style>
