<script setup lang="ts">
import { File } from 'lucide-vue-next'
import { computed, ref } from 'vue'
import { useModal } from 'vue-final-modal'
import { useI18n } from 'vue-i18n'
import RadialProgress from 'vue3-radial-progress'
import { useStore } from 'vuex'
import IMImage from '../classes/image'
import { calculateImageSize } from '../utils/image-size'
import Message, {
  FileMessage,
  ImageMessage,
  MessageStatus,
  MessageType,
  MixedMessage,
  TextMessage
} from './../classes/message'
import AvatarModal from './AvatarModal.vue'
import AvatarView from './AvatarView.vue'
import ContentLightboxDialog from './ui/ContentLightboxDialog.vue'

// Custom function to highlight keywords in rendered HTML
const highlightKeywords = (html: string, keyword: string): string => {
  if (!keyword) return html

  const escapedKeyword = escapeRegExp(keyword)
  const regex = new RegExp(
    `(?<![a-zA-Z0-9_])${escapedKeyword}(?![a-zA-Z0-9_])`,
    'uig'
  )

  // Only highlight text content, not within HTML tags
  // Use [\s\S] instead of . to match across newlines from <br>\n
  return html.replace(/>([\s\S]*?)</g, (match, textContent) => {
    const highlighted = textContent.replace(regex, (match: string) => {
      return `<span class="bg-amber-400 text-white">${match}</span>`
    })
    return `>${highlighted}<`
  })
}

function escapeRegExp(string: string): string {
  return string.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')
}

const props = defineProps<{ message: MixedMessage }>()
const store = useStore()

// --- Reply handling (from TextMessageContent) ---
const replyMessage = computed(
  (): Message =>
    store.state.imkit.messageMultiLists
      .get(store.state.imkit.selectedRoomId)
      ?.main?.map.get(props.message.replyId)
)
const replyMessageSender = computed(() => {
  const reply = replyMessage.value
  if (!reply) return null
  return store.state.imkit.users[reply.senderId]
})

const description = computed((): string => {
  if (!replyMessage.value) return ''
  if (replyMessage.value.type === MessageType.Text) {
    return (replyMessage.value as TextMessage).string
  } else if (replyMessage.value.type === MessageType.Mixed) {
    return (replyMessage.value as MixedMessage).string
  } else if (replyMessage.value.type === MessageType.File) {
    const file = replyMessage.value as FileMessage
    return `${file.fileName}.${file.fileExtension}`
  } else if (
    replyMessage.value.type === MessageType.Image ||
    replyMessage.value.type === MessageType.Video ||
    replyMessage.value.type === MessageType.Sticker
  ) {
    const { t } = useI18n()
    const messageTypeName = {
      [MessageType.Image]: t('image'),
      [MessageType.Video]: t('video'),
      [MessageType.Sticker]: t('sticker')
    }
    return messageTypeName[replyMessage.value.type]
  }
  return ''
})

const replyImage = computed((): IMImage | undefined => {
  if (replyMessage.value?.type === MessageType.Image) {
    return (replyMessage.value as ImageMessage).images[0]
  }
  if (replyMessage.value?.type === MessageType.Mixed) {
    return (replyMessage.value as MixedMessage).images[0]
  }
  return undefined
})

const imageLoadFailed = ref(false)

// --- Text handling (from TextMessageContent) ---
const isIncoming = computed(() => props.message.isIncoming)
const linkPreviews = computed(() => {
  if (!store.state.imkit.config.settings.linkPreviewEnabled) return []
  const { urls } = props.message
  if (!urls) return []
  return urls.map((url) => store.state.imkit.linkPreviews[url]).filter((l) => l)
})
const loadingLinkPreviewUrls = computed(() => {
  if (!store.state.imkit.config.settings.linkPreviewEnabled) return []
  const { urls } = props.message
  if (!urls) return []
  const loadingSet = store.state.imkit.loadingLinkPreviews as Set<string>
  return urls.filter(
    (url) => loadingSet.has(url) && !store.state.imkit.linkPreviews[url]
  )
})

const html = computed((): string => {
  const keyword = store.state.imkit.messageSearchKeyword
  return highlightKeywords(props.message.html, keyword)
})

const handleMentionClick = (event: MouseEvent) => {
  const target = event.target as HTMLElement
  if (target.tagName === 'SPAN' && target.dataset.uid) {
    const user = store.state.imkit.users[target.dataset.uid]
    if (!user) return
    const { open } = useModal({
      component: AvatarModal,
      attrs: {
        url: user.avatarUrl ?? '',
        name: user.nickname ?? ''
      }
    })
    open()
  }
}

const handleCopy = (event: ClipboardEvent) => {
  const selection = window.getSelection()
  const selectedText = selection?.toString()
  if (selectedText) {
    // User selected specific text, let the browser handle the copy natively
    return
  }
  // No selection, copy the entire message text
  event.preventDefault()
  event.clipboardData?.setData('text/plain', props.message.text)
}

const navigate = () => {
  store.dispatch('imkit/navigateToMessage', props.message.replyId)
}

const failedLinkPreviewImages = ref(new Set<string>())
const handleLinkPreviewImageError = (url: string) => {
  failedLinkPreviewImages.value = new Set([
    ...failedLinkPreviewImages.value,
    url
  ])
}
const handleLinkPreviewClick = (url: string) => {
  window.open(url, '_blank')
}

// --- Image handling (from ImageMessageContent) ---
const uploadProgresses = computed(() => store.state.imkit.uploadProgresses)

// Lightbox state
const lightboxOpen = ref(false)
const selectedImage = ref<IMImage | null>(null)

const calculateSize = (index: number, image: IMImage) =>
  calculateImageSize(index, image, props.message.images.length)

// Constrain root container width to match the single image's width,
// so text wraps to the image width instead of the bubble stretching.
const containerStyle = computed(() => {
  if (props.message.images.length !== 1) return {}
  const { width } = calculateImageSize(0, props.message.images[0], 1)
  // Subtract bubble padding (px-3 = 0.75rem × 2) so the image grid
  // (which uses -mx-3) aligns exactly to the bubble edges.
  return { width: `calc(${width} - 1.5rem)`, maxWidth: '100%' }
})

const showImage = (image: IMImage) => {
  selectedImage.value = image
  lightboxOpen.value = true
}

const closeLightbox = () => {
  lightboxOpen.value = false
  selectedImage.value = null
}
</script>

<template>
  <div class="flex flex-col gap-2" :style="containerStyle">
    <!-- Reply preview (if replying) -->
    <template v-if="replyMessage">
      <div class="flex cursor-pointer items-center gap-3" @click="navigate">
        <avatar-view
          class="row-span-2 h-7 w-7 shrink-0 rounded-lg text-base"
          :url="replyMessageSender?.avatarUrl ?? ''"
          :name="replyMessageSender?.nickname ?? ''"
        />
        <div class="flex flex-col gap-1">
          <div class="text-base font-bold text-gray-600 dark:text-gray-300">
            {{ replyMessageSender?.nickname }}
          </div>
          <div
            class="multiline-ellipsis text-xs break-all text-gray-500 dark:text-gray-300"
          >
            {{ description }}
          </div>
        </div>
        <img
          v-if="replyImage && !imageLoadFailed"
          v-src="replyImage.thumbnailUrl"
          class="ml-auto h-10 w-10 rounded-sm object-cover"
          @error="imageLoadFailed = true"
        />
        <File
          v-if="replyMessage.type === MessageType.File"
          :size="28"
          class="ml-auto text-gray-500 dark:text-gray-300"
        />
      </div>
      <div class="-mx-4 h-px bg-gray-200 dark:bg-zinc-600" />
    </template>

    <!-- Text content on top -->
    <div
      class="prose max-w-none wrap-break-word select-none dark:prose-invert pointer-fine:select-text prose-p:leading-5.5 prose-ol:my-0"
      @click="handleMentionClick"
      @copy="handleCopy"
      v-html="html"
    />

    <!-- Translation -->
    <div
      v-if="isIncoming && message.translatedText"
      dir="auto"
      class="break-words text-gray-400"
    >
      {{ $t('translation') }}: {{ message.translatedText }}
    </div>

    <!-- Link previews -->
    <div
      v-if="linkPreviews.length > 0 || loadingLinkPreviewUrls.length > 0"
      class="flex flex-col gap-3"
    >
      <!-- Skeleton loaders for loading link previews -->
      <div
        v-for="url in loadingLinkPreviewUrls"
        :key="url"
        class="flex animate-pulse items-stretch justify-center gap-2"
      >
        <div class="my-0.5 w-0.5 shrink-0 rounded-full bg-gray-300" />
        <div
          class="align-center flex grow flex-col justify-center gap-1.5 overflow-hidden"
        >
          <div class="h-4 w-3/4 rounded bg-gray-200 dark:bg-zinc-600" />
          <div class="h-3 w-1/2 rounded bg-gray-200 dark:bg-zinc-600" />
        </div>
        <div
          class="my-auto h-12 w-12 shrink-0 rounded-sm bg-gray-200 dark:bg-zinc-600"
        />
      </div>
      <!-- Loaded link previews -->
      <div
        v-for="linkPreview in linkPreviews"
        :key="linkPreview.url"
        class="flex cursor-pointer items-stretch justify-center gap-2"
        @click="handleLinkPreviewClick(linkPreview.url)"
      >
        <div class="my-0.5 w-0.5 shrink-0 rounded-full bg-blue-300" />
        <div
          class="align-center flex grow flex-col justify-center gap-0.5 overflow-hidden"
        >
          <div class="ellipsis text-base font-bold">
            {{ linkPreview.title }}
          </div>
          <div class="multiline-ellipsis text-xs">
            {{ linkPreview.description || $t('tapOpen') }}
          </div>
        </div>
        <img
          v-if="
            linkPreview.images.length > 0 &&
            !failedLinkPreviewImages.has(linkPreview.url)
          "
          :src="linkPreview.images[0]"
          class="my-auto h-12 w-12 shrink-0 rounded-sm object-cover"
          @error="handleLinkPreviewImageError(linkPreview.url)"
        />
      </div>
    </div>

    <!-- Image grid below -->
    <div
      class="-mx-3 -mb-2 grid gap-px"
      :class="[message.images.length > 1 ? 'grid-cols-2' : 'grid-cols-1']"
    >
      <div
        v-for="(image, index) in message.images"
        :key="image.thumbnailUrl"
        class="relative flex items-center justify-center overflow-hidden"
        :class="{
          'col-span-2':
            message.images.length > 1 &&
            index === message.images.length - 1 &&
            index % 2 === 0
        }"
        @click="showImage(image)"
      >
        <img
          v-src="image.thumbnailUrl"
          src="data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw=="
          class="border-0 object-cover transition"
          :style="calculateSize(index, image)"
        />
        <template
          v-if="
            image.thumbnailUrl?.startsWith('data') &&
            message.status !== MessageStatus.Failed
          "
        >
          <div class="absolute inset-0 bg-gray-800/50 fill-blue-300" />
          <RadialProgress
            class="absolute!"
            :diameter="48"
            :completed-steps="
              uploadProgresses[`${image.id}-thumbnail`] !== undefined
                ? (((uploadProgresses[`${image.id}-original`] ?? 0) +
                    (uploadProgresses[`${image.id}-thumbnail`] ?? 0)) /
                    2) *
                  100
                : (uploadProgresses[`${image.id}-original`] ?? 0) * 100
            "
            :total-steps="100"
            :start-color="'#60a5fa'"
            :stop-color="'#60a5fa'"
            :stroke-width="4"
            :inner-stroke-width="4"
          >
            <span class="text-xs font-medium text-white">
              {{
                Math.round(
                  uploadProgresses[`${image.id}-thumbnail`] !== undefined
                    ? (((uploadProgresses[`${image.id}-original`] ?? 0) +
                        (uploadProgresses[`${image.id}-thumbnail`] ?? 0)) /
                        2) *
                        100
                    : (uploadProgresses[`${image.id}-original`] ?? 0) * 100
                )
              }}%
            </span>
          </RadialProgress>
        </template>
      </div>
    </div>

    <ContentLightboxDialog
      :open="lightboxOpen"
      :image="selectedImage"
      :room-id="message.roomId"
      :sender-name="message.senderNickname"
      :created-at="message.createdAt"
      @update:open="lightboxOpen = $event"
      @close="closeLightbox"
    />
  </div>
</template>

<style scoped>
.multiline-ellipsis {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}
.ellipsis {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  overflow: hidden;
}

:deep(a) {
  color: #3b82f6;
  text-decoration: underline;
  word-break: break-all;
}
:global(.dark) :deep(a) {
  color: #60a5fa;
}
:deep(code:not(pre code) a) {
  color: inherit;
  text-decoration: none;
}
:global(.dark) :deep(code:not(pre code) a) {
  color: inherit;
}

:deep(li) {
  margin-top: 0;
  margin-bottom: 0;
}
:deep(ol > li)::marker,
:deep(ul > li)::marker {
  color: inherit;
}

/* Remove backticks added by Tailwind Typography prose */
:deep(code)::before,
:deep(code)::after {
  content: none;
}

/* GitHub-style inline code (exclude code blocks inside <pre>) */
:deep(code:not(pre code)) {
  display: inline;
  padding: 0.15em 0.3em;
  border-radius: 6px;
  background-color: rgba(175, 184, 193, 0.2);
  font-size: 85%;
  line-height: inherit;
  white-space: break-spaces;
