<script setup lang="ts">
import { Smile } from 'lucide-vue-next'
import { REACTION_EMOJIS } from '../constants'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuPortal,
  DropdownMenuTrigger
} from './tribo/ui/dropdown-menu'

const emit = defineEmits<{
  (e: 'select', emoji: string): void
}>()

const isOpen = defineModel<boolean>('open', { default: false })

const selectEmoji = (emoji: string) => {
  emit('select', emoji)
}
</script>

<template>
  <DropdownMenu v-model:open="isOpen">
    <DropdownMenuTrigger as-child>
      <button
        type="button"
        class="tooltip-trigger flex items-center justify-center"
      >
        <Smile
          class="h-5 w-5 cursor-pointer text-slate-500 dark:text-slate-400"
        />
        <span v-if="!isOpen" class="tooltip">{{ $t('emoji') }}</span>
      </button>
    </DropdownMenuTrigger>
    <DropdownMenuPortal>
      <DropdownMenuContent
        :side-offset="8"
        side="top"
        class="flex min-w-0 items-center gap-2 rounded-xl border-0 bg-white px-4 py-2 text-2xl shadow-lg dark:bg-zinc-800"
      >
        <button
          v-for="emoji in REACTION_EMOJIS"
          :key="emoji"
          type="button"
          class="cursor-pointer transition-all hover:translate-y-[-2px]"
          @click="selectEmoji(emoji)"
        >
          {{ emoji }}
        </button>
      </DropdownMenuContent>
    </DropdownMenuPortal>
  </DropdownMenu>
</template>
