<script setup lang="ts">
import { MoreVertical, Reply, RotateCcw, X } from 'lucide-vue-next'
import { computed, ref, watch } from 'vue'
import { MessageStatus } from '../classes/message'
import {
  useMessageActionItems,
  type ActionType
} from '../composables/useMessageActionItems'
import MessageEmojiPicker from './MessageEmojiPicker.vue'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuPortal,
  DropdownMenuSeparator,
  DropdownMenuTrigger
} from './tribo/ui/dropdown-menu'

const props = defineProps<{
  direction: 'outgoing' | 'incoming'
  canCopy: boolean
  canReply: boolean
  canTranslate: boolean
  canEdit: boolean
  isSuperuser: boolean
  isGroupRoom: boolean
  status: MessageStatus
  compactMode?: boolean
}>()

const actionItems = useMessageActionItems({
  canReply: () => props.canReply,
  canCopy: () => props.canCopy,
  canEdit: () => props.canEdit,
  isOutgoing: () => props.direction === 'outgoing',
  isSuperuser: () => props.isSuperuser,
  isGroupRoom: () => props.isGroupRoom
})

const emit = defineEmits<{
  reply: []
  edit: []
  copy: []
  translate: []
  delete: []
  unsend: []
  retry: []
  deleteFailedMessage: []
  selectEmoji: [emoji: string]
  'update:dropdownOpen': [value: boolean]
  dismiss: []
}>()

// 分開追蹤 more menu 和 emoji picker 的狀態
const isMoreMenuOpen = ref(false)
const isEmojiPickerOpen = ref(false)

// 當任一個 dropdown 開啟時，通知父元件（用於控制 mouseleave 行為）
const isDropdownOpen = defineModel<boolean>('dropdownOpen', { default: false })

watch([isMoreMenuOpen, isEmojiPickerOpen], ([more, emoji]) => {
  isDropdownOpen.value = more || emoji
})

const handleAction = (action: ActionType) => {
  ;(emit as (event: ActionType) => void)(action)
}

// Desktop dropdown: exclude reply (reply is a separate button outside dropdown)
const dropdownItems = computed(() =>
  actionItems.value.filter((a) => a.type !== 'reply')
)

// Check if there are any visible items in each menu
const hasVisibleActionItems = computed(() =>
  actionItems.value.some((a) => a.visible)
)
const hasVisibleDropdownItems = computed(() =>
  dropdownItems.value.some((a) => a.visible)
)
</script>

<template>
  <!-- Compact Mode (Mobile) -->
  <div v-if="compactMode" class="flex items-center justify-center gap-4">
    <MessageEmojiPicker
      v-model:open="isEmojiPickerOpen"
      @select="
        (emoji) => {
          emit('selectEmoji', emoji)
          emit('dismiss')
        }
      "
    />

    <DropdownMenu
      v-if="hasVisibleActionItems"
      v-model:open="isMoreMenuOpen"
      @update:open="(open) => !open && emit('dismiss')"
    >
      <DropdownMenuTrigger as-child>
        <button
          type="button"
          class="flex items-center justify-center rounded-full bg-white/20 p-2"
        >
          <MoreVertical class="h-5 w-5 cursor-pointer text-white" />
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuPortal>
        <DropdownMenuContent
          align="center"
          side="top"
          :side-offset="8"
          class="border-0 bg-white dark:border dark:border-zinc-600 dark:bg-zinc-800"
        >
          <template v-for="action in actionItems" :key="action.type">
            <DropdownMenuSeparator
              v-if="action.visible && action.dividerBefore"
            />
            <DropdownMenuItem
              v-if="action.visible"
              :class="action.danger && 'text-red-500 focus:text-red-500'"
              @select="handleAction(action.type)"
            >
              <component :is="action.icon" class="mr-2 h-4 w-4" />
              <span>{{ $t(action.labelKey) }}</span>
            </DropdownMenuItem>
          </template>
        </DropdownMenuContent>
      </DropdownMenuPortal>
    </DropdownMenu>
  </div>

  <!-- Outgoing Actions -->
  <div
    v-else-if="direction === 'outgoing'"
    class="flex items-center justify-end gap-2"
  >
    <template v-if="status === MessageStatus.Delivered">
      <!-- More dropdown -->
      <DropdownMenu
        v-if="hasVisibleDropdownItems"
        v-model:open="isMoreMenuOpen"
      >
        <DropdownMenuTrigger as-child>
          <button
            type="button"
            class="tooltip-trigger flex items-center justify-center"
          >
            <MoreVertical
              class="h-5 w-5 cursor-pointer text-slate-500 dark:text-slate-400"
            />
            <span v-if="!isMoreMenuOpen" class="tooltip">{{ $t('more') }}</span>
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuPortal>
          <DropdownMenuContent
            align="end"
            side="top"
            :side-offset="8"
            class="border-0 bg-white dark:border dark:border-zinc-600 dark:bg-zinc-800"
          >
            <template v-for="action in dropdownItems" :key="action.type">
              <DropdownMenuSeparator
                v-if="action.visible && action.dividerBefore"
              />
              <DropdownMenuItem
                v-if="action.visible"
                :class="action.danger && 'text-red-500 focus:text-red-500'"
                @select="handleAction(action.type)"
              >
                <component :is="action.icon" class="mr-2 h-4 w-4" />
                <span>{{ $t(action.labelKey) }}</span>
              </DropdownMenuItem>
            </template>
          </DropdownMenuContent>
        </DropdownMenuPortal>
      </DropdownMenu>

      <button
        v-if="canReply"
        type="button"
        class="tooltip-trigger flex items-center justify-center"
        @click="emit('reply')"
      >
        <Reply
          class="h-5 w-5 cursor-pointer text-slate-500 dark:text-slate-400"
        />
        <span class="tooltip">{{ $t('reply') }}</span>
      </button>

      <MessageEmojiPicker
        v-model:open="isEmojiPickerOpen"
        @select="(emoji) => emit('selectEmoji', emoji)"
      />
    </template>

    <template v-else-if="status === MessageStatus.Failed">
      <X
        class="h-5.5 w-5.5 cursor-pointer text-slate-500 dark:text-slate-400"
        @click="emit('deleteFailedMessage')"
      />
      <RotateCcw
        class="h-4 w-4 cursor-pointer text-slate-500 dark:text-slate-400"
        @click="emit('retry')"
      />
    </template>
  </div>

  <!-- Incoming Actions -->
  <div v-else class="flex shrink-0 items-center justify-start gap-2">
    <MessageEmojiPicker
      v-model:open="isEmojiPickerOpen"
      @select="(emoji) => emit('selectEmoji', emoji)"
    />

    <button
      v-if="canReply"
      type="button"
      class="tooltip-trigger flex items-center justify-center"
      @click="emit('reply')"
    >
      <Reply
        class="h-5 w-5 cursor-pointer text-slate-500 dark:text-slate-400"
      />
      <span class="tooltip">{{ $t('reply') }}</span>
    </button>

    <!-- More dropdown -->
    <DropdownMenu v-if="hasVisibleDropdownItems" v-model:open="isMoreMenuOpen">
      <DropdownMenuTrigger as-child>
        <button
          type="button"
          class="tooltip-trigger flex items-center justify-center"
        >
          <MoreVertical
            class="h-5 w-5 cursor-pointer text-slate-500 dark:text-slate-400"
          />
          <span v-if="!isMoreMenuOpen" class="tooltip">{{ $t('more') }}</span>
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuPortal>
        <DropdownMenuContent
          align="start"
          side="top"
          :side-offset="8"
          class="border-0 bg-white dark:border dark:border-zinc-600 dark:bg-zinc-800"
        >
          <template v-for="action in dropdownItems" :key="action.type">
            <DropdownMenuSeparator
              v-if="action.visible && action.dividerBefore"
            />
            <DropdownMenuItem
              v-if="action.visible"
              :class="action.danger && 'text-red-500 focus:text-red-500'"
              @select="handleAction(action.type)"
            >
              <component :is="action.icon" class="mr-2 h-4 w-4" />
              <span>{{ $t(action.labelKey) }}</span>
            </DropdownMenuItem>
          </template>
        </DropdownMenuContent>
      </DropdownMenuPortal>
    </DropdownMenu>
  </div>
</template>
