<script setup lang="ts">
import { useMediaQuery } from '@vueuse/core'
import { computed, onUnmounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useStore } from 'vuex'
import { Reaction } from '../classes/message'
import User from '../classes/user'
import ReactionSheet from './ReactionSheet.vue'

defineOptions({
  name: 'ReactionList'
})

interface Props {
  reactions: Reaction[]
  /** Tooltip alignment: 'left' for others' messages, 'right' for own messages */
  align?: 'left' | 'right'
}

interface SumReaction {
  reaction: string
  count: number
  clients: string[]
}

const props = withDefaults(defineProps<Props>(), {
  align: 'left'
})
const emit = defineEmits<{
  (e: 'selectEmoji', emoji: string): void
}>()

const store = useStore()
const { t } = useI18n()

const userId = computed(() => store.state.imkit.uid)
const users = computed(() => store.state.imkit.users as Record<string, User>)

const sumReactions = computed(() => {
  const reactionMap = new Map<string, SumReaction>()

  props.reactions.forEach((reaction) => {
    const existing = reactionMap.get(reaction.reaction)
    if (existing) {
      existing.count += 1
      if (!existing.clients.includes(reaction.client)) {
        existing.clients.push(reaction.client)
      }
    } else {
      reactionMap.set(reaction.reaction, {
        reaction: reaction.reaction,
        count: 1,
        clients: [reaction.client]
      })
    }
  })

  return Array.from(reactionMap.values())
})

const MAX_NAMES_DISPLAYED = 20

const getTooltipText = (reaction: SumReaction): string => {
  const clientNames = reaction.clients.map((clientId) => {
    const user = users.value[clientId]
    return user?.nickname ?? clientId
  })

  const displayedNames = clientNames.slice(0, MAX_NAMES_DISPLAYED)
  const remainingCount = clientNames.length - MAX_NAMES_DISPLAYED

  const separator = t('listSeparator')

  if (remainingCount > 0) {
    return t('reactionTooltipWithOthers', {
      names: displayedNames.join(separator),
      count: remainingCount
    })
  }

  return t('reactionTooltip', { names: displayedNames.join(separator) })
}

const selectEmoji = (emoji: string) => {
  emit('selectEmoji', emoji)
}

const activeTooltip = ref<string | null>(null)

const supportsHover = useMediaQuery('(hover: hover)')

const showTooltip = (reactionEmoji: string) => {
  if (!supportsHover.value) return
  activeTooltip.value = reactionEmoji
}

const hideTooltip = () => {
  activeTooltip.value = null
}

const tooltipWrapperClass = computed(() => {
  const base = 'pointer-events-none absolute bottom-full z-50 mb-3'
  return props.align === 'right'
    ? `${base} right-0` // Own message: tooltip aligns right, grows left
    : `${base} left-0` // Others' message: tooltip aligns left, grows right
})

const itemClass = (reaction: SumReaction) => {
  const normalClass =
    'flex items-center gap-1 rounded-2xl px-2 py-0.5 cursor-pointer border'
  const bgClass = reaction.clients.includes(userId.value)
    ? 'bg-[#dff7fe] border-[#447faf] text-[#447faf] dark:bg-[#1e3a4c] dark:border-[#5a9fcf] dark:text-[#8cc4e8]'
    : 'bg-gray-100 border-transparent text-gray-700 dark:bg-zinc-700 dark:text-zinc-200'
  return [bgClass, normalClass]
}

// Long-press handling for mobile
const LONG_PRESS_DURATION = 500 // ms
let longPressTimer: ReturnType<typeof setTimeout> | null = null
const isLongPressing = ref(false)
const showReactionSheet = ref(false)
const sheetInitialEmoji = ref<string | null>(null)
const hadTouchEvent = ref(false) // Track if touch event occurred to prevent duplicate click

const startLongPress = (emoji: string) => {
  isLongPressing.value = false
  longPressTimer = setTimeout(() => {
    isLongPressing.value = true
    sheetInitialEmoji.value = emoji
    showReactionSheet.value = true
  }, LONG_PRESS_DURATION)
}

const cancelLongPress = () => {
  if (longPressTimer) {
    clearTimeout(longPressTimer)
    longPressTimer = null
  }
}

const onTouchStart = (emoji: string, event: TouchEvent) => {
  event.stopPropagation()
  hadTouchEvent.value = true
  startLongPress(emoji)
}

const onTouchEnd = (emoji: string, event: TouchEvent) => {
  cancelLongPress()
  // If it was a long press, don't trigger click
  if (isLongPressing.value) {
    event.preventDefault()
    isLongPressing.value = false
    return
  }
  // Regular tap - trigger selectEmoji
  selectEmoji(emoji)
}

const onTouchMove = () => {
  cancelLongPress()
}

// Desktop click handler - only fires if no touch event occurred
const onReactionClick = (emoji: string) => {
  if (hadTouchEvent.value) {
    hadTouchEvent.value = false
    return
  }
  selectEmoji(emoji)
}

const closeReactionSheet = () => {
  showReactionSheet.value = false
  sheetInitialEmoji.value = null
}

onUnmounted(() => {
  cancelLongPress()
})
</script>

<template>
  <div
    class="reactions flex items-center gap-1.5"
    :class="align === 'right' ? 'justify-end' : 'justify-start'"
  >
    <div
      v-for="reaction in sumReactions"
      :key="reaction.reaction"
      class="relative"
      @mouseenter="showTooltip(reaction.reaction)"
      @mouseleave="hideTooltip"
      @touchstart.passive="onTouchStart(reaction.reaction, $event)"
      @touchend="onTouchEnd(reaction.reaction, $event)"
      @touchmove.passive="onTouchMove"
    >
      <div
        :class="itemClass(reaction)"
        class="select-none"
        @click="onReactionClick(reaction.reaction)"
      >
        <span data-testid="reaction-emoji" class="text-xs leading-none">
          {{ reaction.reaction }}
        </span>
        <span class="text-xs tabular-nums">{{ reaction.count }}</span>
      </div>
      <Transition name="tooltip">
        <div
          v-if="activeTooltip === reaction.reaction"
          :class="tooltipWrapperClass"
        >
          <div class="reaction-tooltip">
            <div class="reaction-tooltip__emoji">
              {{ reaction.reaction }}
            </div>
            <div class="reaction-tooltip__text">
              {{ getTooltipText(reaction) }}
            </div>
            <div
              class="reaction-tooltip__arrow"
              :class="align === 'right' ? 'arrow-right' : 'arrow-left'"
            />
          </div>
        </div>
      </Transition>
    </div>

    <!-- Reaction Sheet -->
    <ReactionSheet
      v-if="showReactionSheet"
      :reactions="reactions"
      :initial-emoji="sheetInitialEmoji"
      @close="closeReactionSheet"
    />
  </div>
</template>

