import { GetterTree } from 'vuex'
import Room from '../../../classes/room'
import { RootState } from '../../../store'
import { IMState } from './state'

export type Getters = {
  doubleCount(state: IMState): number
  roomsInSelectedFolder(state: IMState): Room[]
}

export const getters: GetterTree<IMState, RootState> & Getters = {
  doubleCount: (state) => state.count * 2,
  roomsInSelectedFolder: (state) => {
    const { selectedFolderId } = state
    const selectedFolder = state.folders[selectedFolderId]
    if (!selectedFolder) return []
    const roomsInSelectedFolder = selectedFolder.roomIds
      .map((id: string) => state.rooms[id])
      .filter((room: Room) => {
        if (state.roomTag) {
          return room && room.roomTags.includes(state.roomTag)
        }
        return room
      })
      .sort((a: Room, b: Room) =>
        !!a.pref?.sticky === !!b.pref?.sticky
          ? b.updatedAt - a.updatedAt
          : a.pref?.sticky
            ? -1
            : 1
      )
    return roomsInSelectedFolder
  }
}
