<script setup lang="ts">
import { vOnClickOutside } from '@vueuse/components'
import dayjs from 'dayjs'
import localizedFormat from 'dayjs/plugin/localizedFormat'
import { ChevronLeft, MoreVertical } from 'lucide-vue-next'
import { computed, ref } from 'vue'
import { useModal } from 'vue-final-modal'
import { useStore } from 'vuex'
import { RoomType } from './../classes/room'
import AvatarView from './AvatarView.vue'
import MoveOutConfirmModal from './MoveOutConfirmModal.vue'

dayjs.extend(localizedFormat)

const store = useStore()
const room = computed(
  () => store.state.imkit.rooms[store.state.imkit.selectedRoomId]
)
const users = computed(() => store.state.imkit.users)
const uid = computed(() => store.state.imkit.uid)
const settings = computed(() => store.state.imkit.config.settings)
const showCustomRoomInfoIframe = computed(
  () => store.state.imkit.config.settings.customRoomInfoIframeURL
)
const customRoomInfoIframeURL = computed(
  () =>
    store.state.imkit.config.settings.customRoomInfoIframeURL +
    `?roomId=${store.state.imkit.selectedRoomId}`
)
const blockedUsers = computed(() => store.state.imkit.blockedUsers)

const canMoveOut = computed(() => {
  return room.value.type === 'group'
})
const back = () => {
  store.commit('imkit/setState', { isRoomInfoVisible: false })
}
const blockUser = (uid: string) => {
  store.dispatch('imkit/blockUser', {
    roomId: room.value.id,
    uid: uid
  })
}
const unblockUser = (uid: string) => {
  store.dispatch('imkit/unblockUser', {
    roomId: room.value.id,
    uid: uid
  })
}
const isRequesting = computed(
  () => !!store.state.imkit.isRequesting[`/blockStatus/room/${room.value.id}`]
)

const dropdownStates = ref<{ [key: string]: boolean }>({})

const confirmMoveOut = (memberId: string) => {
  const { open } = useModal({
    component: MoveOutConfirmModal,
    attrs: {
      memberIdToMoveOut: memberId,
      roomId: room.value.id
    }
  })

  open()
  toggleDropdown(memberId)
}

const toggleDropdown = (memberId: string) => {
  for (const key in dropdownStates.value) {
    if (key !== memberId) {
      dropdownStates.value[key] = false
    }
  }
  dropdownStates.value[memberId] = !dropdownStates.value[memberId]
}

const closeAllDropdowns = () => {
  for (const key in dropdownStates.value) {
    dropdownStates.value[key] = false
  }
}
const shouldShowBlockControl = (memberId: string) => {
  if (isRequesting.value) {
    return false
  }
  if (memberId === uid.value) {
    return false
  }
  if (room.value.type === RoomType.Direct) {
    return true
  }
  return room.value.isSuperuser
}
</script>

<template>
  <div
    class="absolute inset-0 flex w-full flex-col divide-y divide-gray-200 bg-white sm:relative sm:w-[350px] sm:max-w-[350px] sm:min-w-[350px] dark:divide-zinc-700 dark:bg-zinc-800"
  >
    <div class="flex h-15 items-center gap-4 px-3">
      <ChevronLeft
        :size="24"
        class="cursor-pointer text-gray-600 sm:hidden dark:text-gray-300"
        @click="back"
      />
      <avatar-view
        v-if="room.avatars.length === 1"
        :url="room.avatars[0].url"
        :name="room.avatars[0].name"
        class="h-10 w-10 text-xl"
      />
      <div v-else class="relative h-10 w-10">
        <avatar-view
          :url="room.avatars[1].url"
          :name="room.avatars[1].name"
          class="absolute top-0 right-0 h-7 w-7 rounded-xl text-base"
        />
        <avatar-view
          :url="room.avatars[0].url"
          :name="room.avatars[0].name"
          class="absolute bottom-0 left-0 h-[30px] w-[30px] rounded-xl border-2 border-white text-base group-hover:border-gray-100 dark:border-zinc-800"
        />
      </div>
      <div
        class="overflow-hidden text-base text-ellipsis whitespace-nowrap text-gray-900 dark:text-gray-200"
      >
        {{ room.displayName }}
      </div>
    </div>
    <div class="flex flex-col gap-4 overflow-auto p-2">
      <div>
        <div class="mb-2 text-base text-gray-500 dark:text-gray-300">
          {{ $t('members') }}
        </div>
        <div class="flex flex-col gap-3">
          <div
            v-for="memberId in room.memberIds"
            :key="memberId"
            class="flex items-center gap-4"
          >
            <div class="relative h-[50px] w-[50px]">
              <avatar-view
                :url="users[memberId].avatarUrl ?? ''"
                :name="users[memberId].nickname"
                class="relative h-[50px] w-[50px] text-xl"
              />
            </div>
            <div
              class="flex flex-col overflow-hidden text-base text-ellipsis whitespace-nowrap"
            >
              <div class="text-base text-gray-900 dark:text-gray-100">
                {{ users[memberId].nickname }}
              </div>
              <div
                v-if="users[memberId].city && users[memberId].country"
                class="text-base text-gray-500 dark:text-gray-400"
              >
                {{ users[memberId].city }}, {{ users[memberId].country }}
              </div>
            </div>
            <template
              v-if="
                settings.showMemberActionMenu &&
                (shouldShowBlockControl(memberId) ||
                  (canMoveOut && memberId !== uid))
              "
            >
              <div
                v-on-click-outside="closeAllDropdowns"
                class="relative ml-auto"
              >
                <button
                  class="flex h-8 w-8 items-center justify-center rounded-full hover:scale-110 hover:transform hover:bg-gray-100 hover:transition sm:group-hover:flex dark:bg-zinc-800 dark:hover:bg-zinc-700"
                  @click="toggleDropdown(memberId)"
                >
                  <MoreVertical
                    :size="20"
                    class="text-gray-600 dark:text-gray-300"
                  />
                </button>
                <div
                  v-if="dropdownStates[memberId]"
                  class="absolute right-0 z-10 mt-2 min-w-[150px] rounded-md border border-gray-100 bg-white shadow-lg dark:border-zinc-700 dark:bg-zinc-800"
                >
                  <div
                    class="py-1"
                    role="menu"
                    aria-orientation="vertical"
                    aria-labelledby="options-menu"
                  >
                    <button
                      v-if="canMoveOut && memberId !== uid"
                      class="block w-full px-4 py-2 text-left text-base text-gray-700 hover:bg-gray-100 dark:text-gray-200 dark:hover:bg-zinc-700"
                      role="menuitem"
                      @click="confirmMoveOut(memberId)"
                    >
                      {{ $t('moveOut') }}
                    </button>
                    <template v-if="shouldShowBlockControl(memberId)">
                      <button
                        v-if="blockedUsers[memberId]"
                        class="block w-full px-4 py-2 text-left text-base text-gray-700 hover:bg-gray-100 dark:text-gray-200 dark:hover:bg-zinc-700"
                        role="menuitem"
                        @click="
                          (unblockUser(memberId), toggleDropdown(memberId))
                        "
                      >
                        {{ $t('unblock') }}
                      </button>
                      <button
                        v-else
                        class="block w-full px-4 py-2 text-left text-base text-gray-700 text-red-500 hover:bg-gray-100 dark:text-gray-200 dark:text-red-400 dark:hover:bg-zinc-700"
                        role="menuitem"
                        @click="(blockUser(memberId), toggleDropdown(memberId))"
                      >
                        {{ $t('block') }}
                      </button>
                    </template>
                  </div>
                </div>
              </div>
            </template>
          </div>
        </div>
      </div>
      <div>
        <div class="text-gray-500 dark:text-gray-300">
          {{ $t('createdAt') }} {{ dayjs(room.createdAt).format('lll') }}
        </div>
        <div class="text-gray-500 dark:text-gray-300">
          {{ $t('updatedAt') }} {{ dayjs(room.updatedAt).format('lll') }}
        </div>
      </div>

      <button
        v-if="room.type === RoomType.Group && settings.showLeaveRoomButton"
        class="w-full rounded-lg border border-gray-200 p-2 text-gray-500 hover:bg-gray-50 dark:border-zinc-700 dark:text-gray-300 dark:hover:bg-zinc-700"
        @click="
          store.dispatch('imkit/removeMembers', {
            roomId: room.id,
            uids: [uid]
          })
        "
      >
        {{ $t('leaveGroup') }}
      </button>
      <iframe
        v-if="showCustomRoomInfoIframe"
        :src="customRoomInfoIframeURL"
        frameborder="0"
      />
    </div>
  </div>
</template>

<style scoped></style>
