import { sha1 } from 'hash-wasm'
type IMImage = {
  id: string
  width: number
  height: number
  thumbnailUrl: string
  originalUrl: string
}
export const file2image = (file: File): Promise<IMImage> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => {
      const image = new Image()
      image.src = reader.result as string
      image.onload = async () => {
        resolve({
          id: await sha1(image.src),
          width: image.width,
          height: image.height,
          thumbnailUrl: image.src,
          originalUrl: image.src
        })
      }
      image.onerror = () => reject
    }
    reader.onerror = () => {
      reject(reader.error)
    }
    reader.readAsDataURL(file)
  })
}
export default IMImage
