<template>
  <Dialog :open="dialogOpen" @update:open="handleOpenChange">
    <DialogContent
      class="flex h-dvh w-dvw max-w-none flex-col !rounded-none !bg-[#000] !p-3 md:h-[90vh] md:max-w-5xl md:!rounded-lg md:!p-0"
      :hide-close="true"
    >
      <div
        data-id="content-lightbox-dialog-header"
        class="flex shrink-0 items-baseline justify-between px-2 py-2 md:rounded-t-lg md:px-4 md:py-3"
      >
        <template v-if="showDownload">
          <Loader2
            v-if="downloadLoading"
            class="h-5 w-5 animate-spin text-white"
          />
          <Download
            v-else
            class="h-5 w-5 cursor-pointer text-white"
            @click="handleDownload"
          />
        </template>
        <div v-else class="h-5 w-5" />
        <div v-if="showHeader" class="flex-1 text-center">
          <div class="text-muted-foreground space-y-0.5 text-xs">
            <div>{{ senderName }}</div>
            <div>{{ dayjs(createdAt).format('YYYY-MM-DD') }}</div>
          </div>
        </div>
        <div v-else class="flex-1" />
        <DialogClose
          class="cursor-pointer text-white opacity-70 transition-opacity hover:opacity-100"
        >
          <X class="h-5 w-5" />
        </DialogClose>
      </div>
      <div
        data-id="content-lightbox-dialog-content"
        class="relative flex min-h-0 flex-1 flex-col overflow-hidden md:rounded-b-lg"
      >
        <div class="flex h-full flex-1 items-center justify-center bg-black/95">
          <!-- ChatRoomContent mode (presigned URL) -->
          <template v-if="isRoomContentMode">
            <template
              v-if="
                selectedMedia &&
                selectedMedia.fileType === 'image' &&
                presignedUrl
              "
            >
              <img
                :src="presignedUrl"
                :alt="$t('image')"
                class="h-auto max-h-[85vh] object-contain md:max-h-[75vh]"
              />
            </template>
            <template v-else>
              <video
                v-if="selectedMedia && presignedUrl"
                :src="presignedUrl"
                controls
                class="h-auto max-h-[85vh] w-auto max-w-full md:max-h-[75vh]"
                autoplay
              />
            </template>
          </template>

          <!-- IMImage mode -->
          <template v-else-if="isImageMode && image">
            <!-- Thumbnail: shown only while original is still loading -->
            <img
              v-if="
                !originalImageLoaded && image.thumbnailUrl !== image.originalUrl
              "
              v-src="image.thumbnailUrl"
              data-id="thumbnail-url"
              class="h-auto max-h-[85vh] w-full max-w-[95vw] object-contain md:max-h-[75vh] md:max-w-[90vw]"
              alt=""
            />
            <!-- Original image (or same as thumbnail when URLs match) -->
            <img
              v-src="image.originalUrl"
              data-id="original-url"
              class="h-auto max-h-[85vh] w-full max-w-[95vw] object-contain md:max-h-[75vh] md:max-w-[90vw]"
              :class="{
                'invisible absolute':
                  !originalImageLoaded &&
                  image.thumbnailUrl !== image.originalUrl
              }"
              alt=""
              @load="originalImageLoaded = true"
            />
            <template
              v-if="
                (!downloadProgresses[image.originalUrl] ||
                  downloadProgresses[image.originalUrl] < 1) &&
                image.thumbnailUrl !== image.originalUrl &&
                !originalImageLoaded
              "
            >
              <div class="absolute inset-0 bg-gray-800/50" />
              <RadialProgress
                class="absolute!"
                :diameter="40"
                :completed-steps="downloadProgresses[image.originalUrl] * 100"
                :total-steps="100"
                :start-color="'#60a5fa'"
                :stop-color="'#60a5fa'"
                :stroke-width="4"
                :inner-stroke-width="4"
              />
            </template>
          </template>

          <!-- IMVideo mode -->
          <template v-else-if="isVideoMode && video">
            <template v-if="videoLoading">
              <div class="flex h-[50vh] items-center justify-center">
                <Loader2 class="h-10 w-10 animate-spin text-white" />
              </div>
            </template>
            <template v-else-if="videoUrl">
              <video
                :src="videoUrl"
                class="h-auto max-h-[85vh] w-auto max-w-full md:max-h-[75vh]"
                controls
                autoplay
              />
            </template>
          </template>

          <!-- Direct video URL mode (local file preview) -->
          <template v-else-if="isDirectVideoMode && directVideoUrl">
            <video
              :src="directVideoUrl"
              class="h-auto max-h-[85vh] w-auto max-w-full md:max-h-[75vh]"
              controls
              autoplay
            />
          </template>
        </div>

        <!-- Navigation arrows -->
        <div
          class="pointer-events-none absolute inset-x-0 top-1/2 flex -translate-y-1/2 justify-between px-2 md:px-4"
        >
          <button
            v-if="mediaCount > 1"
            class="!hover:text-[#2B5CE6] pointer-events-auto inline-flex h-10 w-10 cursor-pointer items-center justify-center gap-2 !rounded-full rounded-md bg-black/50 text-base font-medium whitespace-nowrap text-white hover:bg-black/70"
            @click="previousMedia"
          >
            <ChevronLeft class="h-7 w-7" />
          </button>
          <button
            v-if="mediaCount > 1"
            class="!hover:text-[#2B5CE6] pointer-events-auto inline-flex h-10 w-10 cursor-pointer items-center justify-center gap-2 !rounded-full rounded-md bg-black/50 text-base font-medium whitespace-nowrap text-white hover:bg-black/70"
            @click="nextMedia"
          >
            <ChevronRight class="h-7 w-7" />
          </button>
        </div>
      </div>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import dayjs from 'dayjs'
import {
  ChevronLeft,
  ChevronRight,
  Download,
  Loader2,
  X
} from 'lucide-vue-next'
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import RadialProgress from 'vue3-radial-progress'
import { useStore } from 'vuex'
import ChatRoomContent from '../../classes/chatRoomContent'
import IMImage from '../../classes/image'
import IMVideo from '../../classes/video'
import {
  MIME_TYPES,
  useMediaDownload
} from '../../composables/useMediaDownload'
import { Dialog, DialogClose, DialogContent } from './dialog'

const store = useStore()
const { downloadProgresses, download } = useMediaDownload()

// Local loading state for download button (covers fetchSignedUrl + download)
const downloadLoading = ref(false)

defineOptions({
  name: 'ContentLightboxDialog'
})

const props = withDefaults(
  defineProps<{
    open?: boolean
    // ChatRoomContent mode
    selectedMedia?: ChatRoomContent | null
    previousMedia?: () => void
    nextMedia?: () => void
    mediaCount?: number
    // IMImage/IMVideo mode
    image?: IMImage | null
    video?: IMVideo | null
    // Direct video URL mode (for local file preview)
    directVideoUrl?: string | null
    // Room ID for fetching signed URL (used in IMImage/IMVideo mode)
    roomId?: string | null
    // Header info (used in all modes)
    senderName?: string | null
    createdAt?: string | number | null
    // UI options
    showDownload?: boolean
  }>(),
  {
    open: false,
    selectedMedia: null,
    previousMedia: () => {},
    nextMedia: () => {},
    mediaCount: 0,
    image: null,
    video: null,
    directVideoUrl: null,
    roomId: null,
    senderName: null,
    createdAt: null,
    showDownload: true
  }
)

const emit = defineEmits<{
  (e: 'update:open', value: boolean): void
  (e: 'close'): void
}>()

// Mode detection
const isRoomContentMode = computed(() => Boolean(props.selectedMedia))
const isImageMode = computed(() => Boolean(props.image))
const isVideoMode = computed(() => Boolean(props.video))
const isDirectVideoMode = computed(() => Boolean(props.directVideoUrl))
const showHeader = computed(
  () => isRoomContentMode.value || Boolean(props.senderName)
)

// ChatRoomContent mode state
const presignedUrl = ref<string | null>(null)
const dialogOpen = computed(() => props.open)

// IMImage mode state
const originalImageLoaded = ref(false)

// IMVideo mode state
const videoUrl = ref<string | null>(null)
const videoLoading = ref(false)

const handleOpenChange = (value: boolean) => {
  emit('update:open', value)
  if (!value) {
    emit('close')
    // Cleanup video blob URL
    if (videoUrl.value) {
      URL.revokeObjectURL(videoUrl.value)
      videoUrl.value = null
    }
  }
}

// ChatRoomContent: fetch presigned URL
const fetchPresigned = async () => {
  const media = props.selectedMedia
  if (!media) return
  const currentId = media._id
  try {
    const url = await store.dispatch('imkit/fetchPresignedUrl', {
      bucketName: media.room || '',
      fileId: media._id || ''
    })
    // Check if media changed during async operation
    if (props.selectedMedia?._id !== currentId) return
    presignedUrl.value = (url as string) || null
  } catch (err) {
    console.error('[Lightbox] fetchPresignedUrl error:', err)
    if (props.selectedMedia?._id === currentId) {
      presignedUrl.value = null
    }
  }
}

// IMVideo: load video blob
const loadVideo = async () => {
  const video = props.video
  if (!video || videoUrl.value) return
  const currentId = video.id
  videoLoading.value = true
  try {
    const blob = await store.dispatch('imkit/fetchVideoBlob', video.originalUrl)
    // Check if video changed during async operation
    if (props.video?.id !== currentId) return
    videoUrl.value = URL.createObjectURL(blob)
  } catch (error) {
    console.error('[Lightbox] loadVideo error:', error)
  } finally {
    if (props.video?.id === currentId) {
      videoLoading.value = false
    }
  }
}

// Extract file ID from URL (last segment after the last '/', excluding query string)
const extractFileIdFromUrl = (url: string): string | null => {
  try {
    // Remove query string first for safety
    const urlWithoutQuery = url.split('?')[0]
    const pathParts = urlWithoutQuery.split('/').filter(Boolean)
    return pathParts.length > 0 ? pathParts[pathParts.length - 1] : null
  } catch {
    return null
  }
}

// Fetch signed URL for IMImage/IMVideo mode
const fetchSignedUrl = async (originalUrl: string): Promise<string | null> => {
  if (!props.roomId) return null
  const fileId = extractFileIdFromUrl(originalUrl)
  if (!fileId) return null
  try {
    const url = await store.dispatch('imkit/fetchPresignedUrl', {
      bucketName: props.roomId,
      fileId
    })
    return (url as string) || null
  } catch (err) {
    console.error('[Lightbox] fetchSignedUrl error:', err)
    return null
  }
}

// Download handler
const handleDownload = async () => {
  if (downloadLoading.value) return
  downloadLoading.value = true

  try {
    if (isRoomContentMode.value && props.selectedMedia && presignedUrl.value) {
      const isImage = props.selectedMedia.fileType === 'image'
      const url = String(presignedUrl.value).split('?')[0]
      const signedUrl = await fetchSignedUrl(url)
      download({
        url,
        fileName: props.selectedMedia.originalName,
        fallbackId: props.selectedMedia._id,
        mimeType:
          props.selectedMedia.mimetype ||
          (isImage ? MIME_TYPES.IMAGE_JPEG : MIME_TYPES.VIDEO_MP4),
        useSignedUrl: true,
        signedUrl: signedUrl || undefined
      })
    } else if (isImageMode.value && props.image) {
      // Fetch signed URL for image download (needed for cross-origin/iframe)
      const signedUrl = await fetchSignedUrl(props.image.originalUrl)
      download({
        url: props.image.originalUrl,
        fallbackId: props.image.id,
        mimeType: MIME_TYPES.IMAGE_JPEG,
        useSignedUrl: true,
        signedUrl: signedUrl || undefined
      })
    } else if (isVideoMode.value && props.video) {
      // Fetch signed URL for video download
      const signedUrl = await fetchSignedUrl(props.video.originalUrl)
      download({
        url: props.video.originalUrl,
        fallbackId: props.video.id,
        mimeType: MIME_TYPES.VIDEO_MP4,
        useSignedUrl: true,
        signedUrl: signedUrl || undefined
      })
    }
  } finally {
    downloadLoading.value = false
  }
}

// Watch for open state changes
watch(
  [() => props.open, () => props.selectedMedia, () => props.video],
  ([open, media, video]) => {
    if (open) {
      originalImageLoaded.value = false
      if (media) {
        fetchPresigned()
      } else if (video) {
        loadVideo()
      }
    } else {
      presignedUrl.value = null
      originalImageLoaded.value = false
      if (videoUrl.value) {
        URL.revokeObjectURL(videoUrl.value)
        videoUrl.value = null
      }
    }
  },
  { immediate: true }
)

const handleKeydown = (event: KeyboardEvent) => {
  if (!props.open) return

  if (event.key === 'ArrowLeft') {
    event.preventDefault()
    previousMedia()
  } else if (event.key === 'ArrowRight') {
    event.preventDefault()
    nextMedia()
  }
}

onMounted(() => {
  window.addEventListener('keydown', handleKeydown)
})

onUnmounted(() => {
  window.removeEventListener('keydown', handleKeydown)
  // Cleanup video blob URL on unmount
  if (videoUrl.value) {
    URL.revokeObjectURL(videoUrl.value)
  }
})

const previousMedia = () => props.previousMedia && props.previousMedia()
const nextMedia = () => props.nextMedia && props.nextMedia()
</script>
