import MessageLinkedList from './messageLinkedList'

export default class MessageMultiList {
  head: MessageLinkedList | null
  tail: MessageLinkedList | null
  main: MessageLinkedList | null
  length: number

  constructor(linkedList: MessageLinkedList | null = null) {
    this.head = linkedList
    this.tail = linkedList
    this.main = linkedList
    this.length = linkedList ? 1 : 0
  }

  numberOfMessages(): number {
    let count = 0
    let current = this.head
    while (current) {
      count += current.length
      current = current.next
    }
    return count
  }

  concate(linkedList: MessageLinkedList) {
    this.main?.concate(linkedList)
  }

  unshift(linkedList: MessageLinkedList) {
    this.main?.unshift(linkedList)
  }

  insert(linkedList: MessageLinkedList) {
    if (this.length === 0) {
      this.head = this.tail = this.main = linkedList
      this.length = 1
      return
    }
    if (linkedList.length === 0) return
    let current: MessageLinkedList | null = this.tail
    while (current && current.head!.createdAt > linkedList.head!.createdAt) {
      current = current.prev
    }
    if (current) {
      if (current === this.tail) {
        this.tail = linkedList
      }
      linkedList.next = current.next
      if (linkedList.next) {
        linkedList.next.prev = linkedList
      }
      current.next = linkedList
      linkedList.prev = current
    } else {
      linkedList.next = this.head
      if (linkedList.next) {
        linkedList.next.prev = linkedList
      }
      this.head = linkedList
    }
    this.main = linkedList
    this.length++
  }

  merge() {
    if (this.length <= 1) return
    let current: MessageLinkedList | null = this.tail
    while (current) {
      if (current.prev && current.canCombine(current.prev)) {
        current.combine(current.prev)
        if (current.prev === this.main) {
          this.main = current
        }
        current.prev = current.prev.prev
        if (current.prev) {
          current.prev.next = current
        } else {
          this.head = current
        }
        this.length--
        break
      }
      current = current.prev
    }
    if (current) {
      this.merge()
    }
  }

  isValid() {
    if (this.head && this.head.prev) {
      return false
    }
    if (this.tail && this.tail.next) {
      return false
    }
    let length = 0
    let current = this.head
    while (current) {
      if (current.prev && current.prev.next !== current) {
        return false
      }
      if (current.next && current.next.prev !== current) {
        return false
      }
      length++
      current = current.next
    }
    return length === this.length
  }
}
