<script setup lang="ts">
import { computed } from 'vue'
import { StickerMessage } from './../classes/message'
const props = defineProps<{ message: StickerMessage }>()
const src = computed(() => {
  if (props.message.stickerUrl) {
    return props.message.stickerUrl
  }
  return `/sticker/${props.message.stickerId.split('-')[0]}/${
    props.message.stickerId
  }.png`
})
</script>

<template>
  <img :src="src" class="h-32 w-32 border-0 object-contain" />
</template>

<style scoped></style>
